/*
 * Чимун апп — автомат тест (гуравдагч сангүй, Node built-in vm).
 * Ажиллуулах:  node test/run.js
 *
 * Апп нэг том browser-файл тул: browser-ийн globals (document/localStorage/fetch...)-ийг
 * хуурамчаар (mock) өгч, app.js-г тусгаарлагдсан vm контекстэд ачаална. Дараа тухайн
 * контекстээс ЦЭВЭР функцуудыг (мөнгө/токены логик, DOM-гүй) аваад шалгана.
 * UI (товч дарах) тест ХИЙХГҮЙ — зөвхөн тооцоо/задлан авах логик.
 */
'use strict';
// Ирээдүйн огноо — тестийг огноогоор хуучрахаас хамгаална (2026-09-27).
function _soon(n) { const d = new Date(); d.setDate(d.getDate() + Number(n || 0));
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
const fs = require('fs');
const path = require('path');
const vm = require('vm');

// ── browser globals mock (app.js ачаалах үед унахгүй байх хамгийн бага орчин) ──
function stubEl() {
  const el = {
    style: {}, dataset: {}, children: [], parentNode: null,
    classList: { add() {}, remove() {}, toggle() {}, contains() { return false; } },
    addEventListener() {}, removeEventListener() {}, appendChild() {}, removeChild() {}, remove() {},
    setAttribute() {}, removeAttribute() {}, getAttribute() { return null; },
    querySelector() { return stubEl(); }, querySelectorAll() { return []; },
    insertAdjacentHTML() {}, focus() {}, blur() {}, click() {}, scrollIntoView() {},
    closest() { return null; }, matches() { return false; }, hasAttribute() { return false; },
    innerHTML: '', textContent: '', value: '', checked: false, disabled: false,
  };
  return el;
}
const _store = {};
const localStorage = {
  getItem(k) { return Object.prototype.hasOwnProperty.call(_store, k) ? _store[k] : null; },
  setItem(k, v) { _store[k] = String(v); }, removeItem(k) { delete _store[k]; }, clear() { for (const k in _store) delete _store[k]; },
};
const documentMock = {
  getElementById() { return stubEl(); }, querySelector() { return stubEl(); }, querySelectorAll() { return []; },
  createElement() { return stubEl(); }, createElementNS() { return stubEl(); },
  addEventListener() {}, removeEventListener() {}, body: stubEl(), head: stubEl(), documentElement: stubEl(),
  cookie: '', title: '', readyState: 'complete', visibilityState: 'visible',
};
const noopFetch = () => Promise.resolve({ ok: false, status: 0, json: () => Promise.resolve({}), text: () => Promise.resolve('') });

const sandbox = {
  console, setTimeout, clearTimeout, setInterval, clearInterval, Date, Math, JSON, Promise,
  Array, Object, String, Number, Boolean, RegExp, Error, Map, Set, Symbol, parseInt, parseFloat,
  isNaN, isFinite, encodeURIComponent, decodeURIComponent, Buffer, atob: (s) => Buffer.from(s, 'base64').toString('binary'), btoa: (s) => Buffer.from(s, 'binary').toString('base64'),
  document: documentMock, localStorage, sessionStorage: localStorage,
  fetch: noopFetch, navigator: { userAgent: 'node', serviceWorker: { register: noopFetch, getRegistrations: () => Promise.resolve([]) }, onLine: true },
  location: { href: 'https://test/', search: '', hash: '', pathname: '/', reload() {}, replace() {}, assign() {} },
  crypto: { randomUUID: () => 'test-uuid', getRandomValues: (a) => a },
  caches: { open: () => Promise.resolve({ addAll: noopFetch, put: noopFetch, match: noopFetch }), keys: () => Promise.resolve([]), match: noopFetch },
  Notification: function () {}, alert() {}, confirm() { return false; }, prompt() { return null; },
  requestAnimationFrame: (cb) => setTimeout(cb, 0), cancelAnimationFrame: () => {},
  matchMedia: () => ({ matches: false, addEventListener() {}, addListener() {} }),
  URL, URLSearchParams, TextEncoder, TextDecoder, FileReader: function () {}, Blob: function () {}, FormData: function () {},
  AbortController, AbortSignal,
};
sandbox.window = sandbox;
sandbox.self = sandbox;
sandbox.globalThis = sandbox;
sandbox.window.addEventListener = () => {};
sandbox.window.matchMedia = sandbox.matchMedia;

const src = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
vm.createContext(sandbox);
try {
  vm.runInContext(src, sandbox, { filename: 'app.js' });
} catch (e) {
  console.error('❌ app.js ачаалахад алдаа:', e.message);
  process.exit(1);
}

// ── жижиг assert helper ──
let passed = 0, failed = 0;
const fails = [];
function eq(actual, expected, name) {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a === e) { passed++; }
  else { failed++; fails.push(`  🔴 ${name}\n     хүлээсэн: ${e}\n     гарсан:   ${a}`); }
}
function ok(cond, name) { if (cond) passed++; else { failed++; fails.push(`  🔴 ${name}`); } }

// функцуудыг контекстээс авах
const F = sandbox;
function need(names) { const miss = names.filter(n => typeof F[n] !== 'function'); if (miss.length) { console.error('❌ функц олдсонгүй:', miss.join(', ')); process.exit(1); } }
need(['parseVat', 'encodeVat', 'custInfoOf', 'setCustInfo', 'parsePaidRef', 'parseDelivery', 'encodeDelivery', 'cleanAppNote', 'receiptFingerprint', 'parseBankReceipt', 'mapsHref', 'parseOrderTimes', 'encodeOrderTimes',
  'rentalDiscount', 'rentalDays', 'orderRentalDays', 'salaryNet', 'salaryNextYm', 'vatNum', 'vatNorm', 'vatDateIso', 'vatRegNorm', 'vatNameMatch', 'vatAutoScore', 'vatIsReturned', 'vatActive', 'vatDetectReturned', 'parseVatReportMatrix', 'vatReportRecon', 'vatReportReconHtml', 'claimCanResolve', 'stageMetaHtml', 'vatIsAggregate', 'vatIssuedDay', '_rangesOverlap', 'fmtMoney', 'fmtMoneyShort', 'meventContractHtml', 'ctTierText', 'tariffWorkStart', 'tariffWorkEnd', 'attMemberSummary', 'attAggregateMonth', 'attWorkedLine', 'buildReconAiPayload', 'applyReconAiSuggestions', '_isInternalCredit', 'reconcileOrders', 'parsePaidRef', 'receiptTooOld', 'statementMeta', 'reconcileByReceipts', 'receiptFingerprint', 'reconReceiptOwnerLabel', 'driverBonus', 'monthPayBreakdown', 'monthWorkdays', 'workNormDays', 'workNormMins', 'payMonthDefault', 'payMonthMins', 'payrollHistOnly', 'payrollStartMonth', 'lunchCfg', 'overtimeRate', 'salaryPaymentsFor', 'salaryFinPayments', 'payBalance', 'incomeRelinkPlan', 'pbxPeerTimeline', 'pbxTimelineHtml', 'pbxTime', 'cateringRevenue', 'cateringIncomeMonth', 'cateringOwed', 'cateringMonthIncome', 'cateringHasMoney', 'jrnCateringList', 'jrnCreditFor', 'incomeStatusOfOwner', 'incomeLinkOfOwner', 'renderCatering', 'finMonthIncome', 'finAddOrderIncome', 'journalEntries', 'empAcctOwners', 'empAcctsForPerson', 'acctSame', 'empNameFullKey', 'salaryIsLoan', 'salaryPayLabel', 'salaryPaidFor', 'salaryPayMonth', 'salaryPayFp', 'salaryFinSource', 'payrollRoster', 'payrollOrphans', 'payrollAttMins', 'finIsRealExpense', 'stageFeeForQty', 'orderItemQty', 'stagePayByPerson', 'orderStagesOnDay', 'defectStats', 'pipelineSteps', 'pendingStageClaims', 'stageClaims', 'stageHasPerson', 'stageLabel', 'stageLabelKey', 'stageHistLabel', 'offHoursSpan', 'orderOffHoursCount', 'lateOffHoursFee', 'orderLateFee', 'orderOffHoursFee', 'handoffQualityScore', 'stageDefs', 'stageEvidence', 'stagePtsForQty', 'stageWeight', 'stagePointRate', 'pipelineNext', 'orderPipelineCtx', 'dayLoadForecast', 'missingItemsCost', 'fmtDateTimeUB', 'isDateOnlyStamp', 'countShrinkCost', 'offHoursFeeFor', 'orderOffHoursFeeOf', 'tariffOffhoursFirstFee',
  'finIsDepositReturn', 'encodeSetup', 'setupFlagOf', 'setupFeeOf', 'setupFeeForItems', 'setupRateForName', 'setupUnitFee', 'cooShareAmount', 'quoteDiscountFromTotal', '_histCompute', 'isOrderAutoTask', '_nomaadMonthSum', 'orderDiscountAmount', 'orderMoneyBreakdown', 'calcDeliveryFee', 'tariffOffhoursFee', 'tariffDeliveryCity', 'tariffDeliveryCityOne', 'isDeliveryZone', 'tariffPerKm', 'parseRefund', 'encodeRefundNote', 'productUtilization', 'errStatusLabel', 'productStockByName', 'availabilityFor', 'orderShortages', 'stripFormTokens', 'canProductPart', 'canEditProducts', 'canEditAnyProductPart', 'openingRows', 'openingStats', 'stockOpened', 'stockCounted', 'stockApproved', 'openingSignState', 'openingSignBlock', 'canApproveOpening', 'productPartFields', 'restrictProductEdit', 'warehouseCapital', 'orderMailKind', 'orderReview', 'histDayList', 'histFilterOrders', '_histCompute', 'packageSplit', '_histCatResolver', 'countRowPerson', 'scQuarterOf', 'scSessionLabel', 'scNewSessionId', 'scNormalizeConfig', 'scAllSessionIds', 'openingSealGroups', 'openingBeforeAfter', 'scBranchOfSession', 'scPrimaryBranch', 'scInBranch', 'applyStockCount', 'countRowState', 'countMergeProducts', 'countFilterList',
  'parseStatement', 'expenseFp', 'salaryBranchOf', 'fpAlreadyImported', 'isInternalTransfer',
  'attManualOutTs', 'attManualOutCheck', 'attReqValidate', 'attReqKey', 'attReqPrune', 'attReqApprovalCheck',
  'unknownPersonRefs', 'personNameFix', 'catListFromGroups', 'catOrphans', 'catRenamePlan', 'writeOffBranchPatch', 'countDamage', 'countDamageNote', 'nextMonthStr', '_histItemResolver',
  'ownerCapital', 'ownerCapitalRows', 'openingBalanceCalc', 'journalEntries', 'journalTotals', 'jrnDebitFor', 'jrnCreditFor', 'ledgerLines', 'balanceSheetAt', 'entriesUpTo', 'incomeStatement', 'entriesBetween', 'jrnMonthEnd', 'deprecYearsFor', 'deprecByBranch', 'deprecForMonth', 'deprecLives', 'deprecStartMonth', 'finBranchPnl', 'deprecForProduct']);

// ═══════════════════ ТЕСТҮҮД ═══════════════════

// 0f) productUtilization — ROI-ийн эх сурвалж (2026-09-04)
// Регресс: өмнө нь `state.orders`-оос уншдаг байсан. Тэр массив нэг л удаа `[]` гэж
// оноогдоод хэзээ ч бичигддэггүй байсан → БҮХ барааны ROI 0% харагдаж, CEO хөрөнгийн
// шийдвэрээ буруу тоон дээр гаргаж байв. (`state.orders` өөрөө устсан — 0g-г үз.)
// Мөн: booqable түүхэн мөрийн price нь ХУГАЦААНЫ НИЙТ, аппынх нь ӨДРИЙН үнэ.
{
  const runIn = (code) => vm.runInContext(code, sandbox);
  const save = runIn('[state.products, state.appOrders]');
  runIn("state.products = [{ id:'M-900', sku:'M-900', name:'Тест ширээ', price:10000, qty_mevent:10, stock:10 }];");
  runIn(`state.appOrders = [
    { number:1, source:'app',      status:'rented',    starts_at:'2026-10-01', stops_at:'2026-10-04', items:[{sku:'M-900', name:'Тест ширээ', qty:2, price:10000}] },
    { number:2, source:'booqable', status:'done',      starts_at:'2026-09-01', stops_at:'2026-09-11', items:[{sku:'M-900', name:'Тест ширээ', qty:1, price:50000}] },
    { number:3, source:'app',      status:'cancelled', starts_at:'2026-10-01', stops_at:'2026-10-04', items:[{sku:'M-900', name:'Тест ширээ', qty:9, price:10000}] }
  ];`);
  const u = runIn('productUtilization')('Тест ширээ');
  ok(u.orders === 2, 'ROI: цуцалсан захиалга тоологдохгүй (2 захиалга)');
  ok(u.qty === 3, 'ROI: тоо ширхэг = 2 + 1 (цуцалсан 9 ороогүй)');
  // app: 10000 × 2 × 3 хоног = 60,000 · booqable: 50000 × 1 × 1 (НИЙТ дүн, үржүүлэхгүй) = 50,000
  ok(u.revenue === 110000, 'ROI: app хоногоор, booqable нийт дүнгээр — ' + u.revenue);

  ok(u.revenue > 0, 'ROI: орлого 0 БИШ (амьд эх сурвалжаас уншина)');

  // ГАЦАЛТЫН ХАМГААЛАЛТ (2026-09-04, амьдаар тохиолдсон): энэ функц бараа МӨР
  // БҮРД дуудагдана (294 удаа). Дуудалт бүрд захиалгыг дахин гүйвэл
  // O(бараа × захиалга × мөр) болж «Бараа & хөрөнгө» дэлгэц НЭЭГДЭХЭЭ болино.
  // Индекс НЭГ УДАА баригдаж, дараагийн дуудалтууд түүнийг л уншина.
  runIn('state._utilIdx = null;');
  runIn('productUtilization')('Тест ширээ');
  const idx1 = runIn('state._utilIdx');
  ok(!!idx1, 'ашиглалт: индекс баригдав');
  for (let i = 0; i < 300; i++) runIn('productUtilization')('Тест ширээ');
  ok(runIn('state._utilIdx') === idx1, 'ашиглалт: 300 дуудалтад индекс ДАХИН баригдахгүй (гацалтын хамгаалалт)');

  runIn('state.products = ' + JSON.stringify(save[0] || []) + '; state.appOrders = ' + JSON.stringify(save[1] || []) + ';');
}

// 0e) SCAN — түүхий UTC огноо БАЙХГҮЙ (2026-09-04)
// `x.toISOString().slice(0,10)` нь UTC огноо буцаана. Монгол UTC+8 тул 00:00-08:00
// хооронд НЭГ ӨДРӨӨР хоцордог: сарын 1-нд цалин/гүйцэтгэл өмнөх сарыг үзүүлнэ,
// «Хоцорсон» тооллого буруу гарна. Зөвшөөрөгдөх цорын ганц хэлбэр нь
// getTimezoneOffset()-оор тохируулсан нь (todayStr/dateStr/addDays-ийн дотоод).
// Шинэ код: todayStr() · dateStr(d) · monthStr(d) · addDays(s, n) ашиглана.
{
  // Тайлбар мөрүүдэд тэр хэв маягийг ЗОРИУД бичсэн (яагаад болохгүйг тайлбарлахын тулд)
  // тул код мөрүүдийг л шалгана.
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const all = (codeLines.match(/toISOString\(\)\.slice\(0, ?(?:10|7)\)/g) || []).length;
  const safe = (codeLines.match(/getTimezoneOffset\(\) \* 60000\)\.toISOString\(\)\.slice\(0, ?(?:10|7)\)/g) || []).length;
  eq(all - safe, 0, 'scan: түүхий UTC огноо байхгүй (todayStr/dateStr/monthStr ашигла)');
}

// 0e2) SCAN — ирцийн хүсэлт `app_config`-д БУЦАХГҮЙ (2026-09-18)
// Хүсэлтүүд нэг JSON blob-д байхад: зэрэг бичилт бие биенээ дарна, `app_config`
// нэвтэрсэн бүх ажилтанд уншигддаг тул хүн бусдын хүсэлт/тайлбарыг харна, 120
// хоногийн дараа шийдэгдсэн хүсэлт бүрмөсөн хасагдаж «хэн батлав» гэдэг алга
// болно. Одоо `att_requests` хүснэгт (мөр бүр өөрийн эрхтэй).
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  eq((codeLines.match(/AppConfig\('att_requests'/g) || []).length, 0,
     'scan: ирцийн хүсэлт app_config-оор уншиж/бичихгүй (att_requests хүснэгт)');
  ok(/rest\/v1\/att_requests\?on_conflict=id/.test(codeLines),
     'scan: хүсэлт нэг мөрөөр upsert хийгдэнэ');
  ok(/status\.eq\.pending/.test(codeLines),
     'scan: хүлээгдэж буй хүсэлт огнооны шүүлтээс үл хамааран татагдана');
}

/* ═══ ⛔ ХААСАН САРЫН ЭЛЭГДЭЛ ХӨЛДӨНӨ (2026-10-02) ═══
   `deprecByBranch` нь ОДООГИЙН нөөцөөс бодогддог бөгөөд `month` нь зөвхөн
   асаах/унтраах үүрэгтэй байв. Сар хаасны ДАРАА бараа салбар хооронд шилжихэд
   ХААСАН сарын элэгдэл → ашиг → COO-гийн 30% чимээгүй өөрчлөгддөг байв. */
{
  const DSO = vm.runInContext('deprecSnapshotOf', sandbox);
  const DFM = vm.runInContext('deprecForMonth', sandbox);
  const DSN = vm.runInContext('deprecSnapshotNow', sandbox);
  const st = vm.runInContext('state', sandbox);
  const savedCm = st.closedMonths, savedP = st.products;
  const prod = (q) => ([{ sku: 'A', name: 'Сандал', cost: 1200000, qty_mevent: q, qty_nomaad: 100 - q,
    purchase_date: '2026-09-01', archived: false, type: 'rental' }]);

  st.products = prod(100);
  const snap = DSN('2026-10');
  ok(snap && snap.total > 0, 'хөлдөөлт: хаахад зураг үүснэ');
  const mev0 = snap['ИВЕНТ'];
  ok(mev0 > 0 && snap['КЕМП'] === 0, 'хөлдөөлт: зураг нь салбарын хуваарилалтыг барина');

  // Сар ХААГДСАН + зурагтай → нөөц хөдөлсөн ч тоо ХЭВЭЭР
  st.closedMonths = { '2026-10': { at: '2026-11-01T00:00:00Z', by: 'x', dep: snap } };
  st.products = prod(0);   // БҮХ сандал NOMAAD руу шилжив
  eq(DFM('2026-10')['ИВЕНТ'], mev0, 'ХӨЛДӨӨЛТ: хаасны дараа нөөц шилжсэн ч хаасан сарын элэгдэл ХЭВЭЭР');
  eq(DFM('2026-10').frozen, true, 'хөлдөөлт: хаалттай сар «хөлдсөн» гэж тэмдэглэгдэнэ');
  ok(DSO('2026-10'), 'хөлдөөлт: зураг олдоно');

  // НЭЭЛТТЭЙ сар нь одоогийн нөөцөөс — шилжилт шууд тусна
  st.closedMonths = {};
  eq(DFM('2026-10')['ИВЕНТ'], 0, 'нээлттэй сар: нөөц шилжихэд элэгдэл шууд дагана');
  ok(!DFM('2026-10').frozen, 'нээлттэй сар хөлдөөгүй');

  /* ⚠ Зураггүй хаалттай сар (шилжилтийн хаалт, эсвэл энэ засвараас ӨМНӨ хаасан)
     нь хуучнаараа бодогдоно — тоог чимээгүй 0 болгохоос дээр. */
  st.closedMonths = { '2026-10': { at: '2026-11-01T00:00:00Z', by: 'x' } };
  st.products = prod(100);
  eq(DFM('2026-10')['ИВЕНТ'], mev0, 'зураггүй хаалттай сар: хуучнаар бодогдоно (0 болгохгүй)');
  eq(DSO('2026-10'), null, 'зураггүй сард зураг null');

  // Элэгдэл эхлэхээс ӨМНӨХ сард зураг авахгүй (утгагүй)
  eq(DSN('2026-08'), null, 'хөлдөөлт: элэгдэл идэвхгүй сард зураг авахгүй');
  st.closedMonths = savedCm; st.products = savedP;
}

/* 0e2h) SCAN — хаахад элэгдлийн зураг ЗААВАЛ авна (2026-10-02)
   Зураг авахгүй бол хаалттай сар одоогийн нөөцөөс дахин бодогдож, бараа салбар
   хооронд шилжих бүрд ХААСАН сарын ашиг ба COO-гийн 30% чимээгүй өөрчлөгдөнө —
   «хаасан сарын тоо хөдөлөхгүй» гэдэг гол дүрэм зөрчигдөнө. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function deprecSnapshotNow\(/.test(codeLines) && /function deprecSnapshotOf\(/.test(codeLines),
     'scan: элэгдлийн зургийн функцууд байна');
  ok(/const dep = deprecSnapshotNow\(m\);/.test(codeLines),
     'scan: сар хаахад элэгдлийн зураг авагдана');
  ok(/\.\.\.\(dep \? \{ dep \} : \{\}\)/.test(codeLines),
     'scan: зураг хаалтын бичлэгт хадгалагдана');
  const dm = codeLines.slice(codeLines.indexOf('function deprecForMonth'), codeLines.indexOf('function ensureProductsLoaded'));
  ok(/const snap = deprecSnapshotOf\(month\);/.test(dm),
     'scan: хаалттай сар зурагнаасаа уншина (одоогийн нөөцөөс БИШ)');
}

/* ═══ 🔒 ЭХНИЙ ҮЛДЭГДЭЛ — ГУРАВ ДАХЬ ГАРЫН ҮСЭГ (2026-10-02, CEO шийдвэр) ═══
   Нярав тоолно → ҮАХ захирал хянана → CEO эцэслэнэ → суурь ХӨЛДӨНӨ.
   Эцэслэсний дараа дахин тоолох/батлах/буцаах БОЛОМЖГҮЙ; залруулга зөвхөн
   тооллогоор (аудитын мөртэй). */
{
  const SB = vm.runInContext('openingSealBlock', sandbox);
  const SS = vm.runInContext('stockSealed', sandbox);
  const SIGN = vm.runInContext('openingSignBlock', sandbox);
  const UNDO = vm.runInContext('openingUndoBlock', sandbox);
  const mk = (o) => ({ sku: 'A', name: 'Сандал', stock_opened_at: o.c ? '2026-10-01T00:00:00Z' : null,
    stock_opened_by: o.cby || null, stock_approved_at: o.a ? '2026-10-01T01:00:00Z' : null,
    stock_approved_by: o.aby || null, stock_locked_at: o.s ? '2026-10-01T02:00:00Z' : null,
    stock_locked_by: o.sby || null });

  eq(SS(mk({ c: 1, a: 1 })), false, 'эцэслэл: батлагдсан ч эцэслээгүй');
  eq(SS(mk({ c: 1, a: 1, s: 1 })), true, 'эцэслэл: эцэслэгдсэн');

  // ── Дараалал: тоолох → батлах → эцэслэх ──
  ok(/нярав тоолно/i.test(SB(mk({}), 'ceo', true)), 'эцэслэл: тоолоогүй бол эхлээд нярав');
  ok(/ҮАХ захирал хянана/.test(SB(mk({ c: 1, cby: 'n' }), 'ceo', true)), 'эцэслэл: батлагдаагүй бол эхлээд захирал');
  eq(SB(mk({ c: 1, cby: 'n', a: 1, aby: 'alt' }), 'ceo', true), '', 'эцэслэл: гурав дахь хүн эцэслэж чадна');
  ok(/Зөвхөн CEO/.test(SB(mk({ c: 1, cby: 'n', a: 1, aby: 'alt' }), 'alt', false)), 'эцэслэл: зөвхөн CEO');

  /* ⛔ ГУРВАН ӨӨР ХҮН — нэг хүн хоёр үүрэг гүйцэтгэвэл гурван гарын үсэг нэг
     болж хумигдана (хоёр гарын үсгийн дүрэмтэй ижил зарчим). */
  ok(/Та тоолсон/.test(SB(mk({ c: 1, cby: 'ceo', a: 1, aby: 'alt' }), 'ceo', true)),
     'эцэслэл: тоолсон хүн эцэслэж чадахгүй');
  ok(/Та хянасан/.test(SB(mk({ c: 1, cby: 'n', a: 1, aby: 'ceo' }), 'ceo', true)),
     'эцэслэл: хянасан хүн эцэслэж чадахгүй');
  ok(/Аль хэдийн/.test(SB(mk({ c: 1, cby: 'n', a: 1, aby: 'alt', s: 1 }), 'ceo', true)),
     'эцэслэл: давхар эцэслэхгүй');

  /* ⛔ ХӨЛДСӨНИЙ ДАРАА БҮХ ЗАМ ХААЛТТАЙ — дахин батлах ч, буцаах ч боломжгүй. */
  const sealed = mk({ c: 1, cby: 'n', a: 1, aby: 'alt', s: 1, sby: 'ceo' });
  ok(/өөрчлөх боломжгүй/.test(SIGN(sealed, 'alt', true)), 'хөлдөөлт: дахин батлах зам хаалттай');
  ok(/буцаах боломжгүй/.test(UNDO(sealed, 'alt', true, 'approve')), 'хөлдөөлт: батлалт буцаах зам хаалттай');
  ok(/буцаах боломжгүй/.test(UNDO(sealed, 'alt', true, 'count')), 'хөлдөөлт: тоолол буцаах зам ч хаалттай');
  // ⚠ Хөлдөөгүй бол хуучнаараа ажиллана
  eq(UNDO(mk({ c: 1, cby: 'n', a: 1, aby: 'alt' }), 'alt', true, 'approve'), '',
     'хөлдөөгүй бол буцаах зам нээлттэй хэвээр');
}

/* ═══ ⛔ CEO-гийн ШҮХЭР ҮҮРЭГ ТУСГААРЛАЛТЫГ ЗАДАЛДАГ (2026-10-02) ═══
   `capValue` нь CEO-д ҮРГЭЛЖ `true` буцаадаг. Иймд `canOpenCount` -ийг
   `capValue`-ээр бичихэд эрхийг нь хассан мөртөө CEO-д «Тоолсон» товч
   харагдсаар байв — амьд дэлгэцээс барив.
   ⚠ Scan-тест нь ДҮРСИЙГ шалгадаг (функцийн биед `state.isCEO` байхгүй) тул
     үүнийг БАРЬЖ ЧАДААГҮЙ — зан чанарын тест заавал хэрэгтэй. */
{
  const st = vm.runInContext('state', sandbox);
  const COC = vm.runInContext('canOpenCount', sandbox);
  const CAO = vm.runInContext('canApproveOpening', sandbox);
  const CV = vm.runInContext('capValue', sandbox);
  const saved = { ceo: st.isCEO, me: st.me, mp: st.memberPerms, rp: st.rolePerms };
  st.memberPerms = {}; st.rolePerms = {};

  // ── CEO, ил олгосон эрхгүй → тоолох ч, хянах ч БОЛОХГҮЙ ──
  st.isCEO = true; st.me = '88006790';
  eq(COC(), false, 'ЗАН: CEO ил эрхгүй бол эхний үлдэгдэл ТООЛОХГҮЙ');
  eq(CAO(), false, 'ЗАН: CEO ил эрхгүй бол ХЯНАХГҮЙ');
  eq(CV('products.count'), true, 'ЗАН: харин capValue нь CEO-д true хэвээр (бусад эрхэд хэрэгтэй)');

  // ── Нярав: ил олгосон эрхтэй → тоолно, хянахгүй ──
  st.isCEO = false; st.me = '99285468';
  st.memberPerms = { '99285468': { 'products.count': true, 'products.opening': false } };
  eq([COC(), CAO()], [true, false], 'ЗАН: нярав тоолно, хянахгүй');

  // ── ҮАХ захирал: хянана, тоолохгүй ──
  st.me = '86657676';
  st.memberPerms = { '86657676': { 'products.opening': true, 'products.count': false } };
  eq([COC(), CAO()], [false, true], 'ЗАН: ҮАХ захирал хянана, тоолохгүй');

  /* ⚠ `products.edit` ШҮХЭР эдгээрийг НЭЭХГҮЙ — энэ нь анхны алдааны мөн чанар
     (амьд системд 5 хүн тоолж чаддаг байв). */
  st.me = 'x'; st.memberPerms = { x: { 'products.edit': true } };
  eq([COC(), CAO()], [false, false], 'ЗАН: products.edit шүхэр тоолох/хянах эрх ӨГӨХГҮЙ');

  st.isCEO = saved.ceo; st.me = saved.me; st.memberPerms = saved.mp; st.rolePerms = saved.rp;
}

/* 0e2j) SCAN — ГУРВАН АЛХАМ = ГУРВАН ӨӨР ЭРХ (2026-10-02, CEO барив)
   Өмнө нь ТООЛОХ нь `products.edit` шүхэр дор явдаг байсан тул амьд системд
   5 хүн (нярав 2, ҮАХ захирал, захиалгын ажилтан, дууны инженер) бүгд
   «Тоолсон» дарж чаддаг байв — гурван гарын үсэг нэг болж хумигдана.
   ⛔ CEO тоолох/хянах алхамд ОРОЛЦОХГҮЙ: эцэслэх нь зөвхөн CEO-гийнх бөгөөд
   «гурван өөр хүн» дүрэмтэй тул CEO тоолсон бараа ХЭЗЭЭ Ч эцэслэгдэхгүй болж
   мухардалд орно. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  /* ⛔ `capValue` БИШ `capResolved` — `capValue` нь CEO-д ҮРГЭЛЖ true буцаадаг
     тул үүрэг тусгаарлалт ажиллахгүй (амьд дэлгэцэд CEO-д «Тоолсон» товч
     харагдсаар байв). */
  ok(/function canOpenCount\(\)\s*\{ return capResolved\('products\.count'\) === true; \}/.test(codeLines),
     'scan: тоолох эрх = capResolved (CEO шүхэр тойрсон)');
  ok(/function canApproveOpening\(\) \{ return capResolved\('products\.opening'\) === true; \}/.test(codeLines),
     'scan: хянах эрх = capResolved (CEO шүхэр тойрсон)');
  // ⛔ CEO эдгээр хоёр алхамд БАЙХГҮЙ — мухардал үүснэ
  const g = codeLines.slice(codeLines.indexOf('function canOpenCount'), codeLines.indexOf('function canSeeStockCount'));
  eq(/state\.isCEO/.test(g), false, 'scan: CEO тоолох/хянах эрхэд ОРОХГҮЙ (мухардал үүснэ)');
  // Тоолох ТОВЧ ч ижил эрхээр
  ok(/const canOpen = canOpenCount\(\);/.test(codeLines), 'scan: тоолох товч ижил эрхээр гарна');
  ok(/\$\{canOpen \? `<input class="ui-raw stc-open-in"/.test(codeLines),
     'scan: тоолох оролт нь canOpen-оор хаалттай');
}

/* ═══ ⛔ ЭЦЭСЛЭЭГҮЙ БАРААГ ТООЛОХГҮЙ (2026-10-02, CEO барив) ═══
   «Тооллого хийгээд байна» — суурь нь баталгаажаагүй бол зөрүү юутай ч
   харьцуулагдахгүй. Улмаар зөрүү нь нөөцийг засаж, алдагдлын ЗАРДАЛ болж
   салбарын ашиг ба COO-гийн 30%-д хүрнэ. */
{
  const CBR = vm.runInContext('countBlockReason', sandbox);
  const mk = (o) => ({ sku: 'A', stock_opened_at: o.c ? 't' : null, stock_approved_at: o.a ? 't' : null,
    stock_locked_at: o.s ? 't' : null });
  eq(CBR(mk({ c: 1, a: 1, s: 1 })), '', 'тооллого: эцэслэгдсэн бараа тоологдоно');
  ok(/тоологдоогүй/.test(CBR(mk({}))), 'тооллого: тоолоогүй суурьтай бол хаалттай');
  ok(/хянагдаагүй/.test(CBR(mk({ c: 1 }))), 'тооллого: хянагдаагүй суурьтай бол хаалттай');
  ok(/эцэслээгүй/.test(CBR(mk({ c: 1, a: 1 }))), 'тооллого: хоёр гарын үсэгтэй ч эцэслээгүй бол хаалттай');
  ok(/олдсонгүй/.test(CBR(null)), 'тооллого: бараагүй бол хаалттай');
}

/* ═══ ⛔ ЭЦЭСЛЭГДСЭН ТООГ ФОРМООР ЗАСАХГҮЙ — ГАНЦ БИЧИХ ЦЭГТ (2026-10-02) ═══
   CEO барив: «эцэслэсэн байхад шууд энд ингээд сольж болж байхад эцэслэх ямар
   хэрэгтэй гэж? ийм төрлийн алдаа маш их байна». Урсгал БҮРИЙГ тус тусад нь
   хаах нь буруу арга байв — барааны засах цонх `stock`/`qty_*`-г чөлөөтэй
   өөрчилдөг тул эцэслэл чимэг болж байв.
   Шийдэл: хориг нь `saveProduct` (ГАНЦ бичих цэг) дээр. Хяналттай зам бүр
   `_moveReason` дамжуулдаг, форм дамжуулдаггүй. ⭐ Шинэ дэлгэц нэмэгдсэн ч
   энэ цэгээр дамжих тул ӨӨРӨӨ хаагдана — тэр нь энэ аргын гол давуу тал. */
{
  const SP = vm.runInContext('saveProduct', sandbox);
  const st = vm.runInContext('state', sandbox);
  const saved = st.products;
  const base = () => ({ sku: 'SEAL1', id: 'SEAL1', name: 'Түгжээтэй', stock: 10, qty_mevent: 10,
    qty_nomaad: 0, qty_catering: 0, qty_chimun: 0, stock_locked_at: '2026-10-01T00:00:00Z' });
  const open = () => ({ ...base(), sku: 'OPEN1', id: 'OPEN1', stock_locked_at: null });
  /* ⚠ `saveProduct` нь ОПТИМИСТ — амжилттай дуудлага `state.products`-ыг
     өөрчилдөг тул шалгуур бүрийн ӨМНӨ фикстурыг сэргээнэ. Эс бөгөөс өмнөх
     дуудлагын үлдэц дараагийнхыг худал унагана. */
  const err = async (patch) => {
    st.products = [base(), open()];
    try { await SP(patch); return ''; } catch (e) { return e.message; }
  };

  (async () => {
    // ⛔ Форм (шалтгаангүй) + эцэслэгдсэн + тоо хөдөлсөн → ТАТГАЛЗАНА
    ok(/гараар засах боломжгүй/.test(await err({ ...base(), qty_mevent: 3 })),
       'түгжээ: эцэслэгдсэн барааны салбарын тоог формоор засахгүй');
    ok(/гараар засах боломжгүй/.test(await err({ ...base(), stock: 99 })),
       'түгжээ: нийт нөөцийг ч формоор засахгүй');
    // ✅ Хяналттай зам (_moveReason-тэй) — ЗӨВШӨӨРНӨ
    eq(await err({ ...base(), qty_mevent: 3, _moveReason: 'count' }), '',
       'түгжээ: тооллогын зам (_moveReason) нээлттэй');
    // ✅ Тоо ХӨДӨЛӨӨГҮЙ бол бусад талбар засагдана (нэр, үнэ…)
    eq(await err({ ...base(), name: 'Шинэ нэр' }), '',
       'түгжээ: тоо хөдлөөгүй бол нэр/үнэ засагдана');
    // ✅ Эцэслээгүй бараа — хуучнаараа чөлөөтэй
    eq(await err({ ...open(), qty_mevent: 3 }), '', 'түгжээ: эцэслээгүй бараа чөлөөтэй хэвээр');
    st.products = saved;
  })();
}

/* ═══ ⛔ ЕРӨНХИЙ PATCH-Д МӨНГӨНИЙ ТҮГЖЭЭ (2026-10-02 аудит) ═══
   `patchOrderFields` нь захиалгын ДУРЫН талбарыг PATCH хийдэг. Одоогийн
   дуудагчид мөнгө хөнддөггүй ч шинэ дуудагч `total_mnt` дамжуулбал ХААСАН
   сарын орлого чимээгүй өөрчлөгдөнө. */
{
  const PF = vm.runInContext('patchOrderFields', sandbox);
  const MF = vm.runInContext('ORDER_MONEY_FIELDS', sandbox);
  const st = vm.runInContext('state', sandbox);
  const saved = st.closedMonths;
  // ⚠ Мөнгийг өөр САР руу зөөдөг талбарууд ч жагсаалтад байх ЁСТОЙ
  ['total_mnt', 'paid_mnt', 'deposit_mnt', 'items', 'paid_date', 'starts_at', 'status']
    .forEach(k => ok(MF.includes(k), 'мөнгөний талбар жагсаалтад: ' + k));

  (async () => {
    st.closedMonths = { '2026-08': { at: 'x', by: 'y' } };
    const o = { id: 'O1', paid_date: '2026-08-15', starts_at: '2026-08-20' };
    const err = async (f) => { try { await PF(o, f); return ''; } catch (e) { return e.message; } };
    ok(/сар хаалттай/.test(await err({ total_mnt: 5 })), 'PATCH: хаасан сарын дүн засагдахгүй');
    ok(/сар хаалттай/.test(await err({ items: [] })), 'PATCH: хаасан сарын барааны мөр засагдахгүй');
    ok(/сар хаалттай/.test(await err({ status: 'deleted' })), 'PATCH: хаасан сарын төлөв засагдахгүй');
    /* ⚠ Мөнгөний БИШ талбар нээлттэй хэвээр — эс бөгөөс тэмдэглэл, дамжлагын
       зураг зэрэг хаасан сарын захиалгад бичигдэхээ болино (мөнгө хөнддөггүй). */
    eq(/сар хаалттай/.test(await err({ note: 'тэмдэглэл' })), false, 'PATCH: тэмдэглэл хаалттай сард ч бичигдэнэ');
    eq(/сар хаалттай/.test(await err({ stage_meta: {} })), false, 'PATCH: дамжлагын мэдээлэл бичигдэнэ');
    st.closedMonths = {};
    eq(/сар хаалттай/.test(await err({ total_mnt: 5 })), false, 'PATCH: нээлттэй сард мөнгө засагдана');
    st.closedMonths = saved;
  })();
}

/* 0e2n) SCAN — ерөнхий PATCH-ийн мөнгөн түгжээ (2026-10-02) */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const _i = codeLines.indexOf('async function patchOrderFields');
  const pf = codeLines.slice(_i, _i + 1200);
  ok(/const _money = ORDER_MONEY_FIELDS\.filter\(/.test(pf), 'scan: мөнгөний талбарыг шүүнэ');
  ok(/await loadClosedMonths\(true\)/.test(pf), 'scan: түгжээг СЕРВЭРЭЭС шинэчилнэ');
  ok(/orderLockedMonth\(o\) \|\| orderLockedMonth\(\{ \.\.\.o, \.\.\.fields \}\)/.test(pf),
     'scan: ӨМНӨХ ба ШИНЭ сар ХОЁУЛАА шалгагдана (өөр сар руу зөөхийг барина)');
  ok(/throw new Error\(`\$\{_lk\} сар хаалттай/.test(pf), 'scan: тодорхой мессежтэй татгалзана');
  ok(/if \(_money\.length\) \{/.test(pf), 'scan: зөвхөн мөнгөний талбар дамжсан үед шалгана');
}

/* ═══ 🔎 САМБАРЫН ШҮҮЛТҮҮР (2026-10-03, CEO «нийлүүлэгчгүй, огноогүй гэх мэт») ═══
   281 барааг нүдээр хөөх боломжгүй — дутуу талбарыг шүүж өгнө. Амьд датаар:
   огноогүй 169 · нийлүүлэгчгүй 212 · барьцаагүй 82 · эцэслээгүй 230. */
{
  const AF = vm.runInContext('psApplyFilter', sandbox);
  const F = vm.runInContext('PSHEET_FILTERS', sandbox);
  const P = [
    { sku: 'A', category: 'Асар', photo: 'x', price: 100, deposit: 50, cost: 10, purchase_date: '2026-01-01', supplier: 'Нэг', qty_mevent: 5, stock_locked_at: 't' },
    { sku: 'B', category: '', photo: '', price: 0, deposit: 0, cost: 0, purchase_date: '', supplier: '', qty_mevent: 0, stock_locked_at: null },
    { sku: 'C', category: 'Техник', photo: 'y', price: 200, deposit: 0, cost: 5, purchase_date: null, supplier: '  ', qty_nomaad: 3, stock_locked_at: null },
  ];
  const k = (mode, key) => AF(P, mode, key).map(x => x.sku).join('');
  eq(k('cost', 'nodate'), 'BC', 'шүүлт: авсан огноогүй (null ба хоосон мөр хоёулаа)');
  eq(k('cost', 'nosup'), 'BC', 'шүүлт: нийлүүлэгчгүй (зөвхөн зайнаас тогтсон нь ч)');
  eq(k('cost', 'nocost'), 'B', 'шүүлт: өртөггүй');
  eq(k('price', 'noprice'), 'B', 'шүүлт: үнэгүй');
  eq(k('price', 'nodep'), 'BC', 'шүүлт: барьцаагүй');
  eq(k('catalog', 'nocat'), 'B', 'шүүлт: ангилалгүй');
  eq(k('catalog', 'nophoto'), 'B', 'шүүлт: зураггүй');
  eq(k('stock', 'zero'), 'B', 'шүүлт: нөөцгүй (бүх салбарын нийлбэр 0)');
  eq(k('stock', 'unsealed'), 'BC', 'шүүлт: эцэслээгүй');
  /* ⚠ Танихгүй түлхүүр → БҮГД. Хоосон дэлгэц гаргавал хүн «бараа алга» гэж
     андуурна (хуучин шүүлттэй үлдсэн төлөв рүү буцаж орохыг ч барина). */
  eq(k('cost', 'байхгүй'), 'ABC', 'шүүлт: танихгүй түлхүүр БҮГДИЙГ гаргана');
  eq(k('cost', ''), 'ABC', 'шүүлт: хоосон түлхүүр = бүгд');
  eq(AF(null, 'cost', 'nodate'), [], 'шүүлт: хоосон жагсаалт унахгүй');
  // ⚠ `test` унавал мөр ХАСАГДана, бүх дэлгэц унахгүй
  eq(AF([{ sku: 'X', get supplier() { throw new Error('x'); } }], 'cost', 'nosup').length, 0,
     'шүүлт: алдаатай мөр дэлгэцийг унагахгүй');
  // Самбар бүр өөрийн шүүлтүүртэй
  ['catalog', 'price', 'cost', 'stock'].forEach(m => ok((F[m] || []).length > 0, 'шүүлт: ' + m + ' самбар шүүлтүүртэй'));
}

/* 0e2p) SCAN — шүүлтүүр нэг газраас, тоотой (2026-10-03) */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/const PSHEET_FILTERS = \{/.test(codeLines), 'scan: шүүлтүүр нэг тодорхойлолтоос');
  ok(/function psApplyFilter\(/.test(codeLines), 'scan: хэрэглэх нь ганц функц');
  ok(/psApplyFilter\(_all, mode, state\.psF\)/.test(codeLines), 'scan: жагсаалтад хэрэглэгдэнэ');
  /* ⛔ Чип бүр ТООТОЙ — тоогүй бол хүн аль нь ажилтайг мэдэхгүй, дарж үзэх
     болно. Тоо нь ажил хаана байгааг систем хэлэх цорын ганц зам. */
  ok(/data-ps-f2="\$\{escapeHtml\(k\)\}">\$\{escapeHtml\(lb\)\}<b>\$\{n\}<\/b>/.test(codeLines),
     'scan: чип бүр тоотой');
  // ⚠ Тоо нь ШҮҮГДСЭН биш, ХАЙЛТААР шүүгдсэн бүх мөрөөс — эс бөгөөс шүүлт
  //   идэвхжихэд бусад чипийн тоо 0 болж утгагүй болно.
  ok(/_all\.filter\(x => \{ try \{ return !!f\.test\(x\); \}/.test(codeLines),
     'scan: чипийн тоо нь шүүлтээс ӨМНӨХ жагсаалтаас');
  ok(/state\.psF === k \|\| !k\) \? '' : k/.test(codeLines),
     'scan: дахин дарвал БҮГД рүү буцна');
}

/* 0e2o) SCAN — «Нөөц ба салбар» самбар: ШИЛЖҮҮЛЭГ үндсэн үйлдэл (2026-10-03)
   CEO: «бараа шилжихгүй, ойлгомжгүй». 4 тоог тусад нь нэмж хасуулах нь
   шилжүүлэг БИШ — нийлбэр санамсаргүй өөрчлөгдөх нүх үлдээдэг. ⇄ товч нь
   одоо байгаа `openTransferModal`-ыг дуудаж `product_transfers`-д мөр
   үлдээдэг бөгөөд нийлбэрийг БАРЬДАГ. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const _css = fs.readFileSync(path.join(__dirname, '..', 'styles.css'), 'utf8');
  ok(/data-ps-mv="\$\{escapeHtml\(p\.sku\)\}"/.test(codeLines), 'scan: мөр бүрт ⇄ шилжүүлэх товч');
  ok(/data-ps-mv\]'\)\.forEach[\s\S]{0,220}openTransferModal\(b\.dataset\.psMv\)/.test(codeLines),
     'scan: ⇄ нь одоо байгаа шилжүүлэх модалыг дуудна (шинэ зам үүсгэхгүй)');
  // Эцэслэгдсэн бараа: гар засвар түгжээтэй, ШИЛЖҮҮЛЭГ нээлттэй
  ok(/_sld \? ' disabled' : ''/.test(codeLines), 'scan: эцэслэгдсэн барааны тоон талбар түгжээтэй');
  ok(/ps-row-stock/.test(codeLines), 'scan: нөөцийн мөр өөрийн бүтэцтэй (нягт байрлал)');
  /* ⛔ `.ps-nm` ТОГТМОЛ өргөнтэй бол 375px-д зураг ганцаараа мөр эзэлж, БҮХ
     самбарын мөр 173–231px болдог. Нэр ШАХАГДДАГ байх ёстой. */
  ok(/\.ps-row \.ps-nm \{ flex: 1 1 140px; \}/.test(_css),
     'scan: нэр шахагддаг (бүх самбарт нягт мөр)');
  ok(/\.ps-row \.ps-fields \{ flex: 1 1 100%; \}/.test(_css),
     'scan: талбарууд нарийн дэлгэцэд өөрийн мөрөнд');
  // ⛔ Хадгалах тууз `display:flex` тул `hidden` ажиллахгүй байв — «0 бараа
  //    өөрчлөгдсөн» гэж ҮРГЭЛЖ харагдаж мөр халхалдаг байсан.
  ok(/\.ps-savebar\[hidden\]\s*\{\s*display:\s*none/.test(_css),
     'scan: хадгалах тууз ҮНЭХЭЭР нуугдана (display:flex-ийг дарна)');
}

/* 0e2m) SCAN — ТҮГЖЭЭНИЙ АУДИТ: products-ийн БҮХ бичих зам (2026-10-02)
   CEO «ийм төрлийн алдаа маш их байна» гэснээр бүх бичих замыг тоолов.
   `products`-д 9 бичих зам байхад түгжээ зөвхөн `saveProduct`-д байв:
   · `removeProductRow` (DELETE) — эцэслэгдсэн суурийг ХАТУУ УСТГАНА
   · `setProductArchived` — архивласан бараа элэгдлээс ЧИМЭЭГҮЙ гарна
   (`saveBranchTransfer`/`bulkReturnBranch` нь `product_transfers`-д мөр
   үлдээдэг хяналттай зам тул зориуд нээлттэй.) */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const rm = codeLines.slice(codeLines.indexOf('async function removeProductRow'),
                             codeLines.indexOf('async function setProductArchived'));
  ok(/if \(stockSealed\(_p\)\) throw new Error\(/.test(rm),
     'scan: эцэслэгдсэн барааг ХАТУУ УСТГАХГҮЙ');
  ok(/const _p = \(state\.products[\s\S]{0,200}archivedProducts/.test(rm),
     'scan: архивлагдсан жагсаалтаас ч хайна (устгахын өмнө)');
  const ar = codeLines.slice(codeLines.indexOf('async function setProductArchived'),
                             codeLines.indexOf('async function runAsarModuleSetup'));
  ok(/val && stockSealed\(/.test(ar), 'scan: эцэслэгдсэнийг архивлахад баталгаажуулалт');
  ok(/await showConfirm\(/.test(ar) && /return false;/.test(ar),
     'scan: баталгаажуулалтын хариуг ШАЛГАЖ буцдаг');
  // ⚠ Архивлахыг ХОРИГЛОХГҮЙ — актлах нь жинхэнэ хэрэгцээ, зөвхөн чимээгүй болгохгүй
  eq(/throw new Error\('Эцэслэгдсэн[^']*архив/.test(ar), false,
     'scan: архивлахыг бүрэн хориглохгүй (актлах хэрэгцээтэй)');
}

/* 0e2l) SCAN — түгжээ ГАНЦ БИЧИХ ЦЭГТ, нэгтгэхээс ӨМНӨ (2026-10-02)
   Хориг нь `state.products[idx]` нэгтгэхээс ХОЙШ байвал ӨМНӨХ утга аль хэдийн
   дарагдсан байх тул «хөдөлсөн эсэх» нь ҮРГЭЛЖ худал гарч, түгжээ ажиллахгүй. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const i = codeLines.indexOf('async function saveProduct(');
  const fn = codeLines.slice(i, i + 2400);
  const guardAt = fn.indexOf('stockSealed(state.products[idx]) && !product._moveReason');
  const mergeAt = fn.indexOf('state.products[idx] = { ...state.products[idx], ...product }');
  ok(guardAt > 0, 'scan: эцэслэлийн түгжээ saveProduct дотор');
  ok(guardAt < mergeAt, 'scan: түгжээ state нэгтгэхээс ӨМНӨ (эс бол өмнөх утга дарагдана)');
  ok(/throw new Error\('Эцэслэгдсэн барааны тоог гараар засах боломжгүй/.test(fn),
     'scan: татгалзах нь ТОДОРХОЙ мессежтэй');
  // ⛔ Хяналттай зам нь `_moveReason`-оор ялгардаг — тэр нөхцөлийг хасвал бүх зам хаагдана
  ok(/!product\._moveReason/.test(fn), 'scan: хяналттай зам (_moveReason) нээлттэй үлдэнэ');
  // Дэлгэцэд ч түгжээ харагдана
  ok(/const _sealed = !!\(isEdit && p && stockSealed\(p\)\);/.test(codeLines),
     'scan: засах цонх эцэслэлийг мэднэ');
  ok(/\$\{_pkgDis \|\| _sealDis\}/.test(codeLines), 'scan: тоон талбарууд түгжигдэнэ');
}

/* 0e2k) SCAN — тооллогын хориг БҮХ замд (2026-10-02)
   Бүртгэх зам нээлттэй үлдвэл батлагдаагүй суурьтай зөрүү DB-д хуримтлагдана;
   ХЭРЭГЖҮҮЛЭХ зам нээлттэй үлдвэл тэр зөрүү нөөц ба МӨНГӨНД хүрнэ. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function countBlockReason\(/.test(codeLines), 'scan: тооллогын хоригийн шалтгаан ганц функцээс');
  const _sv0 = codeLines.indexOf('async function saveStockCount');
  const sv = codeLines.slice(_sv0, _sv0 + 900);
  ok(/const _blk = countBlockReason\(productBySku\(sku\)\);[\s\S]{0,60}throw new Error\(_blk\)/.test(sv),
     'scan: БҮРТГЭХ зам хаалттай');
  const _ap0 = codeLines.indexOf('async function applyStockCount');
  const ap = codeLines.slice(_ap0, _ap0 + 900);
  ok(/const _blk = countBlockReason\(p\);[\s\S]{0,60}throw new Error\(_blk\)/.test(ap),
     'scan: ХЭРЭГЖҮҮЛЭХ зам (мөнгөний зам) хаалттай');
  ok(/const actBlk = act \? countBlockReason\(act\) : '';/.test(codeLines),
     'scan: дэлгэцэд шалтгаан ил гарна');
}

// Салбарын тооллогын зөрүү ЗӨВХӨН тэр салбарын баганыг хөдөлгөнө (2026-10-07)
{
  const st = vm.runInContext('state', sandbox);
  const P0 = { sku: 'M-BR1', name: 'Туршилт', stock: 13, qty_mevent: 3, qty_nomaad: 10, qty_catering: 0, qty_chimun: 0, stock_locked_at: '2026-10-01T00:00:00Z', stock_opened_at: 'x', stock_approved_at: 'x' };
  const savedP = st.products, origSave = sandbox.saveProduct, origFetch = sandbox.fetch;
  let got = null;
  const restore = () => { st.products = savedP; sandbox.saveProduct = origSave; sandbox.fetch = origFetch; };
  st.products = [P0];
  sandbox.saveProduct = async (x) => { got = x; return x; };
  sandbox.fetch = () => Promise.resolve({ ok: true, status: 204, json: () => Promise.resolve([]), text: () => Promise.resolve('') });
  const pr = vm.runInContext("applyStockCount({ id: 1, session_id: '2026-Q4@nomaad', sku: 'M-BR1', system_qty: 10, counted_qty: 7 })", sandbox);
  st.products = savedP;
  Promise.resolve(pr).then(() => {
    eq(got && got.qty_nomaad, 7, 'салбар: NOMAAD-ийн зөрүү NOMAAD-ийн баганад');
    eq(got && got.qty_mevent, 3, 'салбар: бусад салбарын тоо хөдлөхгүй');
    eq(got && got.stock, 10, 'салбар: нийт = салбаруудын нийлбэр');
    restore();
  }).catch(e => { ok(false, 'салбар: зөрүү хэрэгжүүлэх — ' + e.message); restore(); });
}

// ЭЦЭСЛЭХИЙН ӨМНӨ «анх → тоолсон» (2026-10-07, CEO)
{
  const oba = F.openingBeforeAfter;
  const L0 = '2026-09-14T03:42:00Z';
  const mv = [
    { sku: 'A', reason: 'opening', delta: 22, at: '2026-10-05T09:49:00Z' },
    { sku: 'A', reason: 'manual', delta: -2, at: '2026-10-06T01:00:00Z' },   // тоолсны ДАРАА гараар
    { sku: 'C', reason: 'opening', delta: -3, at: '2026-09-20T01:00:00Z' },
    { sku: 'C', reason: 'opening', delta: 1, at: '2026-09-21T01:00:00Z' },    // татгалзаад дахин тоолсон
  ];
  eq(oba({ sku: 'A', stock: 78, stock_opened_at: '2026-10-05T09:49:00Z' }, mv, L0), { known: true, before: 58, after: 80, d: 22 }, 'анх→тоолсон: зөрүүтэй тоолсон (дараах хөдөлгөөнийг хасна)');
  eq(oba({ sku: 'B', stock: 40, stock_opened_at: '2026-10-01T01:00:00Z' }, mv, L0), { known: true, before: 40, after: 40, d: 0 }, 'анх→тоолсон: дэвтэрт мөргүй = зөрүүгүй');
  eq(oba({ sku: 'D', stock: 5, stock_opened_at: '2026-09-14T03:10:00Z' }, mv, L0), { known: false, after: 5 }, 'анх→тоолсон: дэвтэр эхлэхээс өмнө тоолсон → мэдэгдэхгүй (таамаглахгүй)');
  eq(oba({ sku: 'C', stock: 8, stock_opened_at: '2026-09-21T01:00:00Z' }, mv, L0), { known: true, before: 10, after: 8, d: -2 }, 'анх→тоолсон: хоёр удаа тоолсон бол анхнаас сүүлч хүртэл');
  eq(oba({ sku: 'E', stock: 5 }, mv, L0), null, 'анх→тоолсон: тоолоогүй бараа → харуулахгүй');
  eq(oba({ sku: 'A', stock: 78, stock_opened_at: 'x' }, null, L0), null, 'анх→тоолсон: дэвтэр ачаалагдаагүй → харуулахгүй');
  const ob = src.slice(src.indexOf('function openingBlockHtml('), src.indexOf('function renderStockCount('));
  ok((ob.match(/\$\{_dq\(x\.sku\)\}/g) || []).length === 2, 'анх→тоолсон: батлах ба эцэслэх жагсаалт хоёуланд гарна');
}

// 🔒 ЭЦЭСЛЭЛ DB-д ХАДГАЛАГДАНА + БӨӨНӨӨР ЭЦЭСЛЭХ (2026-10-07)
// `saveProduct` нь stock_locked_* -ийг илгээдэггүй байсан тул «Эцэслэх» зөвхөн
// дэлгэц дээр тусаж, дахин ачаалахад буцаж алга болдог байв.
{
  /* ⚠ Бусад асинх тест `saveProduct`/`fetch`-ийг түр сольдог тул энэ тест ТЭДНИЙ
     дараа (setTimeout 0) ажиллана; төгсгөлд `__late`-ийг хүлээж тооллогод орно. */
  (globalThis.__late = globalThis.__late || []).push(new Promise(done => setTimeout(() => {
  const st = vm.runInContext('state', sandbox);
  const P0 = { sku: 'M-LK1', id: 'M-LK1', name: 'Түгжих', stock: 4, qty_mevent: 4, stock_opened_at: 'a', stock_approved_at: 'b' };
  const savedP = st.products, origFetch = sandbox.fetch, saved2 = st._prodHasLock;
  const bodies = [];
  const restore = () => { st.products = savedP; sandbox.fetch = origFetch; st._prodHasLock = saved2; done(); };
  st.products = [P0]; st._prodHasLock = true;
  sandbox.fetch = (url, opt) => { if (/products\?on_conflict/.test(String(url))) bodies.push(JSON.parse(opt.body)); return Promise.resolve({ ok: true, status: 201, json: () => Promise.resolve([]), text: () => Promise.resolve('') }); };
  const p1 = vm.runInContext("saveProduct({ ...state.products[0], stock_locked_at: '2026-10-07T01:00:00Z', stock_locked_by: '88006790', _bulk: true })", sandbox);
  Promise.resolve(p1).then(() => {
    eq(bodies[0] && bodies[0].stock_locked_at, '2026-10-07T01:00:00Z', 'эцэслэл: stock_locked_at DB рүү илгээгдэнэ');
    eq(bodies[0] && bodies[0].stock_locked_by, '88006790', 'эцэслэл: stock_locked_by DB рүү илгээгдэнэ');
    ok(!('_bulk' in (bodies[0] || {})), 'эцэслэл: _bulk туг DB рүү явахгүй');
    // Бөөн горимд алдаа ЗАЛГИГДАХГҮЙ — дуудагч тоолно
    st.products = [P0];
    sandbox.fetch = () => Promise.resolve({ ok: false, status: 500, json: () => Promise.resolve({}), text: () => Promise.resolve('boom') });
    return vm.runInContext("saveProduct({ ...state.products[0], stock_locked_at: 'x', _bulk: true }).then(() => 'ok', () => 'threw')", sandbox);
  }).then(r => { eq(r, 'threw', 'эцэслэл: бөөн горимд алдаа шидэгдэнэ (чимээгүй «амжилттай» биш)'); restore(); })
    .catch(e => { ok(false, 'эцэслэл: хадгалалт — ' + e.message); restore(); });
  }, 0)));

  // Бүлэглэлт: дутсан нь тусдаа, өртгөөр эрэмбэлэгдэнэ
  const mv = [
    { sku: 'D1', reason: 'opening', delta: -5, at: '2026-10-02T01:00:00Z' },
    { sku: 'D2', reason: 'opening', delta: -1, at: '2026-10-02T01:00:00Z' },
    { sku: 'U1', reason: 'opening', delta: 3, at: '2026-10-02T01:00:00Z' },
  ];
  const pr = (sku, stock, at) => ({ sku, name: sku, stock, stock_opened_at: at || '2026-10-02T01:00:00Z' });
  const G = F.openingSealGroups([pr('D1', 0), pr('D2', 4), pr('U1', 8), pr('S1', 6), pr('X1', 2, '2026-09-14T03:00:00Z')], mv, '2026-09-14T03:42:00Z',
    (sku) => ({ D1: 7000000, D2: 100000 })[sku] || 0);
  eq(G.down.map(x => x.sku), ['D1', 'D2'], 'бөөн эцэслэх: дутсан нь тусдаа, өртгөөр эрэмбэлэгдэнэ');
  eq(G.down[0].value, 35000000, 'бөөн эцэслэх: дутсан дүн = тоо × өртөг');
  eq(G.up.map(x => x.sku), ['U1'], 'бөөн эцэслэх: илүү гарсан');
  eq(G.same.map(x => x.sku), ['S1'], 'бөөн эцэслэх: зөрүүгүй');
  eq(G.unknown.map(x => x.sku), ['X1'], 'бөөн эцэслэх: анхны тоо мэдэгдэхгүй');
  const bm = src.slice(src.indexOf('function openBulkSealModal'), src.indexOf('function openBulkSealModal') + 6000);
  ok(/const on = new Set\(\[\.\.\.G\.same, \.\.\.G\.up, \.\.\.G\.unknown\]/.test(bm), 'бөөн эцэслэх: дутсан бараа өгөгдмөлөөр СОНГОГДОХГҮЙ');
  ok(/if \(!\(await showConfirm\(/.test(bm), 'бөөн эцэслэх: буцаах боломжгүй тул showConfirm-ийн хариуг шалгана');
  ok(/state\.isCEO/.test(bm.slice(0, 200)), 'бөөн эцэслэх: зөвхөн CEO');
}

/* 0e2i) SCAN — эцэслэлийн хориг БҮХ бичих замд (2026-10-02)
   Нэг замыг нь онгорхой орхивол хөлдсөн суурь чимээгүй өөрчлөгдөж, гурван
   гарын үсэг утгагүй болно. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function stockSealed\(/.test(codeLines) && /function openingSealBlock\(/.test(codeLines),
     'scan: эцэслэлийн функцууд байна');
  ok(/if \(stockSealed\(p\)\) return 'Эцэслэн баталгаажсан — өөрчлөх боломжгүй';/.test(codeLines),
     'scan: дахин батлах зам хаагдсан');
  ok(/if \(stockSealed\(p\)\) return 'Эцэслэн баталгаажсан — буцаах боломжгүй/.test(codeLines),
     'scan: буцаах зам хаагдсан');
  ok(/if \(stockSealed\(p\)\) \{ showToast\('Эцэслэн баталгаажсан/.test(codeLines),
     'scan: дахин ТООЛОХ зам ч хаагдсан');
  // ⛔ Эцэслэх нь буцаах боломжгүй тул баталгаажуулалтгүй байж БОЛОХГҮЙ
  const h = codeLines.slice(codeLines.indexOf("data-op-seal]"), codeLines.indexOf("data-op-un]"));
  ok(/if \(!\(await showConfirm\(/.test(h), 'scan: эцэслэхийн өмнө баталгаажуулалт асууна');
  // ⛔ «Нээх» товч БАЙХГҮЙ — залруулга тооллогоор, аудитын мөртэй
  eq((codeLines.match(/data-op-unseal/g) || []).length, 0,
     'scan: эцэслэлийг НЭЭХ товч БАЙХГҮЙ (залруулга тооллогоор)');
}

/* 0e2g) SCAN — ЭЛЭГДЛИЙГ ШАЛГАХ ГАЗАР байна (2026-10-02)
   «Тооцоолол зөв эсэхийг хаанаас харах вэ?» — өмнө нь зөвхөн барааны ЦОНХ дотор
   байсан тул 281 барааг нэг бүрчлэн нээхээс өөр арга байгаагүй, тайлан дахь
   14.3сая/сар гэсэн тоог хэн ч тулгаж чаддаггүй байв. Одоо «Өртөг ба хөрөнгө»
   жагсаалт: дээр нь НИЙЛБЭР, мөр бүрт дүрэм/нас/сарын дүн. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function psDeprecLine\(/.test(codeLines) && /function psDeprecSummary\(/.test(codeLines),
     'scan: элэгдлийн мөр ба нийлбэр функцууд байна');
  ok(/\$\{psDeprecLine\(p\)\}/.test(codeLines), 'scan: бараа бүрийн мөрөнд элэгдэл бичигдэнэ');
  ok(/mode === 'cost' \? psDeprecSummary\(\)/.test(codeLines),
     'scan: нийлбэр нь «Өртөг ба хөрөнгө» дэлгэцийн толгойд');
  /* ⛔ ТООГ ДАХИН БОДОХГҮЙ — тайлантай ижил эх сурвалжаас. Дахин бодвол
     жагсаалт ба тайлан хоёр өөр тоо харуулж, тулгалт утгагүй болно.
     ⚠ `psDeprecSummary` нь `psDeprecLine`-ААС ӨМНӨ тодорхойлогддог тул зүсэлт
       түүнээс эхлэх ёстой — эс бөгөөс гурван шалгуур худал унана. */
  const dl = codeLines.slice(codeLines.indexOf('function psDeprecSummary'), codeLines.indexOf('function renderProductSheet'));
  ok(/const d = deprecForProduct\(p\);/.test(dl), 'scan: мөр нь deprecForProduct-аас (тайлангийн ижил эх сурвалж)');
  ok(/deprecByBranch\(state\.products/.test(dl), 'scan: нийлбэр нь deprecByBranch-аас');
  eq((dl.match(/\/\s*\(\s*years\s*\*\s*12\s*\)/g) || []).length, 0,
     'scan: элэгдлийг дэлгэцэд ДАХИН бодохгүй');
  // Өртөггүй / огноогүй бараа НУУГДАХГҮЙ — тэдгээр нь буруу тооцооллын гол эх үүсвэр
  ok(/noCost \? `[^`]*бараа өртөггүй/.test(dl), 'scan: өртөггүй бараа ил тоологдоно');
  /* ⛔ ЭВХЭГДСЭН ч САРЫН ДҮН товчлолд ҮЛДЭНЭ (2026-10-03). Бүрэн нуувал энэ
     мөрийн ЗОРИЛГО — элэгдлийг бараагаар тулгах — алдагдаж, хүн 281 барааг
     нэг бүрчлэн нээх болно. */
  ok(/<summary>📉 <b>\$\{fmtMoneyShort\(Math\.round\(d\.totalMonth\)\)\}\/сар<\/b>/.test(dl),
     'scan: эвхэгдсэн үед ч сарын дүн товчлолд харагдана');
  ok(/<details class="ps-dep">/.test(dl), 'scan: задаргаа эвхэгддэг');
  // Эвхэгдсэн үед мөрөнд багтана, задарвал бүтэн мөр эзэлнэ
  const _depCss = fs.readFileSync(path.join(__dirname, '..', 'styles.css'), 'utf8');
  ok(/\.ps-dep \{ flex: 0 1 auto;/.test(_depCss), 'scan: эвхэгдсэн элэгдэл мөрөнд багтана');
  ok(/\.ps-dep\[open\] \{ flex: 1 0 100%; \}/.test(_depCss), 'scan: задарсан үед бүтэн мөр');
  ok(/noDateN \? `[^`]*авсан огноогүй/.test(dl), 'scan: авсан огноогүй бараа ил тоологдоно');
}

/* 0e2f) SCAN — COO картад ЭЛЭГДЭЛ ил задарна (2026-10-02)
   «14 саяын зардал хаанаас гарч ирсэн юм бэ?» — элэгдэл нь сарын эхэнд БҮТНЭЭР
   суудаг тул сар дөнгөж эхлэхэд 2 хоногийн орлоготой харьцуулагдаж, зардал
   гэнэт томорсон мэт харагдана. Мөнгө гараагүй гэдгийг ил хэлэх ёстой. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/const COO_DEP_KEY = \{/.test(codeLines),
     'scan: салбарын нэр → элэгдлийн түлхүүрийн зураглал ганц газар');
  ok(/if \(dk && p\.dep && p\.dep\.active\) dep \+=/.test(codeLines),
     'scan: зөвхөн ИДЭВХТЭЙ элэгдэл нэмэгдэнэ (лавлагаа тоо орохгүй)');
  ok(/үүнээс элэгдэл \(мөнгө гараагүй\)/.test(codeLines),
     'scan: картад «үүнээс элэгдэл (мөнгө гараагүй)» дэд мөр гарна');
}

/* 0e2e) SCAN — ТЭНЦЭЛ ЗӨВХӨН САРААР (2026-10-02, CEO шийдвэр)
   Хуулгын экспортын цонх дурын (амьд датаар 23 хуулгын 2 нь л сартай тохирсон)
   тул тэндээс «сар тэнцсэн» гэж дүгнэвэл: ① хил давсан хуулга ХОЁР сард тоологдож
   нэг дутуу файл хоёр сарыг зэрэг блоклоно ② «01…өнөөдөр» хуулганд сарын эцсийн
   үлдэгдэл БАЙХГҮЙ атал сар батлагдсан мэт харагдана. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function monthSeal\(/.test(codeLines) && /function monthEndDay\(/.test(codeLines),
     'scan: сарын тэнцэл ганц функцээс');
  const bs = codeLines.slice(codeLines.indexOf('function balanceStats'),
                             codeLines.indexOf('function closeMonthBlockers'));
  ok(/monthSeal\(stmts, a, m\)/.test(bs), 'scan: balanceStats нь monthSeal-аас уншина');
  eq((bs.match(/stmtBalanceCheck\(/g) || []).length, 0,
     'scan: balanceStats хуулга тус бүрийн тэнцлийг ШУУД шалгахаа болив (сараар)');
  const ms = codeLines.slice(codeLines.indexOf('function monthSeal'), codeLines.indexOf('function balanceStats'));
  // ⛔ Эцсийн үлдэгдэлгүй сарыг «батлагдсан» гэж бичихгүй — ЯМАР хуулга хэрэгтэйг хэлнэ
  ok(/state: 'noend'/.test(ms) && /хуулга татаж оруул/.test(ms),
     'scan: эцсийн үлдэгдэл алга бол ЯМАР хуулга татахыг хэлнэ');
  ok(/closing: null/.test(ms), 'scan: батлагдаагүй сарын эцсийн үлдэгдлийг ТААМАГЛАХГҮЙ');
  /* ⛔ ТЭНЦЭЭГҮЙ хуулгаас сарын дүн ГАРГАЖ АВАХГҮЙ — батлагдаагүй тооноос
     гаргасан зүсэлт батлагдаагүй хэвээр. Хамгаалалт алдагдвал «батлагдсан»
     гэсэн ХУДАЛ дүгнэлт тарна. */
  ok(/const b = stmtBalanceCheck\(s\); return b\.ok && !b\.skip;/.test(ms),
     'scan: зөвхөн ӨӨРӨӨ тэнцсэн хуулгаас сарын дүн гаргаж авна');
  ok(/s\.months\[m\]\.end != null/.test(ms),
     'scan: эцсийн үлдэгдэл гарган аваагүй сарыг батлахгүй');
  // Хуулга импортод сараар задарна — эс бөгөөс гаргаж авах дата хэзээ ч үүсэхгүй
  ok(/months: stmtMonthSplit\(rows, opening\)/.test(codeLines),
     'scan: импортод хуулга сараар задарч хадгалагдана');
  /* ⛔ ЖИНХЭНЭ хаах зам (toggleMonthClose) ч ангилаагүй зардлыг тоолж дамжуулна —
     зөвхөн картын товчийг унтраавал CEO цонхноос шууд хааж өнгөрнө. */
  ok(/allPendingCardExpenses\(\)\.filter\(r => String\(r\.requested_at \|\| ''\)\.slice\(0, 7\) === m\)\.length/.test(codeLines),
     'scan: хаах зам ангилаагүй зардлыг тоолно');
  ok(/closeMonthBlockers\(state\.bankStatements, state\.bankIncome, companyAcctList\(\), m, _pendM\)/.test(codeLines),
     'scan: тэр тоо блокеруудад дамжина');
  // Бүтэн сар = 1-нээс сүүлчийн өдөр хүртэл
  ok(/String\(s\.period_from\) === first && String\(s\.period_to\) === end/.test(ms),
     'scan: сар батлагдах нөхцөл = 1-нээс сүүлчийн өдөр хүртэлх БҮТЭН хуулга');
  // Тулгалтын цонхонд сарын шат байна
  ok(/recon-sec-h">⚖️ \$\{escapeHtml\(sealMonth\)\} сарын эцсийн үлдэгдэл/.test(codeLines),
     'scan: тулгалтын цонхонд сарын блок гарна (тайлбар биш, бодит markup)');
  ok(/monthSeal\(list, a, sealMonth\)/.test(codeLines), 'scan: сарын шат ч ижил функцээс (дүрэм салбарлахгүй)');
  /* ⛔ ЗӨВХӨН СОНГОСОН САР — бүх сарыг дараалуулбал «9 сар сонгосон атал яагаад
     10 сар улаан байна» гэж хүн төөрнө (амьд дэлгэцэд гарсан гомдол). */
  ok(/const sealMonth = String\(state\.finReportMonth/.test(codeLines),
     'scan: сарын блок нь СОНГОСОН сараар (бүх сар дараалахгүй)');
  // ⛔ Дансны нэр тайлбарт дарагдахгүй — тайлбар нь ӨӨРИЙН мөрөнд
  ok(/seal-why/.test(codeLines), 'scan: шалтгаан нь дансны нэрийг шахахгүй, доорх мөрөнд');
  // Мөр дарахад бодолт нээгдэнэ
  ok(/<details class="stmt-det"><summary class="recon-row seal-row">/.test(codeLines),
     'scan: сарын мөр дарахад бодолт нээгдэнэ');
}

/* 0e2d) SCAN — БОДОЛТЫГ ДАХИН БОДОХГҮЙ, залгааны тулгуур ГАНЦ газар (2026-10-02)
   `stmtBalanceCheck` = тэнцлийн ганц шүүгч (валют данс, уншигдаагүй үлдэгдэл,
   ±1₮ тоймлолт бүгд тэнд). Дэлгэц өөрөө «эхний + орлого − зарлага» бодож
   харьцуулбал тэр онцгой тохиолдлууд алдагдаж, дэлгэц ба шалгуур зөрнө.
   Багтсан хуулгыг хасах дүрэм ч ганц газар (`stmtChainSpine`) — хоёр газар
   бичвэл залгаа ба дэлгэц өөр хуулгыг «тулгуур» гэж үзнэ. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function stmtChainSpine\(/.test(codeLines), 'scan: залгааны тулгуур ганц функцээс');
  ok(/function stmtDetail\(/.test(codeLines), 'scan: хуулгын бодолт ганц функцээс');
  // stmtChainCheck өөрөө эрэмбэлж/шүүхгүй — stmtChainSpine дуудна
  const cc = codeLines.slice(codeLines.indexOf('function stmtChainCheck'),
                             codeLines.indexOf('function stmtManualIncome') > 0
                               ? codeLines.indexOf('function stmtManualIncome') : codeLines.indexOf('function incomeManualRows'));
  ok(/stmtChainSpine\(all\)/.test(cc), 'scan: залгааны шалгуур тулгуурыг ганц функцээс авна');
  eq((cc.match(/period_from\)\.localeCompare/g) || []).length, 0,
     'scan: stmtChainCheck дотор эрэмбэлэх/багтсаныг шүүх код ДАВХАРДААГҮЙ');
  // stmtDetail нь зөрүүг ӨӨРӨӨ бодохгүй — stmtBalanceCheck-ээс авна
  const sd = codeLines.slice(codeLines.indexOf('function stmtDetail'),
                             codeLines.indexOf('function stmtChainCheck'));
  ok(/stmtBalanceCheck\(s\)/.test(sd), 'scan: бодолт тэнцлийн шүүгчээс уншина');
  eq((sd.match(/closing_calc\s*\)?\s*-/g) || []).length, 0,
     'scan: stmtDetail зөрүүг ДАХИН бодохгүй');
  // Шалгагдаагүй үед зөрүү нь null — 0 бол «зөв» гэж уншигдана
  ok(/diff: b\.skip \? null :/.test(sd), 'scan: шалгагдаагүй үед зөрүү null');
  // Дэлгэц: бодолтын мөрүүд + эх файл харагдана
  ok(/= Бодсон эцсийн/.test(codeLines) && /Хуулгад бичсэн/.test(codeLines),
     'scan: «бодсон» ба «хуулгад бичсэн» хоёр мөр ЗЭРЭГ харагдана');
  ok(/stmt-lad/.test(codeLines), 'scan: бодолт өөрийн класстай (inline style биш)');
}

/* 0e2c) SCAN — ТЭНЦЛИЙН ТӨЛӨВ хоёр газар салбарлахгүй (2026-10-02)
   «Хэдэн данснаас хэд нь тэнцсэн» нь ГАНЦ функцээс (`balanceStats`) гарна: карт
   болон сар хаах хоёул түүнээс уншина. Хоёр газар бодвол дэлгэц «4/4 тэнцсэн»
   гэж байхад сар хаах «зөрүүтэй» гэж хориглож, хүн алийг нь ч эрх мэдэлтэй
   гэж мэдэхгүй болно. Мөн ТУСДАА ЦОНХ үүсгэхгүй — хэн ч нээдэггүй дэлгэц үхдэг. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function balanceStats\(/.test(codeLines), 'scan: тэнцлийн тоолол ганц функцээс');
  // closeMonthBlockers нь өөрөө ДАХИН бодохгүй — balanceStats дуудна
  const cb = codeLines.slice(codeLines.indexOf('function closeMonthBlockers'),
                             codeLines.indexOf('function finNextSteps'));
  ok(/balanceStats\(stmts, regAccts, month\)/.test(cb),
     'scan: сар хаах нь balanceStats-аас уншина');
  eq((cb.match(/stmtBalanceCheck\(/g) || []).length, 0,
     'scan: closeMonthBlockers тэнцлийг ДАХИН бодохгүй (бүгд balanceStats-аар)');
  // ⛔ Тэнцлийн зөрүү «залгаа» гэж нэрлэгдэхгүй — хүнд өөр ажил заана
  ok(/flags\.filter\(g => g\.kind !== 'balance'\)/.test(cb),
     'scan: тэнцлийн зөрүү залгааны блокероос ХАСАГДСАН');
  ok(/kind: 'balance'/.test(cb), 'scan: тэнцэл нь өөрийн нэртэй блокер');
  // Карт нь тэнцлийн мөрийг ҮРГЭЛЖ гаргана (зөв үед ч N/M)
  ok(/key: 'balance', done: true[\s\S]{0,300}данс сарын эцсийн үлдэгдлээр батлагдсан/.test(codeLines),
     'scan: зөв үед ч «N/M данс сарын эцсийн үлдэгдлээр батлагдсан» гэж батална');
  ok(/\}\)\(balanceStats\(state\.bankStatements, companyAcctList\(\), month\)\)/.test(codeLines),
     'scan: дэлгэц картад тэнцлийн төлөв дамжуулна');
  // ⏳ Сар дуусаагүй бол тэнцэл ХҮЛЭЭНЭ — 10-05-нд «10-31-ний хуулга оруул» гэж шаардахгүй (2026-10-05, CEO)
  ok(/today: todayStr\(\),/.test(codeLines), 'scan: карт өнөөдрийг дамжуулна (сар дууссан эсэх)');
  {
    const bal4 = { total: 4, ok: 0, bad: 0, unver: 4, badAccts: [], unverAccts: ['Зарлага данс', 'Орлого Mevent', 'Орлого Nomaad', 'ХААН байгууллага'] };
    const base = { month: '2026-10', isCEO: true, missingAccts: [], pendExpenses: 0, openIncome: { n: 0, sum: 0 }, balance: bal4 };
    const mid = F.finNextSteps({ ...base, today: '2026-10-05' });
    const bm = mid.find(s => s.key === 'balance');
    ok(bm.wait && !bm.n && /2026-10-31/.test(bm.hint), 'тэнцэл: сар дуусаагүй → хүлээнэ, тоологдохгүй');
    ok(mid.find(s => s.key === 'close').wait, 'сар хаах: сар дуусаагүй бол хүлээнэ');
    const end = F.finNextSteps({ ...base, today: '2026-11-03' }).find(s => s.key === 'balance');
    eq(end.n, 4, 'тэнцэл: сар дууссаны дараа 4 данс');
    ok(/Зарлага данс, Орлого Mevent/.test(end.hint) && end.hint.length < 160, 'тэнцэл: товч (дансны нэр + юу дутуу), урт өгүүлбэр давтахгүй');
  }
  // ── НЭГ ИМПОРТ = ОРЛОГО + ЗАРДАЛ (2026-10-05, CEO) ──
  {
    const cm = codeLines.slice(codeLines.indexOf('async function openStatementClassifyModal'), codeLines.indexOf('function renderMyExpenses'));
    ok(cm.length > 1000, 'scan: хуулга оруулах цонх олдов');
    ok(/!rows\.length && !skippedInternal && !incomePrev\.length\) throw/.test(cm), 'импорт: зөвхөн орлоготой хуулга татгалзагдахгүй');
    ok(/buildStatementImport\(st, _meta/.test(cm), 'импорт: орлогыг хадгалах үеийн ИЖИЛ функцээр урьдчилж харуулна');
    ok(/if \(!todo\.length\) showToast\(/.test(cm) && !/if \(!todo\.length\) \{ showToast\([^\n]*return; \}/.test(cm),
       '⛔ импорт: шинэ зардалгүй ч хуулга + орлого бичигдэнэ (өмнө нь return хийж орлогыг алгасдаг байв)');
    const sv = cm.slice(cm.indexOf('saveBtn.onclick'));
    ok(sv.indexOf('persistStatement(') > sv.indexOf('if (!todo.length) showToast('), 'импорт: орлогын бичилт зардлын дараа ҮРГЭЛЖ ажиллана');
    const rp = codeLines.slice(codeLines.indexOf('function renderReconcilePanel'), codeLines.indexOf('function openReconcileModal'));
    ok(!/recon-file/.test(rp) && /id="recon-import"/.test(rp), '⛔ тулгалтын цонхонд тусдаа импорт БАЙХГҮЙ — нэг хаалга');
    ok(/#recon-import'\)\?\.addEventListener\('click', \(\) => \{ ov\.remove\(\); openStatementClassifyModal\(\); \}\)/.test(codeLines), 'тулгалтын цонхны товч нэгдсэн импортыг нээнэ');
  }
  // ── Тулгалтын цонх: ЗӨВХӨН сонгосон сар ──
  {
    const sv0 = vm.runInContext('[state.finReportMonth, state.bankStatements, state.bankIncome]', sandbox);
    vm.runInContext(`state.finReportMonth = '2026-09';
      state.bankStatements = [
        { id: 'A|2026-08-01|2026-08-31', acct: '111', period_from: '2026-08-01', period_to: '2026-08-31', opening: 0, closing_stated: 100, credit_total: 100, debit_total: 0, ccy: 'MNT' },
        { id: 'A|2026-09-01|2026-09-30', acct: '111', period_from: '2026-09-01', period_to: '2026-09-30', opening: 100, closing_stated: 150, credit_total: 50, debit_total: 0, ccy: 'MNT' }];
      state.bankIncome = [
        { fp: 'x9', dt: '2026-09-12', amount: 50, payer: 'Бат', memo: 'тулгаагүй', status: 'open' },
        { fp: 'x8', dt: '2026-08-12', amount: 70, payer: 'Дорж', memo: 'наймдугаар', status: 'open' }];`, sandbox);
    const h = vm.runInContext('renderStmtLedger()', sandbox);
    ok(/2026-09-01 … 2026-09-30/.test(h) && !/2026-08-01 … 2026-08-31/.test(h), 'тулгалт: зөвхөн сонгосон сарын хуулга');
    ok(/Бат/.test(h) && !/Дорж/.test(h), 'тулгалт: зөвхөн сонгосон сарын хаагдаагүй орлого');
    ok(h.indexOf('Хаагдаагүй орлого') < h.indexOf('сарын эцсийн үлдэгдэл'), 'тулгалт: хийх ажил (хаагдаагүй орлого) ЭХЭНД');
    ok(/<details class="recon-sec recon-fold/.test(h), 'тулгалт: хуулгын жагсаалт эвхмэл');
    vm.runInContext("state.finReportMonth = '2099-01';", sandbox);
    ok(/Сар дуусаагүй/.test(vm.runInContext('renderStmtLedger()', sandbox)), 'тулгалт: дуусаагүй сард «сар дуусаагүй» гэж нэг мөр');
    vm.runInContext(`[state.finReportMonth, state.bankStatements, state.bankIncome] = ${JSON.stringify(sv0)};`, sandbox);
  }
  /* ⛔ Сар хаахыг хоридог бүх нөхцөл НЭГ мөрөнд — аль нэгийг нь чимээгүй хасвал
     тэр дутагдалтайгаар сар хаагдаж, гажсан тоо МӨНХӨД хөлдөнө. */
  ok(/const blocked = miss\.length \|\| pend \|\| oi\.n \|\| chain \|\| balBad/.test(codeLines),
     'scan: дутуу хуулга · АНГИЛААГҮЙ ЗАРДАЛ · хаагдаагүй орлого · залгаа · тэнцэл — бүгд сар хаахыг хорино');
}

/* 0e2b) SCAN — НЭРГҮЙ хуулгын экспортыг импортод ИЛ хэлнэ (2026-10-02)
   Голомт хоёр хэлбэрээр экспортолдог: харилцагчийн НЭРИЙН баганатай, ба
   зөвхөн «Харьцсан данс»-тай (7 багана). Нэргүйг оруулахад мөрийн тоо, дүн,
   тэнцэл БҮГД ЗӨВ гардаг тул өөр ямар ч шалгуур дуугардаггүй — орлогын мөр
   бүрийн «хэн төлсөн» чимээгүй хоосон орно. Анхааруулга нь зардлыг ангилах
   цонхны нэг л газраас гарна; хасагдвал буруу хэлбэр дахин орж мэднэ. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/function stmtNoPayerNames\(/.test(codeLines),
     'scan: нэргүй экспортын шалгуур ганц функцээс (stmtNoPayerNames)');
  ok(/stmtQueue\.filter\(q => stmtNoPayerNames\(q\.parsed\) > 0\)/.test(codeLines),
     'scan: импортын цонх хуулга бүрийг нэргүй эсэхээр шалгана');
  ok(/nameBanner[\s\S]{0,400}нэрний багана байхгүй/.test(codeLines),
     'scan: нэргүй бол хэрэглэгчид ил анхааруулга гарна');
  ok(/warnBanner = prsnBanner \+ salBanner \+ nameBanner/.test(codeLines),
     'scan: тэр анхааруулга анхааруулгын туузанд УГСАРСАН (харагдана)');
}

/* 0e3) SCAN — өөрийн данс/яаралтай холбоог УНШИХ зам (2026-09-30)
   `bank_account` нь /webhook/staff-аас буцаагддаггүй эмзэг талбар тул TEAM-д
   байхгүй. Иймээс ажилтан дансаа бүртгэсэн ч дараагийн ачаалалтад «⚠ Данс
   бүртгэгдээгүй» гэж ДАХИН шаардаж байв. `get_my_profile` RPC үүнийг хаана.
   ⛔ RPC-д УТАС дамжуулж БОЛОХГҮЙ — сервер токеноосоо л авна. Дамжуулбал
      хэн ч хэний ч данс, РД, хаягийг уншиж болох нүх болно. */
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  ok(/rpc\/get_my_profile/.test(codeLines), 'scan: өөрийн профайлыг get_my_profile RPC-ээр уншина');
  const call = codeLines.slice(codeLines.indexOf('rpc/get_my_profile'), codeLines.indexOf('rpc/get_my_profile') + 500);
  eq(/p_phone|phone:/.test(call), false, 'scan: get_my_profile-д УТАС дамжуулахгүй (токеноос авна)');
  ok(/renderMyAttend\(\)[\s\S]{0,260}loadMyProfile\(/.test(codeLines),
     'scan: «Миний ирц» нээхэд өөрийн данс татагдана');
  ok(/loadMyProfile\(true\)/.test(codeLines),
     'scan: профайл хадгалсны дараа серверээс ДАХИН уншиж батална');
}

// 0e3) SCAN — ЗУРАГ ХАРАХ ГАЗАР ГАНЦ: #lightbox (2026-09-19)
// `openStagePhoto` нь `modal-bg`-ээр тусдаа харагч үүсгэдэг байв. `.modal-bg.open`
// нь `display:block` тул дотоод flex хайрцаг дээд-зүүн буланд наалдаж зураг
// ГОЛЛОХГҮЙ, баруун тал нь дэлгэцнээс халин гарна; дэвсгэр нь `rgba(0,0,0,.3)`
// учир ард нь апп бүдгэрч харагдана. 390×844 браузераар хуулбарлаж баталсан.
// #lightbox нь голлодог + аюулгүй бүсийг тооцдог — хоёр дахь харагч БАЙХГҮЙ.
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const body = (codeLines.match(/function openStagePhoto\([\s\S]*?\n\}/) || [''])[0];
  ok(/getElementById\('lightbox-img'\)/.test(body),
     'scan: openStagePhoto нь #lightbox-ийг ашиглана');
  eq((body.match(/modal-bg/g) || []).length, 0,
     'scan: openStagePhoto нь modal-bg-ээр тусдаа харагч үүсгэхгүй');
  eq((body.match(/style="/g) || []).length, 0,
     'scan: openStagePhoto-д inline style байхгүй');
}

// 0e4) SCAN — динамик модал ЗААВАЛ `.open` класстай нээгдэнэ (2026-09-27)
// `.modal-bg` нь styles.css дээр өгөгдмөл `display:none`; `.modal-bg.open` л
// харагдана. Тиймээс модалыг үүсгээд `classList.add('open')` хийхгүй бол модал
// DOM-д БАЙГААД дэлгэцэд ГАРАХГҮЙ — хэрэглэгчид «товч дарагдахгүй» мэт санагдана
// (алдаа ч шидэгдэхгүй тул хэн ч мэдэхгүй). Тооллогын «Тоолсон» товч яг ингэж
// үхмэл байсан: openOpeningCountModal модалаа нээдэг ч `.open` нэмдэггүй байв.
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  const re = /(\w+)\.className = 'modal-bg'/g;
  const missing = [];
  let m;
  while ((m = re.exec(codeLines))) {
    const varName = m[1];
    const rest = codeLines.slice(m.index);
    // Тухайн функцийн төгсгөл = дараагийн дээд түвшний функцийн эхлэл
    const end = rest.search(/\n(?:async )?function /);
    const body = end > 0 ? rest.slice(0, end) : rest;
    if (!body.includes(varName + ".classList.add('open')")) missing.push(varName + '@' + m.index);
  }
  eq(missing.length, 0, 'scan: modal-bg үүсгэсэн бүрд .open класс нэмэгдэнэ (' + missing.join(', ') + ')');
}

// 0f) SCAN — ажилтны картад «Хувийн мэдээлэл» блок үлдэнэ (2026-09-16)
// Яаралтай үеийн холбоо, хаяг, РД, и-мэйл, ажилд орсон огноо нь бүртгэлийн маягтаар
// цуглуулагддаг байтал аппад ХАРАГДАХ газар огт байсангүй — CEO батлах цонхонд нэг л
// удаа гараад дараа нь алга болдог байв (осол гарахад хэнд залгахаа мэдэхгүй).
// Дүрэм: openStaffCardModal нь `info` блокийг заавал рендэрлэнэ.
{
  ok(/const rows = \[\s*\n\s*scTel\('☎️ Яаралтай', m\.emergency_name, m\.emergency_phone\)/.test(src),
     'scan: ажилтны картад яаралтай холбоо бий');
  ok(/<div class="sc-body">\$\{info\}/.test(src),
     'scan: «Хувийн мэдээлэл» блок sc-body-д рендэрлэгдэнэ');
}

// 0g) SCAN — цагийн ажилтны ЖАГСААЛТ ба МӨНГӨ тусдаа эрхтэй (2026-09-16)
// Нярав өдрийн ажилтан дуудахын тулд жагсаалтыг хардаг. Хэн хэдэн төгрөг авсан,
// банкны данс, «Цалин шилжүүлэх» товч нь өөр эрх — `canSeeHourlyMoney()`.
// ⛔ `can('salary.pay')` нь тохируулаагүй үед ЗӨВШӨӨРдөг тул загварт таараагүй ШИНЭ
//    албан тушаал цалинг чимээгүй харна. `capValue(...) === true` л зөв.
{
  ok(/function canSeeHourlyMoney\(\)\s*\{[^}]*capValue\('salary\.pay'\) === true/.test(src),
     'scan: canSeeHourlyMoney нь capValue(...)===true ашиглана (can() БИШ)');
  ok(/\$\{money \? `<button class="btn btn-primary" data-hourly-pay=/.test(src),
     'scan: «Цалин шилжүүлэх» товч мөнгөний эрхээр хаагдана');
  ok(/const paidLine = \(money && sum > 0\)/.test(src),
     'scan: авсан цалингийн мөр мөнгөний эрхээр хаагдана');
  ok(/const bankLine = !money \? ''/.test(src),
     'scan: банкны данс мөнгөний эрхээр хаагдана');
}

// 0j) SCAN — захиалгын хүснэгтийн толгой ба мөр НЭГ багана тодорхойлолтоос (2026-09-04)
// Алдаа: толгой ба мөр тус тусдаа `… 118px auto` гэж бичигдсэн байв. Сүүлийн `auto`
// нь агуулгаас хамаарна — «💵 Төлбөр авах» товчтой мөрөнд ~124px, товчгүй мөрөнд 0 —
// тэгэхээр `1fr` мөр бүрт өөр болж БҮХ багана 112px шилжиж, хойно урд харагдана.
// Дүрэм: хоёулаа `var(--otable-cols)`-ыг л ашиглана; шинэ `auto` сүүлийн багана хориотой.
{
  const css = fs.readFileSync(path.join(__dirname, '..', 'styles.css'), 'utf8');
  // Токен нэг л удаа тодорхойлогдоно, сүүлийн багана нь ТОГТМОЛ px (auto БИШ)
  const tok = (css.match(/--otable-cols:[^;]+;/g) || []);
  eq(tok.length, 1, 'scan: --otable-cols токен нэг л газар');
  ok(/\d+px;$/.test(tok[0] || ''), 'scan: --otable-cols сүүлийн багана тогтмол өргөнтэй (auto биш)');
  // Толгой ба мөр хоёулаа тэр токеноор — тусад нь бичсэн 8 баганын жагсаалт БАЙХГҮЙ
  ok(/\.otable-head\s*\{[^}]*grid-template-columns:\s*var\(--otable-cols\)/.test(css),
     'scan: otable толгой --otable-cols токеныг ашиглана');
  ok(/\.olist-row\s*>\s*summary\s*\{[^}]*grid-template-columns:\s*var\(--otable-cols\)/.test(css),
     'scan: otable мөр --otable-cols токеныг ашиглана');
  // Баганын жагсаалт өөрөө зөвхөн ТОКЕНД байна (утга нь өөрчлөгдөхөд тест хуучрахгүй)
  const cols = (tok[0] || '').replace('--otable-cols:', '').replace(';', '').trim();
  eq(css.split(cols).length - 1, 1,
     'scan: 8 баганын жагсаалт зөвхөн токенд (толгой/мөрд давхардуулахгүй)');
}

// 0j-2) SCAN — workflow YAML-д 0-р баганын мөр БАЙХГҮЙ (2026-09-16)
// Алдаа: `run: |` блок дотор heredoc (`--body "$(cat <<EOF`) бичихэд heredoc-ийн
// мөрүүд 0-р баганад буусан. YAML блок-скаляр тэндээ ТАСАРЧ, файл бүхэлдээ парс
// болохоо больсон. GitHub тэр үед workflow-г нэрээр биш ЗАМААР харуулж,
// `workflow_dispatch` бүртгэгдэхгүй болсон — өөрөөр хэлбэл харуул ЧИМЭЭГҮЙ
// унтарсан, ямар ч алдаа гарaaгүй. Дүрэм: PR/Issue-ийн бичвэрийг heredoc-оор
// биш `printf '%s\n' …`-ээр угсарна (бүх мөр догол мөртэй үлдэнэ).
{
  const dir = path.join(__dirname, '..', '.github', 'workflows');
  const TOP = /^(name|run-name|on|env|permissions|concurrency|defaults|jobs|#|---)/;
  const bad = [];
  for (const f of fs.readdirSync(dir).filter((n) => /\.ya?ml$/.test(n))) {
    fs.readFileSync(path.join(dir, f), 'utf8').split('\n').forEach((ln, i) => {
      if (!ln.trim() || /^\s/.test(ln) || TOP.test(ln)) return;
      bad.push(`${f}:${i + 1}`);
    });
  }
  eq(bad.length, 0, 'scan: workflow YAML-д 0-р баганын мөр байхгүй' +
     (bad.length ? ' → ' + bad.join(', ') : ''));
}

// 0j-3) Шөнийн агентын ажил нэг шөнөд ДУУСАХ хэмжээтэй байх (2026-09-16)
// Алдаа: суггестер хамгийн ИХ хуримтлагдсан функцийг (`kpi`, 200 inline style)
// нэрлэсэн. Агент 40 эргэлтийг дуусгаж унасан — бүр дуусгасан ч 500 мөрийн diff
// хязгаараас хэтэрч merge хийгдэхгүй байсан: суггестер ба merge-ийн хязгаар хоёр
// бие биенийхээ эсрэг ажиллаж байв. Дүрэм: санал болгосон ажил ҮРГЭЛЖ хүрээнд.
{
  const D = require('../tools/debt-check.js');
  const s = D.suggest();
  ok(D.SUG_MAX <= 30, 'шөнийн ажлын дээд хязгаар 30-аас хэтрэхгүй (diff хязгаарт таарна)');
  for (const r of s.top) {
    ok(r.count >= D.SUG_MIN && r.count <= D.SUG_MAX,
       `шөнийн ажил хүрээнд: ${r.fn} = ${r.count} (${D.SUG_MIN}–${D.SUG_MAX})`);
  }
  // Хүрээнээс том нь саналд ОРОХГҮЙ (тэднийг гараар хуваана)
  const names = new Set(s.top.map((r) => r.fn));
  eq(s.oversize.filter((r) => names.has(r.fn)).length, 0,
     'хэт том функц саналд орохгүй');
}

// 0k) Захиалгын жагсаалт — хугацааны бүлэг (Өнөөдөр / Маргааш) (2026-09-04)
// «Самбар» харагдац хасагдаж, бүлэг нь жагсаалтын дотор гарчиг мөр болов.
// Гол дүрэм: дууссан/архив/цуцалсныг ХЭЗЭЭ Ч «өнөөдөр/маргааш» гэж бүлэглэхгүй —
// эс бөгөөс 888 архивласан захиалга «хугацаа хэтэрсэн» болж жагсаалтыг дүүргэнэ.
{
  const T = '2026-09-04';
  // Гол огноо: гарах шатанд АВАХ өдөр, түрээсэнд БУЦААХ өдөр
  eq(F.orderKeyDate({ status: 'reserved', starts_at: '2026-09-01', stops_at: '2026-09-05' }), '2026-09-01', 'бүлэг: гарахаас өмнө авах огноо');
  eq(F.orderKeyDate({ status: 'rented', starts_at: '2026-09-01', stops_at: '2026-09-05' }), '2026-09-05', 'бүлэг: түрээсэнд байхад буцаах огноо');
  eq(F.orderKeyDate({ status: 'reserved' }), '', 'бүлэг: огноогүй бол хоосон');
  // Хугацааны бүлэг
  eq(F.orderTimeGroup({ status: 'reserved', starts_at: '2026-09-04' }, T), 'today', 'бүлэг: өнөөдөр');
  eq(F.orderTimeGroup({ status: 'reserved', starts_at: '2026-09-05' }, T), 'tomorrow', 'бүлэг: маргааш');
  eq(F.orderTimeGroup({ status: 'reserved', starts_at: '2026-09-02' }, T), 'over', 'бүлэг: хугацаа хэтэрсэн');
  eq(F.orderTimeGroup({ status: 'reserved' }, T), 'none', 'бүлэг: огноогүй');
  ['returned', 'archived', 'canceled', 'deleted'].forEach(st => {
    eq(F.orderTimeGroup({ status: st, starts_at: '2026-09-02' }, T), 'closed',
       `бүлэг: «${st}» нь хэтэрсэн биш, дууссан бүлэгт`);
  });
  // Гарчгийн дараалал: хэтэрсэн → өнөөдөр → маргааш → … → дууссан (хамгийн сүүл)
  const G = n => vm.runInContext(n, sandbox);
  const keys = G('ORDER_TIME_GROUPS').map(x => x[0]);
  eq(keys[0], 'over', 'бүлэг: хэтэрсэн нь тэргүүнд');
  eq(keys[1], 'today', 'бүлэг: өнөөдөр хоёрт');
  eq(keys[2], 'tomorrow', 'бүлэг: маргааш гуравт');
  eq(keys[keys.length - 1], 'closed', 'бүлэг: дууссан нь хамгийн сүүлд');
  eq(G('ORDER_SORT_OPTS')[0][0], 'smart', 'бүлэг: эрэмбийн default = хугацаагаар');
}

// 0m) SCAN — гүйцэтгэгч ажилтны мөрөнд МӨНГӨНИЙ мэдээлэл гарахгүй (2026-09-04)
// Утаснаас ажилладаг хүнд барьцаа / НӨАТ / илгээсэн үнийн санал / борлуулалтын
// суваг хэрэггүй — тэдгээр нь картанд бүтэн МӨР эзэлж, ажлын мэдээллийг доош
// түлхдэг. Мөнгөний багана хоосон үед мөр `compact` болж 4 биш 2 мөрт багтана.
{
  const row = src.slice(src.indexOf('function orderListRow('), src.indexOf('function orderListHtml('));
  ok(/_money \?[^\n]*depWarn[^\n]*:[^\n]*badChip, cxChip\]/.test(row),
     'scan: барьцаа/НӨАТ/үнийн санал/суваг шошго зөвхөн мөнгө харах эрхтэйд');
  ok(/class="olist-row\$\{_money \? '' : ' compact'\}/.test(row),
     'scan: мөнгөгүй мөр .compact класстай (утсанд 2 мөрт багтана)');
  ok(/_seeMoney && _site\.site \?/.test(src),
     'scan: сайтын эзлэх хувь = борлуулалтын үзүүлэлт, ажилтанд харагдахгүй');
}

// 0l) SCAN — «Самбар» харагдац БҮРМӨСӨН хасагдсан (2026-09-04)
// Хэрэглэгчийн шийдвэр: нэг харагдац (жагсаалт) л байна. Хоёр харагдац байхад
// нэг нь (самбар) сайжирч, нөгөө нь хоцордог — өнөөдөр/маргааш нь зөвхөн
// самбарт байсан тул утаснаас хардаг ажилчид түүнийг олдоггүй байв.
{
  const css = fs.readFileSync(path.join(__dirname, '..', 'styles.css'), 'utf8');
  ['ordersView', 'ordersBoardOpen', 'renderOrderPipelineBoard', 'boardOrderRow', 'data-oview', 'board-order'].forEach(pat => {
    eq(src.split(pat).length - 1, 0, `scan: самбарын үлдэгдэл «${pat}» байхгүй`);
  });
  ['.oview-toggle', '.bstep', '.board-stepper', '.board-sec', '.oboard'].forEach(pat => {
    eq(css.split(pat).length - 1, 0, `scan: самбарын CSS «${pat}» байхгүй`);
  });
}

// 0g) SCAN — «мөнх хоосон» state талбар БАЙХГҮЙ (2026-09-04)
// ROI 0% алдааны АНГИЛАЛ: `state.x` зарлагдсан ч хэзээ ч бичигддэггүй атлаа
// уншигддаг бол алдаа шидэхгүйгээр ХУДАЛ «0 / хоосон» хариу өгнө. Ийм алдаа
// чимээгүй тул сар турш илэрдэггүй — тэр л ROI-д тохиолдсон.
// Зөвшөөрөгдөх цорын ганц тохиолдол: зориудын статик тохиргоо (`config`).
{
  const codeOnly = src.split('\n').map(l => l.replace(/^\s*\/\/.*$/, '')).join('\n');
  const init = codeOnly.match(/const state = \{([\s\S]*?)\n\};/);
  ok(!!init, 'scan: state эхлүүлэгч олдов');
  const STATIC_OK = ['config'];   // IIFE-ээр нэг удаа бүтээгддэг, өөрчлөгддөггүй
  const dead = [];
  for (const f of [...init[1].matchAll(/^\s{2}([A-Za-z_$][\w$]*)\s*:/gm)].map(x => x[1])) {
    if (STATIC_OK.includes(f)) continue;
    const reads = (codeOnly.match(new RegExp('state\\.' + f + '\\b', 'g')) || []).length;
    const writes = (codeOnly.match(new RegExp(
      'state\\.' + f + '\\s*=[^=]' +
      '|state\\.' + f + '\\s*\\.(push|unshift|splice|set|add|delete|clear|sort)\\(' +
      '|state\\.' + f + '\\s*\\[[^\\]]*\\]\\s*=[^=]' +
      '|state\\.' + f + '\\.[A-Za-z_$][\\w$]*\\s*=[^=]' +
      '|Object\\.assign\\(\\s*state\\.' + f, 'g')) || []).length;
    if (writes === 0 && reads > 1) dead.push(f + ' (' + reads + ' уншилт, 0 бичилт)');
  }
  eq(dead.length, 0, 'scan: мөнх хоосон state талбар байхгүй — ' + (dead.join(', ') || 'цэвэр'));
}

// 0j) SCAN — PIN нь 4-6 оронтой (2026-09-04)
// PIN 4 → 4-6 орон болсон. Хуучин 4 оронтой PIN БҮГД ажилласаар байна.
// ⚠ Сервер тал (n8n «CHIMUN · Login» ба «Reset Verify») мөн `\d{4,6}` — клиентийг
//   ГАНЦААР нь өөрчилвөл 6 оронтой PIN серверт `bad_input` болж нэвтрэлт эвдэрнэ.
// ⚠ Нэвтрэлтийн авто илгээлт ЯГ 4 орон дээр ажиллаж БОЛОХГҮЙ: 6 оронтой хүн
//   бичиж дуусахаас өмнө илгээгдэж «буруу PIN» гэж тоологдоно. Сервер 5 буруу
//   оролдлогын дараа 15 минут ТҮГЖДЭГ тул энэ нь бодит эрсдэл.
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  eq((codeLines.match(/\/\^\\d\{4\}\$\/\.test\(\s*(pin|newPin)/g) || []).length, 0,
     'scan: PIN шалгуур 4 оронтой хатуу биш (\\d{4,6} ашигла)');
  eq((codeLines.match(/pinInput\.value\.length === 4/g) || []).length, 0,
     'scan: нэвтрэлтийн авто илгээлт ЯГ 4 орон дээр ажиллахгүй (6 оронтой PIN тасарна)');
  ok(/slice\(0,\s*6\)/.test(codeLines) && /pinInput/.test(codeLines),
     'scan: PIN оруулга 6 орон хүртэл зөвшөөрнө');
  // ⚠ 2026-09-05: #191 нь app.js-ийг зассан ч index.html-ийн НЭВТРЭХ талбар
  //   `maxlength="4" minlength="4" pattern="[0-9]{4}"` хэвээр үлдсэн. 6 оронтой
  //   PIN-тэй хүн 4-өөс илүү тэмдэгт БИЧИЖ ЧАДАХГҮЙ → буруу PIN → 5 оролдлогын
  //   дараа 15 минут түгжигдэнэ. CEO яг ингэж нэвтэрч чадахгүй болсон.
  const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
  ['login-pin-input', 'reg-pin'].forEach(id => {
    const tag = (html.match(new RegExp('<input id="' + id + '"[^>]*>', 's')) || [''])[0];
    ok(tag, 'scan: ' + id + ' талбар index.html-д байна');
    eq(/maxlength="(\d+)"/.test(tag) ? RegExp.$1 : '', '6',
       'scan: ' + id + ' нь 6 орон хүртэл бичихийг зөвшөөрнө');
    eq(/pattern="\[0-9\]\{4\}"/.test(tag), false,
       'scan: ' + id + ' нь ЯГ 4 орон шаардахгүй ([0-9]{4,6})');
  });
}

// 0l) Ажилтны данс — цалин олгодог хүнд харагдана (2026-09-05)
// Данс/РД/цалин нь ажилтны нийтийн жагсаалтаар ирдэггүй, тусдаа эмзэг сувгаар ирнэ.
// Тэр суваг ЗӨВХӨН CEO-д нээлттэй байсан тул «Цалин» эрх өгсөн захиралд бүх ажилтан
// «данс бүртгэгдээгүй» гэж улаанаар харагдаж, цалин шилжүүлэх боломжгүй байв.
// ⚠ Сервер тал (n8n «CHIMUN · Staff PINs») мөн нээгдэх ёстой — эс бол хүсэлт татгалзана.
//   Тэр үед «denied» гэж ялгаж, ДАХИН оролдохгүй байх ёстой (render бүрд хүсэлт явахаас сэргийлнэ).
{
  const runIn = (code) => vm.runInContext(code, sandbox);
  const save = runIn('[state.isCEO, state.me, state.memberPerms, state._staffPinsLoaded, state._staffPinsErr]');

  runIn("state.isCEO = true; state.me = 'ceo'; state.memberPerms = {};");
  ok(F.canSeeStaffSensitive(), 'данс: CEO харна');

  // Цалин эрхтэй, CEO биш хүн — данс харна (цалин шилжүүлэхэд заавал хэрэгтэй)
  runIn("state.isCEO = false; state.me = '80000001'; state.memberPerms = { '80000001': { salary: true } };");
  ok(F.canSeeStaffSensitive(), 'данс: «Цалин» эрхтэй хүн харна');

  // Цалингийн эрхгүй хүн — харахгүй
  runIn("state.memberPerms = { '80000001': { salary: false } };");
  ok(!F.canSeeStaffSensitive(), 'данс: цалингийн эрхгүй хүн харахгүй');
  ok(/харах эрх алга/.test(F.staffAcctMissingHtml()), 'данс: эрхгүй бол «эрх алга» гэж хэлнэ');

  // Хоосон харагдах шалтгааныг ЯЛГАНА — бүгдийг «бүртгэгдээгүй» гэж хэлэх нь худал
  runIn("state.memberPerms = { '80000001': { salary: true } }; state._staffPinsLoaded = false; state._staffPinsErr = '';");
  ok(/ачаалж байна/.test(F.staffAcctMissingHtml()), 'данс: ачаалж байхад «ачаалж байна»');
  runIn("state._staffPinsLoaded = true; state._staffPinsErr = 'denied'; state._staffPinsReason = 'forbidden';");
  ok(/эрх алга/.test(F.staffAcctMissingHtml()), 'данс: сервер татгалзвал «эрх алга»');
  // ⛔ ШАЛТГААНЫГ ИЛ БИЧНЭ — «сервер эрх өгсөнгүй» гэсэн ганц мессеж нь хугацаа
  //   дууссан токеныг «эрх байхгүй» мэт үзүүлж, хүн юу хийхээ мэдэхгүй сууж байв.
  ok(/forbidden/.test(F.staffAcctMissingHtml()), 'данс: серверийн шалтгаан ил гарна');
  // Дэлгэцийн дээд талд ҮЙЛДЭЛТЭЙ тууз — жижиг сараачлага ганцаараа хангалтгүй.
  ok(/Дахин оролдох/.test(F.staffAcctBannerHtml()), 'данс: татгалзвал дахин оролдох товч');
  runIn("state._staffPinsErr = 'need_login';");
  ok(/Дахин нэвтрэх/.test(F.staffAcctBannerHtml()), 'данс: хугацаа дуусвал нэвтрэх товч');
  runIn("state._staffPinsErr = 'retry';");
  ok(/ачаалж байна/.test(F.staffAcctBannerHtml()), 'данс: түр алдаанд ачаалж байна');
  runIn("state._staffPinsErr = '';");
  eq(F.staffAcctBannerHtml(), '', 'данс: асуудалгүй бол тууз гарахгүй');
  // ⛔ Төлөв хараахан тодорхойгүй (анх ачаалж байгаа) үед ХУДАЛ анхааруулга гаргахгүй.
  runIn("delete state._staffPinsErr;");
  eq(F.staffAcctBannerHtml(), '', 'данс: ачаалагдаагүй үед тууз гарахгүй');
  // Токены агуулга — гарын үсэг ОГТ орохгүй, задарч чадахгүй бол null.
  runIn("state.isCEO = true; localStorage.setItem('sessionToken', 'not-a-token');");
  eq(F.sessionClaims(), null, 'токен: буруу хэлбэр → null');
  eq(F.sessionLevelStale(), false, 'токен: задарсангүй бол «хуучирсан» гэж дүгнэхгүй');
  {
    const mk = (o) => Buffer.from(JSON.stringify(o)).toString('base64url') + '.sig';
    runIn(`localStorage.setItem('sessionToken', ${JSON.stringify(mk({ ph: '80000001', lvl: 40, exp: 4102444800000 }))});`);
    eq(F.sessionClaims().lvl, 40, 'токен: эрхийн түвшин уншигдана');
    // ⛔ Аппад CEO мөртлөө токен нь бага түвшинтэй = ХУУЧИРСАН нэвтрэлт.
    //   «Эрх алга» гэж хэлэх нь худал — дахин нэвтрэх л хэрэгтэй.
    ok(F.sessionLevelStale(), 'токен: CEO мөртлөө lvl бага → хуучирсан');
    runIn(`localStorage.setItem('sessionToken', ${JSON.stringify(mk({ ph: '80000001', lvl: 100, exp: 4102444800000 }))});`);
    ok(!F.sessionLevelStale(), 'токен: lvl 100 бол хуучраагүй');
    runIn("state.isCEO = false;");
    ok(!F.sessionLevelStale(), 'токен: CEO биш хүнд дүрэм хамаарахгүй');
  }
  runIn("state.isCEO = false; localStorage.removeItem('sessionToken');");

  // ── Сесс дууссаныг ил гаргах (2026-09-21) ──
  runIn("state.sessionExpired = false;");
  eq(F.sessionExpiredBannerHtml(), '', 'сесс: асуудалгүй бол тууз гарахгүй');
  runIn("state.sessionExpired = true; state.sessionExpiredAt = 'мэдэгдэл бүртгэх';");
  ok(/Дахин нэвтрэх/.test(F.sessionExpiredBannerHtml()), 'сесс: дууссан бол нэвтрэх товч');
  ok(/мэдэгдэл бүртгэх/.test(F.sessionExpiredBannerHtml()), 'сесс: хаана унасныг хэлнэ');
  runIn("state.sessionExpired = false; state.sessionExpiredAt = '';");
  {
    const _src = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
    // ⛔ Нэвтрэлтийн бүтэлгүйтлийг чимээгүй кэш рүү унагаж БОЛОХГҮЙ — 14 хоногт
    //   ажилтны жагсаалт 42, мэдэгдлийн бүртгэл 56 удаа чимээгүй унасан.
    ok(/n8nUnauthorized\(r\)\) noteAuthFailure\('ажилтны жагсаалт'\)/.test(_src),
       'scan: ажилтны жагсаалт унавал мэдэгдэнэ');
    ok(/n8nUnauthorized\(r\)\) noteAuthFailure\('мэдэгдэл бүртгэх'\)/.test(_src),
       'scan: мэдэгдлийн бүртгэл унавал мэдэгдэнэ');
    ok(/\$\{sessionExpiredBannerHtml\(\)\}/.test(_src), 'scan: тууз Тойм дэлгэцэд гарна');
    ok(/attachSessionBanner\(\)/.test(_src), 'scan: туузны товч холбогдсон');
    // ⛔ Тууз ганцаараа хангалтгүй — сервер токеныг хүчингүй гэж БАТАЛСАН үед
    //   нэвтрэх дэлгэц рүү хүчээр буцаана (хүн тоомсорлохгүй өнгөрдөг).
    ok(/v\.valid === false\) forceRelogin\(\)/.test(_src), 'scan: баталгаатай үед хүчээр гаргана');
    // ⚠ Сүлжээгүй (null) үед ХӨӨХГҮЙ — офлайн ажиллаж байгаа хүнийг тасалдуулна.
    ok(!/serverVerifyToken[\s\S]{0,200}?if \(!v\) forceRelogin/.test(_src),
       'scan: сүлжээгүй үед хөөхгүй');
    // ⛔ Зориудын дахин ачаалалт «гэнэт үхсэн» гэж бүртгэгдэх ёсгүй.
    ok(/clearAlive\(\);[\s\S]{0,160}?location\.reload\(\)/.test(_src),
       'scan: reload-ийн өмнө clearAlive');
  }

  // ⛔ SCAN: `await`-ийн ДАРАА `e.currentTarget` УНШИХГҮЙ (fp 99731bced2c1, 2026-10-03).
  //   Браузер нь үйл явдал дамжуулж дуусмагц `currentTarget`-ыг **null** болгодог тул
  //   async handler-д await-ийн дараа түүнийг уншвал «null is not an object» гэж унана.
  //   Амьд системд PIN шинэчлэх товч: код буруу оруулахад товч мөнхөд «Шинэчилж байна…»
  //   гэж гацаж, хүн дахин оролдож чаддаггүй байв. Товчийг handler-ийн ЭХЭНД хувьсагчид
  //   ав (`const btn = e.currentTarget`) — тэр лавлагаа await-ийн дараа ч хүчинтэй.
  {
    const _src = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
    // Тайлбарыг зайгаар дүүргэнэ (УРТ хэвээр — мөрийн дугаар зөв үлдэнэ): эс бөгөөс
    // тайлбар дотор бичсэн «await» гэдэг үг кодын await мэт уншигдаж ХУДАЛ зөрчил гаргана.
    const noCmt = (s) => s
      .replace(/\/\*[\s\S]*?\*\//g, m => m.replace(/[^\n]/g, ' '))
      .split('\n').map(l => {
        const i = l.indexOf('//');
        if (i < 0 || l[i - 1] === ':') return l;   // `https://…` нь тайлбар БИШ
        return l.slice(0, i) + ' '.repeat(l.length - i);
      }).join('\n');
    const late = [];
    const hre = /async\s*(?:\(\s*(\w+)\s*\)|(\w+))\s*=>\s*\{/g;
    let hm;
    while ((hm = hre.exec(_src))) {
      const p = hm[1] || hm[2];
      const open = _src.indexOf('{', hm.index + hm[0].length - 1);
      let depth = 0, end = -1;
      for (let i = open; i < _src.length; i++) {
        const c = _src[i];
        if (c === '{') depth++;
        else if (c === '}') { depth--; if (depth === 0) { end = i; break; } }
      }
      if (end < 0) continue;
      const body = noCmt(_src.slice(open, end));
      const aw = body.search(/\bawait\b/);
      if (aw < 0) continue;
      const rest = body.slice(aw);
      const cre = new RegExp('\\b' + p + '\\.currentTarget\\b', 'g');
      let cm;
      while ((cm = cre.exec(rest))) {
        const line = _src.slice(0, open + aw + cm.index).split('\n').length;
        if (!late.includes(line)) late.push(line);
      }
    }
    eq(late, [], 'scan: await-ийн дараа e.currentTarget уншихгүй (null болсон байдаг)');
  }

  runIn("state._staffPinsErr = 'denied';");
  // ⛔ SCAN: хугацаа дууссан/гарын үсэг буруу токеныг «эрх алга» гэж бүү тайлбарла —
  //   хүн дахин нэвтрэхээ мэдэхгүй болно (амьд системд яг ингэж гацсан).
  {
    const _src = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
    ok(/\['bad_token', 'bad_sig', 'bad_payload', 'expired'\]\.includes\(why\)/.test(_src),
       'scan: хугацаа/гарын үсэг → дахин нэвтрэх');
    ok(/why === 'staff_unavailable'/.test(_src), 'scan: түр алдаа дахин оролдоно');
    ok(/attachStaffAcctBanner\(\)/.test(_src), 'scan: туузны товч холбогдсон');
    // ⛔ Сервер тодорхой татгалзвал алдааны логт үлдэнэ — эс бөгөөс шалтгааныг
    //   зөвхөн таамаглах болно (данс алга болоход сервер талд ул мөр үлддэггүй байв).
    ok(/_staffPinsErr === 'denied'\) \{[\s\S]{0,600}?dataLoadFailed\(/.test(_src),
       'scan: татгалзал алдааны логт бүртгэгдэнэ');
    // ⛔ Токены ГАРЫН ҮСГИЙГ хэзээ ч логт бүү бич — зөвхөн биеийн талбарууд.
    ok(/sessionClaims\(\)/.test(_src) && !/sessionToken[^\n]{0,40}dataLoadFailed/.test(_src),
       'scan: логт зөвхөн токены агуулга, гарын үсэг БИШ');
  }
  runIn("state._staffPinsErr = 'need_login';");
  ok(/дахин нэвтэрнэ/.test(F.staffAcctMissingHtml()), 'данс: токен дууссан бол «дахин нэвтэрнэ үү»');
  runIn("state._staffPinsErr = '';");
  ok(/бүртгэгдээгүй/.test(F.staffAcctMissingHtml()), 'данс: жинхэнэ хоосон бол «бүртгэгдээгүй»');

  // SCAN — эмзэг суваг зөвхөн state.isCEO дээр түгжигдэхгүй
  ok(/if \(state\._staffPinsLoaded \|\| !canSeeStaffSensitive\(\)\) return;/.test(src),
     'scan: loadStaffPins нь canSeeStaffSensitive()-ээр шалгана (CEO-гоор хатуу биш)');
  // SCAN — давталтын хамгаалалт: renderSalary дуудна, сервер 403 буцаавал хязгааргүй хүсэлт явж БОЛОХГҮЙ
  ok(/_staffPinsTries >= 2/.test(src) && /_staffPinsTries\+\+/.test(src),
     'scan: loadStaffPins сессид 2 оролдлогоор хязгаарлагдана (хүсэлтийн давталт хаана)');
  // SCAN — цалин хуудас өөрөө эмзэг датаг татна (өмнө нь зөвхөн «Ажилчид» хуудсаар татагддаг байв)
  ok(/function renderSalary\(\)[\s\S]{0,400}loadStaffPins\(\)/.test(src),
     'scan: renderSalary нь данс/РД-г өөрөө татна');

  vm.runInContext('state.isCEO = __s[0]; state.me = __s[1]; state.memberPerms = __s[2]; state._staffPinsLoaded = __s[3]; state._staffPinsErr = __s[4];',
    Object.assign(sandbox, { __s: save }));
}

// 0h) canonKey / keyVariants — ажилтны хуучин түлхүүрийг эзэнтэй нь холбох (2026-09-04)
// Нэг ажилтны утас солигдоход 5 хүснэгтийн 16 бичлэг эзэнгүй болж, 360° оноо нь
// БҮРЭН алдагдсан (2026-09-04). Зураглалыг DB талын trigger автоматаар бичдэг;
// энд аппын тал зөв уншиж байгааг бэхжүүлнэ.
{
  const run = (code) => vm.runInContext(code, sandbox);
  const save = run('state.empAliases');

  // alias байхгүй үед ЮУ Ч өөрчлөгдөхгүй (зөөлөн задрал)
  run('state.empAliases = null;');
  eq(run('canonKey')('89904109'), '89904109', 'canonKey: alias байхгүй бол утга хэвээр');
  eq(run('canonKey')(''), '', 'canonKey: хоосон утга аюулгүй');

  run("state.empAliases = { 'phone:89904109':'89985352', 'email:huuchin@a.mn':'89985352', 'name:хуучин нэр':'89985352' };");
  eq(run('canonKey')('89904109'), '89985352', 'canonKey: утсаар шийднэ');
  eq(run('canonKey')('HUUCHIN@a.mn'), '89985352', 'canonKey: мэйл том/жижиг үсэг ялгахгүй');
  eq(run('canonKey')('Хуучин Нэр'), '89985352', 'canonKey: нэрээр шийднэ');
  eq(run('canonKey')('89985352'), '89985352', 'canonKey: одоогийн түлхүүр хэвээр');

  // Транзитив A→B→C
  run("state.empAliases = { 'phone:111':'222', 'phone:222':'333' };");
  eq(run('canonKey')('111'), '333', 'canonKey: транзитив A→B→C');

  // ⚠ Мөчлөг үүсвэл ГАЦААХГҮЙ (оператор дугаарыг дахин олгодог тул бодит эрсдэл)
  run("state.empAliases = { 'phone:111':'222', 'phone:222':'111' };");
  const cyc = run('canonKey')('111');
  ok(cyc === '111' || cyc === '222', 'canonKey: мөчлөг дээр гацахгүй — ' + cyc);

  // keyVariants — сервер талын шүүлтэд БҮХ хувилбар орох ёстой
  run("state.empAliases = { 'phone:89904109':'89985352', 'phone:70001111':'89985352', 'phone:999':'өөр' };");
  const v = run('keyVariants')('89985352');
  ok(v.includes('89985352') && v.includes('89904109') && v.includes('70001111'),
     'keyVariants: бүх хуучин утас багтана — ' + JSON.stringify(v));
  ok(!v.includes('999'), 'keyVariants: өөр хүний alias ОРОХГҮЙ');

  // PostgREST жагсаалт — нэрэнд зай/цэг байж болно тул хашилттай
  eq(run('pgrstInList')(['89985352', 'Б.Тест Нэр']), 'in.("89985352","Б.Тест Нэр")',
     'pgrstInList: утга бүр хашилтад');

  run('state.empAliases = ' + JSON.stringify(save) + ';');
}

// 0i) SCAN — ажилтны түлхүүрээр СЕРВЕР талд шүүхийг хориглоно (2026-09-04)
// PostgREST-ийн шүүлт сервер дээр болдог тул хуучин түлхүүртэй мөр клиент рүү ОГТ
// ирэхгүй — canonKey тэнд туслахгүй. Ийм дуудлага нэмбэл «Миний ирц» ба «Ирцийн
// тайлан» ӨӨР ӨӨР тоо харуулна. Зөв хэлбэр: `${pgrstInList(keyVariants(түлхүүр))}`.
// (member_perms дээрх DELETE нь БИЧИЛТ тул хамаарахгүй — үргэлж одоогийн түлхүүрээр.)
{
  const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
  // Сервер талын RPC хайлт ч мөн адил — `get_employee_doc` нь p_phone-оор хайдаг тул
  // хуучин түлхүүр дор хадгалагдсан баримт олдохгүй. keyVariants-аар дараалан оролдоно.
  const rpcBad = (codeLines.match(/rpc\/get_employee_doc/g) || []).length > 0
              && !/keyVariants\(phone\)/.test(codeLines) ? 1 : 0;
  const bad = rpcBad
            + (codeLines.match(/rest\/v1\/attendance\?[^`'"]*member_key=eq\./g) || []).length
            + (codeLines.match(/rest\/v1\/(evaluations|staff_salary|hourly_ratings)\?[^`'"]*=eq\.\$\{encodeURIComponent\((state\.me|personKey)/g) || []).length;
  eq(bad, 0, 'scan: ажилтны түлхүүрээр сервер талд шүүхгүй (pgrstInList(keyVariants(...)) ашигла)');
}

// 0b) Хүрэлцээ — ХУУЧИРСАН НЭРТЭЙ мөрийг sku-гээр таньж шалгана (2026-09-03)
// Регресс: өмнө нь availabilityFor(it.name) байсан тул сайтаас хуучин нэртэй мөр
// ирэхэд productByName олдохгүй → null → «Хүрэлцэхгүй» ОГТ гардаггүй байв.
{
  const runIn = (code) => vm.runInContext(code, sandbox);
  const save = runIn('[state.products, state.appOrders]');
  runIn("state.products = [{ id:'M-100', sku:'M-100', name:'Цагаан ширээ 180см', price:10000, qty_mevent:5, stock:5 }]; state.appOrders = [];");
  const SH = runIn('orderShortages'), AV = runIn('availabilityFor');

  ok(SH([{ sku:'M-100', name:'Цагаан ширээ 180см', qty:9 }], '2026-10-01', '2026-10-02').length === 1,
     'хүрэлцээ: зөв нэрээр хүрэлцэхгүйг барина');
  ok(SH([{ sku:'M-100', name:'Ширээ (хуучин нэр)', qty:9 }], '2026-10-01', '2026-10-02').length === 1,
     'хүрэлцээ: ХУУЧИРСАН нэртэй ч sku-гээр таньж барина');
  ok(SH([{ sku:'M-100', name:'Ширээ (хуучин нэр)', qty:3 }], '2026-10-01', '2026-10-02').length === 0,
     'хүрэлцээ: хүрэлцэж байвал анхааруулахгүй');
  ok(SH([{ sku:'ZZZ', name:'Байхгүй бараа', qty:99 }], '2026-10-01', '2026-10-02').length === 0,
     'хүрэлцээ: каталогт байхгүй бол шалгахгүй');

  const aItem = AV({ sku:'M-100', name:'хуучин' }, '2026-10-01', '2026-10-02');
  const aName = AV('Цагаан ширээ 180см', '2026-10-01', '2026-10-02');
  ok(aItem && aName && aItem.stock === aName.stock && aItem.avail === aName.avail,
     'availabilityFor: мөрөөр ба каноник нэрээр ижил');

  runIn('state.products = ' + JSON.stringify(save[0] || []) + '; state.appOrders = ' + JSON.stringify(save[1] || []) + ';');
}

// 5c) SCAN — reserveReceipt-ийн үр дүнг ЦАГААН жагсаалтаар шалгана (2026-09-03)
// Дүрэм 2: 'dup'-ыг хар жагсаалтаар барих нь 'err'-ийг 'ok' мэт нэвтрүүлдэг →
// сүлжээ/эрх унахад давхар баримтын хамгаалалт ЧИМЭЭГҮЙ унтардаг байв.
// Энэ scan нь: 'dup' шалгадаг газар бүр 'err'-ийг мөн шалгасан байх ёстой.
{
  const dupChecks = (src.match(/rr === 'dup'/g) || []).length;
  const errChecks = (src.match(/rr === 'err'/g) || []).length;
  ok(dupChecks > 0, 'scan: reserveReceipt дуудагч олдов (' + dupChecks + ')');
  ok(errChecks >= dupChecks,
     "scan: 'dup' шалгадаг газар бүр 'err'-ийг мөн шалгана (dup=" + dupChecks + ", err=" + errChecks + ')');
}

// 0d) SCAN — view бүр safeViewHtml-ээр хамгаалагдсан байна (2026-09-03)
// Рендер алдаа шидвэл wrap.innerHTML хоосон үлдэж апп «үхсэн» мэт харагдана —
// цэс дарахад юу ч болохгүй, алдааны мессеж ч гарахгүй. safeViewHtml нь try/catch
// хийж хэрэглэгчид ойлгомжтой мессеж үзүүлнэ. Аудит: 15 view-ээс 13 нь хамгаалалтгүй байв.
{
  const bare = (src.match(/wrap\.innerHTML\s*=\s*render[A-Z]/g) || []).length;
  eq(bare, 0, 'scan: view рендер бүр safeViewHtml-ээр хамгаалагдсан');
}

// 0c) SCAN — CACHE_TAG-ийг ЗӨВХӨН globalThis-ээр уншина (2026-09-03)
// `typeof X === 'string' ? X : ''` дэх ХОЁР ДАХЬ лавлагаа нь no-undef-д баригдаж
// CI-г улаан болгодог. 2026-09-03-нд хоёр удаа тохиолдсон — эхнийх нь 2 газар
// зассаны дараа өөр сесс 3 дахь газар нэмсэн. Тиймээс ХЭВ МАЯГИЙГ хаана.
{
  const bare = (src.match(/(?<!globalThis\.)\bCACHE_TAG\b/g) || []).length;
  eq(bare, 0, 'scan: CACHE_TAG зөвхөн globalThis.CACHE_TAG хэлбэрээр (no-undef)');
}

// 0a) SCAN — PostgREST дуудлага бүр НЭВТЭРСЭН токеноор явна (2026-09-03)
// pgrstBearer() = pgrstToken() || DB_ANON_KEY — токенгүй бол anon руу унана, тул
// солих нь юуг ч эвдэхгүй. Харин anon-ы УНШИХ эрхийг ирээдүйд хаах боломж нээгдэнэ.
// Шинэ код `Bearer ' + DB_ANON_KEY` бичвэл тэр бараа дахин anon-оор явна.
{
  const anonBearer = (src.match(/Authorization: 'Bearer ' \+ DB_ANON_KEY/g) || []).length;
  eq(anonBearer, 0, "scan: PostgREST дуудлагад 'Bearer ' + DB_ANON_KEY БАЙХГҮЙ (pgrstBearer() ашигла)");
}

// 0g) SCAN — «Бараа & хөрөнгө» дэлгэц захиалгын датаг АЧААЛНА (2026-09-04)
// productUtilization (ROI, «N удаа · орлого») нь state.appOrders-оос уншина.
// Дэлгэц түүнийг ачаалахгүй бол state.appOrders === undefined хэвээр үлдэж
// БҮХ барааны ROI 0% харагдана — хөрөнгийн шийдвэр худал тоон дээр гарна.
// #162 функцийг зассан ч ачаалалт дутуу үлдсэн (амьд дэлгэцээр илрэв).
{
  const line = src.split('\n').find(l => l.includes("v === 'products'") && l.includes('canSeeProducts'));
  ok(!!line, 'scan: products дэлгэцийн ачаалалтын мөр олдов');
  ok(/loadAppOrders/.test(line || ''), 'scan: products дэлгэц loadAppOrders дуудна (ROI мөнх 0% болохоос сэргийлнэ)');
}

// 0f) SCAN — барааны модалын таб задаргаа талбар алдагдуулаагүй байх (2026-09-04)
// openProductModal 25 талбартай нэг цонх байсныг Каталог/Үнэ/Нөөц 3 таб болгосон.
// Талбар аль ч pane-д ороогүй үлдвэл ЧИМЭЭГҮЙ алдагдана: submitProductModal нь
// querySelector-оос null авч үнэ 0, нөөц 0 болгож хадгална. Тиймээс модал болон
// submit-ийн УНШДАГ pm-* id бүр модалын HTML-д зарлагдсан байх ёстой.
{
  // Гарын үсгээс ХАМААРАЛГҮЙ (openProductModal(p) → (p, opts) болоход тест унасан)
  const openSrc = src.slice(src.indexOf('function openProductModal('), src.indexOf('async function submitProductModal('));
  const _rest = src.slice(src.indexOf('async function submitProductModal('));
  const submitSrc = _rest.slice(0, _rest.indexOf('\nfunction attachProductsHandlers('));
  const read = new Set();
  [openSrc, submitSrc].forEach(t => {
    // Сүүлчийн зураас дээр таслахгүй: тайлбар дахь `#pm-media-д` (кирилл) нь
    // `pm-media-` болж худал сэрэмжлүүлэг өгдөг байв.
    (t.match(/#(pm-[a-z]+(?:-[a-z]+)*)/g) || []).forEach(m => read.add(m.slice(1)));
    (t.match(/g\('(pm-[a-z-]+)'\)/g) || []).forEach(m => read.add(m.slice(3, -2)));
  });
  const declared = new Set((openSrc.match(/id="(pm-[a-z-]+)"/g) || []).map(m => m.slice(4, -1)));
  eq([...read].filter(id => !declared.has(id)), [], 'scan: модалын уншдаг pm-* id бүр HTML-д зарлагдсан');
  ok(declared.size >= 20, 'scan: барааны модалын талбарууд бүрэн (' + declared.size + ')');

  // Меню мөр / буцах товч бүр БАЙГАА хэсэг рүү заана. Нэг нь зөрвөл тэр бүлэг
  // талбар бүрмөсөн нуугдана (эсвэл хоосон дэлгэц гарна).
  const gos = [...new Set((openSrc.match(/data-pmgo="[a-z]+"/g) || []).map(m => m.slice(11, -1)))].sort();
  const panes = [...new Set((openSrc.match(/data-pmpane="[a-z]+"/g) || []).map(m => m.slice(13, -1)))].sort();
  eq(panes, ['cat', 'cost', 'menu', 'price', 'stock'], 'scan: барааны модал = меню + 4 хэсэг');
  eq(gos, panes, 'scan: меню/буцах товч бүр байгаа хэсэг рүү заана');

  // Хэсэг бүр ТҮГЖИГДЭХ хайрцагтай — эс бөгөөс эрхгүй хүнд задгай үлдэнэ.
  const locks = [...new Set((openSrc.match(/data-pmlock="[a-z]+"/g) || []).map(m => m.slice(13, -1)))].sort();
  eq(locks, ['cat', 'cost', 'price', 'stock'], 'scan: 4 хэсэг тус бүр түгжигдэх хайрцагтай');

  // ХАДГАЛАГДДАГ талбар бүр аль нэг хэсэгт ХАРЬЯАЛАГДАНА. Шинэ талбар нэмээд
  // хэсэгт хуваарилахаа мартвал эрхгүй хүн түүнийг дарж бичих боломжтой үлдэнэ.
  {
    const b = submitSrc.slice(submitSrc.indexOf('const base = {'));
    const baseSrc = b.slice(0, b.indexOf('\n  };'));
    const written = [...new Set((baseSrc.match(/([a-z_]+):/g) || []).map(m => m.slice(0, -1)))];
    const owned = new Set(Object.values(F.productPartFields()).flat());
    const exempt = new Set(['sku', 'code', 'variant_group', 'variant_label']);   // өөрчлөгддөггүй таних талбар
    eq(written.filter(f => !owned.has(f) && !exempt.has(f)), [], 'scan: хадгалагддаг талбар бүр хэсэгт харьяалагдана');
  }
}

// 1) НӨАТ токен round-trip
eq(F.parseVat(F.encodeVat(15000)), 15000, 'НӨАТ токен: encode→parse round-trip');
eq(F.parseVat('note ' + F.encodeVat(0)), 0, 'НӨАТ токен: 0 дүн');
eq(F.parseVat('токенгүй note'), null, 'НӨАТ токен: байхгүй бол null');

// 2) Харилцагчийн мэдээлэл (CI) токен
{
  const ci = { company: 'Түшиг ХХК', reg: '1234567', contact: 'FB: mevent', maps: 'https://maps.google/x' };
  const note = F.setCustInfo('үндсэн note', ci);
  eq(F.custInfoOf(note), ci, 'CI токен: setCustInfo→custInfoOf round-trip');
  ok(note.indexOf('үндсэн note') === 0, 'CI токен: үндсэн note хадгалагдана');
}
eq(F.custInfoOf('token байхгүй'), {}, 'CI токен: байхгүй бол {}');
// injection хамгаалалт — ⟦⟧ тэмдэгт зайлуулагдана
{
  const note = F.setCustInfo('', { company: 'Му⟧ухай⟦ХХК' });
  const back = F.custInfoOf(note);
  ok(!/[⟦⟧]/.test(back.company || ''), 'CI токен: ⟦⟧ injection зайлуулна');
}

// 3) Хүргэлт токен
{
  const enc = F.encodeDelivery('city', 5, 150000);
  const d = F.parseDelivery('note ' + enc);
  eq({ zone: d.zone, km: d.km, fee: d.fee }, { zone: 'city', km: 5, fee: 150000 }, 'Хүргэлт токен: encode→parse');
}
eq(F.parseDelivery('токенгүй'), null, 'Хүргэлт токен: байхгүй бол null');

// 3b) Суурилуулалт токен + нэгж хөлс
{
  // encode→parse round-trip (флаг + хөлс)
  const enc = F.encodeSetup(true, 75000);
  eq(F.setupFlagOf('note ' + enc), true, 'Суурилуулалт токен: флаг=true');
  eq(F.setupFeeOf('note ' + enc), 75000, 'Суурилуулалт токен: хөлс уншина');
  // хуучин 2 хэсэгтэй токентой нийцтэй (хөлсгүй) → фээ 0
  eq(F.setupFlagOf('⟦SET|1⟧'), true, 'Суурилуулалт токен: хуучин ⟦SET|1⟧ флаг');
  eq(F.setupFeeOf('⟦SET|1⟧'), 0, 'Суурилуулалт токен: хуучин токенд хөлс 0');
  eq(F.setupFlagOf('⟦SET|0⟧'), false, 'Суурилуулалт токен: 0 = false');
  eq(F.encodeSetup(false, 99999), '⟦SET|0⟧', 'Суурилуулалт токен: off бол хөлс кодлохгүй');
  eq(F.setupFlagOf('токенгүй'), null, 'Суурилуулалт токен: байхгүй бол null');
  // нэгж хөлс — барааны нэрээр
  eq(F.setupRateForName('Тайз 2х2м'), 30000, 'Нэгж хөлс: тайз=30000');
  eq(F.setupRateForName('Сүлжмэл сандал'), 500, 'Нэгж хөлс: сандал=500');
  eq(F.setupRateForName('Танихгүй бараа'), 1000, 'Нэгж хөлс: default=1000');
  // нийт хөлс = тоо × нэгж, доод хязгаартай
  eq(F.setupFeeForItems([{ name: 'Тайз', qty: 3 }]), 90000, 'Нийт хөлс: 3×30000=90000');
  eq(F.setupFeeForItems([{ name: 'Сандал', qty: 10 }]), 50000, 'Нийт хөлс: 10×500=5000 → доод хязгаар 50000');
  eq(F.setupFeeForItems([]), 0, 'Нийт хөлс: бараагүй = 0');
  // каталогийн setup (item.setup) нэрээр таамагласнаас ДАВУУ
  eq(F.setupUnitFee({ name: 'Сандал', setup: 3000 }), 3000, 'Нэгж хөлс: каталогийн setup давуу');
  eq(F.setupUnitFee({ name: 'Сандал' }), 500, 'Нэгж хөлс: setup байхгүй → нэрээр');
  eq(F.setupFeeForItems([{ name: 'Сандал', qty: 100, setup: 3000 }]), 300000, 'Нийт хөлс: каталогийн setup×тоо');
  // Үнийн саналын хямдрал — нийт дүнгээс гаргах (задаргаа нийт дүнтэй тэнцэнэ)
  // #1478 бодит кейс: түрээс 6.6сая, хүргэлт 150k, нийт 3.45сая → хямдрал = 3.3сая (50%), 4.62сая БИШ
  eq(F.quoteDiscountFromTotal(6600000, 150000, 0, 0, 0, 0, 3450000), 3300000, 'Quote хямдрал: #1478 = 3.3сая (давхар тоолохгүй)');
  // сайтын авто-20% total-д шингэсэн, гар хямдралгүй → 20% харагдана
  eq(F.quoteDiscountFromTotal(1000000, 0, 0, 0, 0, 0, 800000), 200000, 'Quote хямдрал: авто-20% total-аас');
  // хямдралгүй — задаргаа тэнцэнэ (хүргэлт+барьцаа+НӨАТ)
  eq(F.quoteDiscountFromTotal(1000000, 100000, 0, 0, 50000, 25000, 1125000), 0, 'Quote хямдрал: хямдралгүй = 0');
  eq(F.quoteDiscountFromTotal(6600000, 150000, 0, 0, 0, 0, 0), 0, 'Quote хямдрал: total 0 бол 0 (ноорог)');
  // NOMAAD цуглуулсан орлого — сарын харьяалал (C5): олон удаагийн төлбөр зөв сард, Σ = nomaadPaid
  {
    const log = [{ total: 500000, pay_date: '2026-08-15' }, { total: 300000, pay_date: '2026-09-02' }];
    eq(F._nomaadMonthSum(log, 800000, '2026-09-02', '2026-08'), 500000, 'NOMAAD сар: 8-р сард төлбөр₁');
    eq(F._nomaadMonthSum(log, 800000, '2026-09-02', '2026-09'), 300000, 'NOMAAD сар: 9-р сард төлбөр₂');
    eq(F._nomaadMonthSum(log, 800000, '2026-09-02', '2026-08') + F._nomaadMonthSum(log, 800000, '2026-09-02', '2026-09'), 800000, 'NOMAAD сар: Σ = nomaadPaid');
    // лог хоосон — running total-ыг income_date сард
    eq(F._nomaadMonthSum([], 800000, '2026-09-02', '2026-09'), 800000, 'NOMAAD сар: логгүй → income_date сард');
    eq(F._nomaadMonthSum([], 800000, '2026-09-02', '2026-08'), 0, 'NOMAAD сар: логгүй, өөр сар = 0');
    // лог дутуу (running total их) — зөрүү income_date сард
    const partial = [{ total: 500000, pay_date: '2026-08-15' }];
    eq(F._nomaadMonthSum(partial, 800000, '2026-09-02', '2026-08'), 500000, 'NOMAAD сар: лог дутуу, 8-р сар = логоор');
    eq(F._nomaadMonthSum(partial, 800000, '2026-09-02', '2026-09'), 300000, 'NOMAAD сар: лог дутуу, зөрүү 9-р сард');
  }
  // Захиалгын хямдрал — авто-хоног ба гар хямдралын их нь (C3, сувгаар парити)
  eq(F.orderDiscountAmount(1000000, 3, 'pct', 0), 200000, 'C3: 3 хоног авто −20% (гар 0)');
  eq(F.orderDiscountAmount(1000000, 7, 'pct', 0), 400000, 'C3: 7 хоног авто −40%');
  eq(F.orderDiscountAmount(1000000, 1, 'pct', 0), 0, 'C3: 1 хоног авто-хямдралгүй');
  eq(F.orderDiscountAmount(1000000, 3, 'pct', 30), 300000, 'C3: гар 30% > авто 20% → гар');
  eq(F.orderDiscountAmount(1000000, 3, 'pct', 10), 200000, 'C3: гар 10% < авто 20% → авто (доод хамгаалалт)');
  eq(F.orderDiscountAmount(1000000, 3, 'amount', 500000), 500000, 'C3: гар дүн 500k > авто 200k → гар');
  // orderMoneyBreakdown — ГАНЦ эх сурвалж: задаргаа нийт дүнтэй ҮРГЭЛЖ тэнцэнэ (үнийн санал+гэрээ ижил)
  {
    // #1478 бодит кейс: түрээс 6.6сая, хүргэлт 150k, нийт 3.45сая → хямдрал 3.3сая (50%)
    const o = { subtotal_mnt: 6600000, total_mnt: 3450000, deposit_mnt: 0, discount_type: 'pct', discount_value: 50, starts_at: '2026-09-15', stops_at: '2026-09-18', note: '⟦DLV|city|0|150000⟧' };
    const b = F.orderMoneyBreakdown(o);
    eq(b.subtotal, 6600000, 'breakdown: subtotal');
    eq(b.delivFee, 150000, 'breakdown: delivFee');
    eq(b.discount, 3300000, 'breakdown: хямдрал total-аас (3.3сая, 4.62сая БИШ)');
    eq(b.subtotal - b.discount - b.vatDisc + b.delivFee + b.offFee + b.setupFee + b.deposit, b.total, 'breakdown: задаргаа = нийт дүн (үргэлж тэнцэнэ)');
    // НӨАТ хассан + барьцаатай кейс — мөн тэнцэнэ
    const o2 = { subtotal_mnt: 1000000, total_mnt: 1075000, deposit_mnt: 200000, note: '⟦DLV|city|0|100000⟧ ⟦VAT|25000⟧' };
    const b2 = F.orderMoneyBreakdown(o2);
    eq(b2.subtotal - b2.discount - b2.vatDisc + b2.delivFee + b2.offFee + b2.setupFee + b2.deposit, b2.total, 'breakdown: НӨАТ+барьцаатай ч тэнцэнэ');
  }
  // Тариф fallback (app_config байхгүй үед) — одоогийн утгыг цоожилно (C2, сайттай ижил байх ёстой)
  eq(F.tariffDeliveryCity(), 150000, 'Тариф fallback: хот дотор 150,000');
  eq(F.tariffPerKm(), 5000, 'Тариф fallback: км тутам 5,000');
  eq(F.tariffOffhoursFee(), 10000, 'Тариф fallback: ажлын бус цаг 10,000₮/ЦАГ');
  eq(F.tariffOffhoursFirstFee(), 20000, 'Тариф fallback: ЭХНИЙ цаг 20,000₮');
  /* ⛔ ЭХНИЙ ЦАГ ҮНЭТЭЙ — шөнө ажилтан дуудах нь өөрөө зардалтай. */
  eq(F.offHoursFeeFor(0), 0, 'хөлс: 0 цаг = 0');
  eq(F.offHoursFeeFor(1), 20000, 'хөлс: 1 цаг = 20,000');
  eq(F.offHoursFeeFor(3), 40000, 'хөлс: 3 цаг = 20,000 + 2×10,000');
  eq(F.offHoursFeeFor(5), 60000, 'хөлс: 5 цаг = 20,000 + 4×10,000');
  // ⚠ ЦЭГ ТУС БҮРД өөрийн «эхний цаг» — хоёр өөр удаа дуудаж байна
  eq(F.orderOffHoursFeeOf(7, 20), 60000, 'хөлс: 07:00 ба 20:00 = 30,000 × 2');
  eq(F.orderOffHoursFeeOf(10, 16), 0, 'хөлс: ажлын цагт 0');
  /* ⛔ ЦАГ БҮРТ, «авах/өгөх бүрт» БИШ (2026-10-05, CEO). 19:00-д ба 23:00-д
     буцаахыг ижил үнээр бодох нь буруу байв. */
  eq(F.offHoursSpan(21), 3, 'бус цаг: 21:00 = 18-аас 3 цаг хойш');
  eq(F.offHoursSpan(7), 2, 'бус цаг: 07:00 = 09-өөс 2 цаг өмнө');
  eq(F.offHoursSpan(12), 0, 'бус цаг: ажлын цагт 0');
  eq(F.offHoursSpan(18), 0, 'бус цаг: 18:00 нь ажлын цаг (хил дээр)');
  eq(F.offHoursSpan(9), 0, 'бус цаг: 09:00 нь ажлын цаг (хил дээр)');
  eq(F.offHoursSpan('х'), 0, 'бус цаг: уншигдаагүй утга 0');
  eq(F.orderOffHoursCount(7, 21), 5, 'бус цаг: хоёр цэгийн нийлбэр (2+3)');
  eq(F.orderOffHoursCount(10, 16), 0, 'бус цаг: хоёулаа ажлын цагт 0');
  eq(F.calcDeliveryFee('city', 0), 150000, 'Хүргэлт: хот дотор 150,000');
  eq(F.calcDeliveryFee('out', 12), 120000, 'Хүргэлт: 12км × 2 × 5,000 = 120,000');
  eq(F.calcDeliveryFee('pickup', 0), 0, 'Хүргэлт: өөрөө авах 0');
  // Хот дотор НЭГ тал — очих+буцахаас хямд байх ёстой (хоёр талыг давхар авахгүй)
  eq(F.tariffDeliveryCityOne(), 80000, 'Тариф fallback: хот дотор нэг тал 80,000');
  eq(F.calcDeliveryFee('city1', 0), 80000, 'Хүргэлт: хот дотор нэг тал 80,000');
  ok(F.calcDeliveryFee('city1', 0) < F.calcDeliveryFee('city', 0), 'Хүргэлт: нэг тал < очих+буцах');
  // ⚠ zone-д цифр бий (city1) — _DLV_RE [a-z]+ хэвээр бол токен УНШИГДАХГҮЙ, төлбөр чимээгүй алга болно
  {
    const d = F.parseDelivery('note ' + F.encodeDelivery('city1', 0, 80000));
    eq(d && { zone: d.zone, fee: d.fee }, { zone: 'city1', fee: 80000 }, 'Хүргэлт токен: city1 унших');
  }
  eq([F.isDeliveryZone('city'), F.isDeliveryZone('city1'), F.isDeliveryZone('out'), F.isDeliveryZone('pickup')],
     [true, true, true, false], 'Хүргэлттэй бүс: pickup-аас бусад нь тийм');
  // Буцаан олголт токен + барьцааны буцаалт төрөл (C11)
  {
    // барьцааны буцаалт — kind='dep' round-trip
    const n1 = F.encodeRefundNote('', 200000, 'цуцлагдсан', 'dep');
    const r1 = F.parseRefund(n1);
    eq({ amount: r1.amount, note: r1.note, kind: r1.kind }, { amount: 200000, note: 'цуцлагдсан', kind: 'dep' }, 'Refund: барьцаа (dep) round-trip');
    // хоосон шалтгаантай ч dep хадгалагдана
    const r2 = F.parseRefund(F.encodeRefundNote('', 200000, '', 'dep'));
    eq({ amount: r2.amount, kind: r2.kind }, { amount: 200000, kind: 'dep' }, 'Refund: шалтгаангүй ч dep');
    // ерөнхий буцаалт (kind байхгүй) — dep БИШ
    const r3 = F.parseRefund(F.encodeRefundNote('note', 150000, 'илүү төлөлт'));
    eq({ amount: r3.amount, note: r3.note, kind: r3.kind }, { amount: 150000, note: 'илүү төлөлт', kind: '' }, 'Refund: ерөнхий буцаалт dep БИШ');
    // хуучин 2 хэсэгтэй токентой нийцтэй
    eq(F.parseRefund('⟦RF|100000⟧').kind, '', 'Refund: хуучин токенд kind хоосон');
    // ⭐ НЭГ ГҮЙЛГЭЭ = БАРЬЦАА + ЗӨРҮҮ (2026-09-22, захиалга #1476)
    // Ажилтан барьцаа ба бараа багассаны зөрүүг НЭГ шилжүүлэгээр илгээдэг.
    // Токенд барьцааны ХЭСЭГ тусад нь үлдэхгүй бол зөрүү ч «барьцаа» болж өр уусна.
    {
      const n = F.encodeRefundNote('', 271000, 'сандал аваагүй зөрүү', 'dep', 150000);
      const r = F.parseRefund(n);
      eq({ amount: r.amount, kind: r.kind, dep: r.dep }, { amount: 271000, kind: 'dep', dep: 150000 },
         'Refund: нийт 271,000₮-ийн 150,000₮ нь барьцаа гэж тусад нь үлдэнэ');
      eq(F.parseRefund(F.encodeRefundNote('', 271000, '', 'dep', 400000)).dep, 271000,
         '⛔ барьцааны хэсэг нийтээс хэтрэхгүй');
      eq(F.parseRefund(F.encodeRefundNote('', 271000, '', '', 150000)).dep, 0,
         '⛔ арилжааны буцаалтад барьцааны хэсэг бичигдэхгүй');
      eq(F.parseRefund('⟦RF|150000||dep⟧').dep, 0, 'хуучин dep токенд 5-р талбар байхгүй');
    }
  }
}

// 4) Эхлэх/дуусах цаг токен
{
  const enc = F.encodeOrderTimes(9, 18);
  const t = F.parseOrderTimes('note ' + enc);
  eq({ sh: t.sh, eh: t.eh }, { sh: 9, eh: 18 }, 'Цаг токен: encode→parse');
}

// 4b) orderDateTime — огноо + ⟦RT⟧ цаг нэгтгэх (2026-09-04)
// Регресс: `starts_at`/`stops_at` нь ЗӨВХӨН огноо, формын цаг ⟦RT⟧ токенд хадгалагддаг.
// Үнийн санал/гэрээ нь огноог шууд уншдаг байсан тул АВАХ ЦАГ хэзээ ч гардаггүй байв
// (гэрээнд «……» цаг гэж хэвлэгддэг). Ажлын бус цагийн +төлбөр яг тэр цагаас тооцогддог
// тул харилцагч ямар цагаас төлбөр нэмэгдсэнийг баримтаас харах ёстой.
need(['orderDateTime']);
{
  const note = 'тэмдэглэл ' + F.encodeOrderTimes(8, 20);
  eq(F.orderDateTime('2026-09-10', note, false), '2026-09-10T08:00', 'orderDateTime: эхлэх цаг огноотой нийлнэ');
  eq(F.orderDateTime('2026-09-12', note, true),  '2026-09-12T20:00', 'orderDateTime: дуусах цаг огноотой нийлнэ');
  // токенгүй (хуучин мөр) — огноо хэвээр, хуурамч цаг зохиохгүй
  eq(F.orderDateTime('2026-09-10', '', false), '2026-09-10', 'orderDateTime: ⟦RT⟧ байхгүй бол огноо хэвээр');
  // огноонд аль хэдийн цаг байвал (booqable түүх) ХӨНДӨХГҮЙ
  eq(F.orderDateTime('2026-09-10T14:30', note, false), '2026-09-10T14:30', 'orderDateTime: байгаа цагийг дарж бичихгүй');
  eq(F.orderDateTime('', note, false), '', 'orderDateTime: огноогүй бол хоосон');
  // шөнө дунд (0 цаг) — falsy тул алдагдаж болзошгүй
  eq(F.orderDateTime('2026-09-10', F.encodeOrderTimes(0, 23), false), '2026-09-10T00:00', 'orderDateTime: 00 цаг алдагдахгүй');
}

// 4c) Гэрээнд авах/өгөх цаг хэвлэгдэнэ (дээрх алдааны нөхөн үзүүлэлт)
{
  const ord = {
    number: 7, customer: 'Тест ХХК', order_no: 'ME-7',
    starts_at: '2026-09-10', stops_at: '2026-09-12',
    total_mnt: 500000, deposit_mnt: 0,
    items: [{ name: 'Ширээ', qty: 2, price: 10000, total: 40000 }],
    note: F.encodeOrderTimes(8, 20),
  };
  const ct = F.meventContractHtml(ord);
  ok(ct.indexOf('2026-09-10 08:00') > -1, 'гэрээ/цаг: эхлэх огноо+цаг хэвлэгдэнэ');
  ok(ct.indexOf('2026-09-12 20:00') > -1, 'гэрээ/цаг: дуусах огноо+цаг хэвлэгдэнэ');
  // цагийн байрлалд бөглөх «……» үлдэхгүй (гарын үсгийн мөрийн «……» нь ӨӨР — түүнийг хөндөхгүй)
  ok(!/Эхлэх:[^<]*<b>[^<]*……/.test(ct), 'гэрээ/цаг: цагийн оронд «……» үлдэхгүй');
}

// 5) cleanAppNote — токенуудыг цэвэрлэнэ, үндсэн текст үлдэнэ
{
  const note = 'Жинхэнэ тэмдэглэл ' + F.encodeVat(5000) + ' ' + F.encodeDelivery('out', 10, 50000);
  const clean = F.cleanAppNote(note);
  ok(clean.indexOf('Жинхэнэ тэмдэглэл') === 0, 'cleanAppNote: үндсэн текст үлдэнэ');
  ok(!/⟦VAT/.test(clean) && !/⟦DLV/.test(clean), 'cleanAppNote: токенууд арилна');
}

// 5b) stripFormTokens — захиалгын форм ЗӨВХӨН өөрийн токеныг солино (2026-09-03)
// Регресс: өмнө нь cleanAppNote-оор бүгдийг арилгаж байсан тул захиалга засах бүрд
// санхүүгийн бүртгэсэн ⟦PAY⟧ ба буцаалтын ⟦RF⟧ УСТДАГ байв.
{
  const foreign = '⟦PAY|500000|бүтэн|данс|2026-09-01|ITZONE⟧ ⟦RF|120000⟧ ⟦DMG|сандал⟧ ⟦CX|цуцлав⟧';
  const own = F.encodeVat(5000) + ' ' + F.encodeDelivery('out', 10, 50000) + ' ' + F.encodeSetup(true);
  const kept = F.stripFormTokens('Тэмдэглэл ' + own + ' ' + foreign);
  ok(!/⟦VAT/.test(kept), 'stripFormTokens: өөрийн ⟦VAT⟧ арилна');
  ok(!/⟦DLV/.test(kept), 'stripFormTokens: өөрийн ⟦DLV⟧ арилна');
  ok(!/⟦SET/.test(kept), 'stripFormTokens: өөрийн ⟦SET⟧ арилна');
  ok(/⟦PAY\|500000/.test(kept), 'stripFormTokens: санхүүгийн ⟦PAY⟧ ХАДГАЛАГДАНА');
  ok(/⟦RF\|120000⟧/.test(kept), 'stripFormTokens: буцаалтын ⟦RF⟧ ХАДГАЛАГДАНА');
  ok(/⟦DMG\|/.test(kept) && /⟦CX\|/.test(kept), 'stripFormTokens: ⟦DMG⟧ ба ⟦CX⟧ ХАДГАЛАГДАНА');
  ok(kept.indexOf('Тэмдэглэл') === 0, 'stripFormTokens: үндсэн текст үлдэнэ');
  ok(F.cleanAppNote(foreign) === '', 'cleanAppNote нь ХАРИН бүгдийг арилгасаар байна (өөр зориулалт)');
}

// 6) paid_ref задлах (банкны баримтын лавлагаа)
{
  const raw = '[#REF123] Бат · 5555000123 · түрээс  |  [#REF456] Дорж · 4444 · төлбөр';
  const list = F.parsePaidRef(raw);
  eq(list.length, 2, 'paid_ref: 2 баримт задлана');
  eq(list[0].id, 'REF123', 'paid_ref: баримтын дугаар');
  eq(list[0].sender, 'Бат', 'paid_ref: илгээгч');
  eq(list[0].acct, '5555000123', 'paid_ref: данс');
}
eq(F.parsePaidRef(''), [], 'paid_ref: хоосон бол []');

// 7) mapsHref — линк эсвэл координат
ok(F.mapsHref('https://maps.google.com/x') === 'https://maps.google.com/x', 'mapsHref: http линкийг хэвээр');
ok(/google\.com\/maps\/search/.test(F.mapsHref('47.9,106.9')), 'mapsHref: координатыг maps search болгоно');

// 8) receiptFingerprint — ижил гүйлгээ ижил хурууны хээ, өөр нь өөр
{
  const a = F.receiptFingerprint({ amount: 100000, date: '2026-08-28', senderName: 'Бат' });
  const b = F.receiptFingerprint({ amount: 100000, date: '2026-08-28', senderName: 'Бат' });
  const c = F.receiptFingerprint({ amount: 200000, date: '2026-08-28', senderName: 'Бат' });
  ok(a === b, 'receiptFingerprint: ижил гүйлгээ = ижил хээ');
  ok(a !== c, 'receiptFingerprint: өөр дүн = өөр хээ');
}

// 9) parseBankReceipt — банкны баримтаас мөнгө/огноо/илгээгч гаргах (ХАМГИЙН ЧУХАЛ)
{
  const golomt = [
    'Хүлээн авагчийн банк', 'Голомт банк',
    'Хүлээн авагчийн данс', '3635185058',
    'Хүлээн авагчийн нэр', 'Чимун ХХК',
    'Гүйлгээний дүн', '500,000.00 MNT',
    'Гүйлгээний огноо', '2026-08-28',
    'Гүйлгээний утга', 'Түрээсийн төлбөр',
    'Гүйлгээний төлөв', 'Амжилттай',
    'Шилжүүлэгчийн нэр', 'Батбаяр',
    'Шилжүүлэгчийн дансны дугаар', '5555000123',
    'Хүсэлтийн лавлах дугаар: ABC123',
  ].join('\n');
  const r = F.parseBankReceipt(golomt);
  eq(r.amount, 500000, 'parseBankReceipt: ДҮН зөв (500,000.00 MNT → 500000)');
  eq(r.date, '2026-08-28', 'parseBankReceipt: огноо');
  eq(r.senderName, 'Батбаяр', 'parseBankReceipt: илгээгчийн нэр');
  eq(r.receiverName, 'Чимун ХХК', 'parseBankReceipt: хүлээн авагч');
  eq(r.senderAcct, '5555000123', 'parseBankReceipt: илгээгчийн данс');
  eq(r.ref, 'Түрээсийн төлбөр', 'parseBankReceipt: гүйлгээний утга');
  eq(r.status, 'Амжилттай', 'parseBankReceipt: төлөв');
  eq(r.bankRef, 'GLABC123', 'parseBankReceipt: лавлах дугаар (GL префикс)');
  ok(/чимун/i.test(r.receiverName), 'parseBankReceipt: Чимун хүлээн авагч шалгалт (орлого мөн)');
}
// Таслалтай том дүн + бутархай
{
  const r = F.parseBankReceipt('Гүйлгээний дүн\n1,234,567.89 MNT\n2026-01-15');
  eq(r.amount, 1234568, 'parseBankReceipt: том дүн таслалтай (1,234,567.89 → 1234568)');
}
// Дүнгүй баримт → amount undefined (буруу файлыг таних)
{
  const r = F.parseBankReceipt('ямар нэг текст дүнгүй');
  ok(r.amount === undefined, 'parseBankReceipt: дүнгүй бол amount undefined (буруу баримт барих)');
}

// 10) rentalDiscount — түрээсийн хугацааны хямдрал (2+ хоног 20%, 7+ 40%, 30+ 55%)
eq(F.rentalDiscount(1).pct, 0, 'Хямдрал: 1 хоног = 0%');
eq(F.rentalDiscount(2).pct, 0.20, 'Хямдрал: 2 хоног = 20%');
eq(F.rentalDiscount(6).pct, 0.20, 'Хямдрал: 6 хоног = 20%');
eq(F.rentalDiscount(7).pct, 0.40, 'Хямдрал: 7 хоног = 40%');
eq(F.rentalDiscount(29).pct, 0.40, 'Хямдрал: 29 хоног = 40%');
eq(F.rentalDiscount(30).pct, 0.55, 'Хямдрал: 30 хоног = 55%');

// 11) rentalDays / orderRentalDays — түрээсийн хоног = КАЛЕНДАРИЙН ӨДРӨӨР (mevent.mn сайттай ЯГ ижил)
const _dMs = (y, m, day, h) => new Date(y, m - 1, day, h || 0).getTime();
eq(F.rentalDays(_dMs(2026, 8, 28, 10), _dMs(2026, 8, 29, 10)), 1, 'Хоног: 28→29 = 1 хоног');
eq(F.rentalDays(_dMs(2026, 8, 28, 10), _dMs(2026, 8, 29, 20)), 1, 'Хоног: 28 10:00→29 20:00 (34ц) = 1 хоног — цаг үл нөлөөлнө (сайттай ижил)');
eq(F.rentalDays(_dMs(2026, 8, 28, 10), _dMs(2026, 8, 30, 9)), 2, 'Хоног: 28→30 = 2 хоног');
eq(F.rentalDays(_dMs(2026, 8, 28, 10), _dMs(2026, 8, 28, 20)), 1, 'Хоног: нэг өдөр = хамгийн багадаа 1');
eq(F.orderRentalDays({ starts_at: '2026-08-28', stops_at: '2026-08-30' }), 2, 'orderRentalDays: 28→30 = 2 хоног');
eq(F.orderRentalDays({ starts_at: '', stops_at: '' }), 1, 'orderRentalDays: огноогүй = 1');

// 12) salaryNet — цэвэр цалин (НДШ 11.5% + ХХОАТ 10%)
{
  const r = F.salaryNet(1000000, true);
  eq(r.ndsh, 115000, 'Цалин: НДШ 11.5% (1сая → 115,000)');
  eq(r.pit, 88500, 'Цалин: ХХОАТ 10% үлдэгдлээс (88,500)');
  eq(r.net, 796500, 'Цалин: цэвэр дүн (796,500)');
}
eq(F.salaryNet(1000000, false).net, 1000000, 'Цалин: суутгалгүй ажилтан → цэвэр = нийт');

// 13) salaryNextYm — дараагийн сар (жил дамжина)
eq(F.salaryNextYm('2026-06'), '2026-07', 'Дараа сар: 2026-06 → 2026-07');
eq(F.salaryNextYm('2026-12'), '2027-01', 'Дараа сар: 12 сар → дараа жилийн 1 сар');

// 14) Огноо давхцал — давхар захиалгын гол логик (_rangesOverlap)
ok(F._rangesOverlap('2026-08-28', '2026-08-30', '2026-08-29', '2026-08-31') === true, 'Давхцал: 28-30 ба 29-31 → давхцана');
ok(F._rangesOverlap('2026-08-01', '2026-08-05', '2026-08-10', '2026-08-15') === false, 'Давхцал: 1-5 ба 10-15 → давхцахгүй');
ok(F._rangesOverlap('2026-08-01', '2026-08-10', '2026-08-10', '2026-08-15') === true, 'Давхцал: нэг өдөр шүргэлцэх = давхцана (инклюзив)');

// 15) НӨАТ туслах логик (тулгалт)
eq(F.vatNum('1,234.5'), 1234.5, 'vatNum: таслалтай тоо');
eq(F.vatNum('₮5,000'), 5000, 'vatNum: тэмдэгттэй');
eq(F.vatNum('abc'), 0, 'vatNum: тоо биш → 0');
eq(F.vatNorm('Түшиг ХХК'), 'түшиг', 'vatNorm: ХХК-г хасна');
eq(F.vatNorm('ABC Group LLC'), 'abc', 'vatNorm: group/llc хасна');
eq(F.vatRegNorm('РД: 1234567'), '1234567', 'vatRegNorm: зөвхөн цифр');
ok(F.vatDateIso('2026-08-28').indexOf('2026-08-28T') === 0, 'vatDateIso: огноо ISO болгоно');
eq(F.vatDateIso(''), '', 'vatDateIso: хоосон → хоосон');

// 16) НӨАТ нэр таарах — ХАТУУ (нэг ерөнхий үг хангалтгүй)
ok(F.vatNameMatch('Түшиг ХХК', 'Түшиг ХХК') === true, 'vatNameMatch: яг таарна');
ok(F.vatNameMatch('Ирээдүйн Хөгжил', 'Хөгжил Ирээдүйн') === true, 'vatNameMatch: 2 гол үг таарвал (эрэмбэ хамаагүй)');
ok(F.vatNameMatch('Гэрэл групп', 'Гэрэл төв') === false, 'vatNameMatch: 1 л гол үг таарвал ХАРГАЛЗАХГҮЙ (хатуу)');
ok(F.vatNameMatch('Түшиг', 'Өөр Компани') === false, 'vatNameMatch: огт өөр нэр');

// 16a) БУЦААСАН НӨАТ баримт (2026-09-04) — нөхөн үзүүлэх тест
// Бодит алдаа: 2026-08-27-нд Токи шоп-д 21,057,080₮-ийн баримт шивээд маргааш нь
// БУЦААГААД 3,000,000 + 18,057,080 болгож хуваасан. eBarimt дээр буцаасан баримт
// задаргаанаас БҮРМӨСӨН алга болдог (сөрөг мөр ч, төлөвийн багана ч үлдэхгүй) ч
// апп ачаалахдаа зөвхөн НЭМДЭГ байсан тул хуучин баримт сууж, нэг захиалгад
// 4 баримт (21.0сая + 2.6сая + 3.0сая + 18.0сая = 44.7сая) холбогдож 25.2сая₮-ийн
// захиалгыг «НӨАТ илүү 19.5сая» гэж харуулж байв.
{
  const D = (dt, ddtd, total, vat, name) => ({ id: ddtd, ddtd, dt, total, vat, buyer_name: name, matched_id: 'NC-2026-0160' });
  // Аппын DB-д байгаа нь (өмнөх ачаалалт — буцаахаас ӨМНӨ татсан файлаас)
  const existing = [
    D('2026-08-27T11:06:00Z', 'A-21057080', 21057080, 1914280, 'Токи шоп'),          // ← буцаагдсан
    D('2026-08-27T11:09:00Z', 'A-2655120', 2655120, 241374.55, 'ТОКИ ББСБ'),
    D('2026-08-28T15:44:00Z', 'A-3000000', 3000000, 272727.27, 'Токи шоп'),
    D('2026-08-28T15:45:00Z', 'A-18057080', 18057080, 1641552.73, 'Токи шоп'),
    D('2026-07-15T10:00:00Z', 'A-7SAR', 5000000, 454545.45, 'Өөр сарын'),            // ← 7-р сар, хөндөгдөх ЁСГҮЙ
  ];
  // Шинэ eBarimt задаргаа (8-р сар) — буцаасан баримт БАЙХГҮЙ
  const imported = existing.filter(r => r.ddtd !== 'A-21057080' && r.ddtd !== 'A-7SAR');

  const det = F.vatDetectReturned(existing, imported);
  eq(det.gone.map(r => r.ddtd), ['A-21057080'], 'буцаалт: файлаас алга болсон баримтыг олно');
  eq(det.months, ['2026-08'], 'буцаалт: зөвхөн ачаалсан сар');
  eq(det.back.length, 0, 'буцаалт: сэргээх баримт алга');

  // ⚠ ХАМГИЙН ЧУХАЛ: 8-р сарын файл ачаалахад 7-р сарын баримт хөндөгдөхгүй
  ok(!det.gone.some(r => r.ddtd === 'A-7SAR'), 'буцаалт: ачаалаагүй сарын баримт БУЦААСАН болохгүй');

  // Тэмдэглэсний дараа — нийлбэрээс хасагдана
  const after = existing.map(r => r.ddtd === 'A-21057080' ? { ...r, returned: true } : r);
  const act = F.vatActive(after);
  eq(act.length, 4, 'буцаалт: хүчинтэй баримт 4 (буцаасан хасагдав)');
  const aug = act.filter(r => String(r.dt).slice(0, 7) === '2026-08');
  eq(aug.reduce((s, r) => s + r.total, 0), 23712200, 'буцаалт: 8-р сарын Токи нийлбэр = 23,712,200₮ (44,769,280 БИШ)');

  // Дахин гарч ирвэл (буцаалт цуцлагдсан) автоматаар сэргэнэ
  const det2 = F.vatDetectReturned(after, existing.filter(r => r.ddtd !== 'A-7SAR'));
  eq(det2.back.map(r => r.ddtd), ['A-21057080'], 'буцаалт: файлд дахин гарвал сэргээх жагсаалтад');
  eq(det2.gone.length, 0, 'буцаалт: сэргээх үед шинэ алга болсон байхгүй');

  eq(F.vatIsReturned({ returned: true }), true, 'буцаалт: тэмдэглэгээ уншина');
  eq(F.vatIsReturned({}), false, 'буцаалт: тэмдэглэгээгүй = хүчинтэй');
  eq(F.vatActive(null).length, 0, 'буцаалт: хоосон оролт унахгүй');
  eq(F.vatDetectReturned([], []).gone.length, 0, 'буцаалт: хоосон файл юуг ч тэмдэглэхгүй');
}

// 16a-1b) НӨАТ-ын САРЫН ТАЙЛАН → иргэдийн нийлбэр (2026-10-05).
// e-barimt-ийн задаргаа ЗӨВХӨН регистртэй баримтыг гаргадаг тул иргэнд гаргасан
// 3,022,000₮ аппад огт ороогүй байв. Татварт илгээдэг тайлангийн «1000000» мөрөөс
// уншина. Бусад нэгтгэсэн мөр (4000000) задаргаатай давхцдаг тул ОРОХГҮЙ.
{
  const H = ['Огноо', 'Падааны дугаар', 'Борлуулагчийн ТТД', 'Борлуулагчийн Нэр', 'Худалдан авагчийн ТТД', 'Худалдан авагчийн Нэр', 'Татвар ногдуулах нийт орлогын дүн (6+7)', 'Нэмэгдсэн өртгийн албан татвар', 'Нийт дүн', 'ХМЛ Задаргаа', '', ''];
  const mx = [H,
    ['2026-09-07', '4273221425', '6614337', 'Чимун', '5054788', 'МЧБС', '17403636.36', '1740363.64', '19144000', '', '1', '2'],
    ['2026-09-30', '4272263059', '6614337', 'Чимун', '1000000', 'ЭЦСИЙН ХЭРЭГЛЭГЧ', '2747272.73', '274727.27', '3022000', '', '1', ''],
    ['2026-09-30', '4272533022', '6614337', 'Чимун', '4000000', 'ЭЦСИЙН ХЭРЭГЛЭГЧ', '24487409.09', '2448740.91', '26936150', '', '1', ''],
    ['2026-09-30', '4272337088', '6614337', 'Чимун', '2000000', 'ЭЦСИЙН ХЭРЭГЛЭГЧ', '0', '0', '0', '', '3', ''],
    ['2026-09-01', '4272465855', '5241901', 'Петростар', '6614337', 'Чимун', '45454.55', '4545.45', '50000', '', '0', '1'],
    ['2026-09-02', '4272465999', '5000001', 'Номин', '6614337', 'Чимун', '90909.09', '9090.91', '100000', '', '0', '1'],
  ];
  const rp = F.parseVatReportMatrix(mx);
  ok(rp, 'НӨАТ тайлан: файлыг таньлаа');
  eq(rp.own, '6614337', 'НӨАТ тайлан: өөрийн ТТД = мөр бүрд гардаг ТТД');
  eq(rp.month, '2026-09', 'НӨАТ тайлан: сар');
  eq(rp.citizen.id, 'agg-2026-09-1000000', 'НӨАТ тайлан: иргэдийн нийлбэрийн id сараар (дахин оруулахад шинэчлэгдэнэ)');
  eq(rp.citizen.total, 3022000, 'НӨАТ тайлан: иргэдийн дүн 3,022,000');
  eq(Math.round(rp.citizen.vat), 274727, 'НӨАТ тайлан: иргэдийн НӨАТ');
  eq(rp.citizen.reg, '1000000', 'НӨАТ тайлан: зөвхөн иргэдийн код');
  eq(String(rp.citizen.dt).slice(0, 10), '2026-09-30', 'НӨАТ тайлан: огноо тайлангийн сард');
  eq(rp.sales.total, 19144000 + 3022000 + 26936150, 'НӨАТ тайлан: борлуулалтын нийт (нэгтгэсэн мөр багтана)');
  eq(rp.purchases.n, 2, 'НӨАТ тайлан: худалдан авалт = худалдан авагч нь өөрөө');
  eq(Math.round(rp.purchases.vat), 13636, 'НӨАТ тайлан: худалдан авалтын НӨАТ');
  // Задаргааны файлыг тайлан гэж андуурахгүй, тайлангийн толгойгүй файл → null
  eq(F.parseVatReportMatrix([['Пос дугаар', 'ДДТД', 'Огноо', 'Нийт дүн'], ['1', 'X', '2026-09-01', '100']]), null, 'НӨАТ тайлан: задаргааг тайлан гэж андуурахгүй');
  eq(F.parseVatReportMatrix([]), null, 'НӨАТ тайлан: хоосон → null');
  // Иргэдийн мөргүй тайлан → citizen null (юу ч нэмэхгүй)
  eq(F.parseVatReportMatrix([H, mx[1], mx[5]]).citizen, null, 'НӨАТ тайлан: иргэдийн мөргүй бол нэмэх юм алга');

  // ⛔ Иргэдийн нийлбэр задаргаанд хэзээ ч гарахгүй → задаргаа оруулахад «буцаасан» БОЛОХГҮЙ
  const agg = { id: rp.citizen.id, ddtd: rp.citizen.ddtd, dt: '2026-09-30T00:00:00+00:00', total: 3022000, vat: 274727.27, buyer_reg: '1000000' };
  const b2b = { id: 'B1', ddtd: 'B1', dt: '2026-09-07T10:00:00+00:00', total: 19144000, vat: 1740363.64, buyer_reg: '5054788' };
  const det = F.vatDetectReturned([agg, b2b], [b2b]);
  eq(det.gone.length, 0, 'НӨАТ тайлан: иргэдийн нийлбэр задаргаа оруулахад «алга болсон» гэж тооцогдохгүй');
  ok(F.vatIsAggregate(agg) && !F.vatIsAggregate(b2b), 'НӨАТ тайлан: нэгтгэсэн мөрийг таньдаг');

  // Иргэдийн НӨАТ зардалд орно (тулгагдаагүй → ХХК)
  const br = F.vatByBranchMonth([agg, b2b], '2026-09');
  eq(Math.round(br.total), Math.round(274727.27 + 1740363.64), 'НӨАТ тайлан: иргэдийн НӨАТ сарын НӨАТ-д орно');
  eq(Math.round(br['ХХК']), Math.round(274727.27 + 1740363.64), 'НӨАТ тайлан: тулгагдаагүй → ХХК');

  // Тайлан ↔ апп тулгалт: буцаасныг хасна, зөрүүг тэмдэгтэй буцаана
  const ret = { id: 'R', ddtd: 'R', dt: '2026-09-04T10:00:00+00:00', total: 2476000, vat: 225090.91, returned: true };
  const c1 = F.vatReportRecon({ month: '2026-09', sales: { total: 19144000 + 3022000, vat: 1740363.64 + 274727.27 }, purchases: { n: 0 }, citizen: rp.citizen }, [agg, b2b, ret]);
  eq(c1.diffTotal, 0, 'НӨАТ тайлан: таарсан үед зөрүү 0 (буцаасан тоологдохгүй)');
  ok(/таарч байна/.test(F.vatReportReconHtml(c1)), 'НӨАТ тайлан: таарвал «таарч байна»');
  const c2 = F.vatReportRecon({ month: '2026-09', sales: { total: 19144000 + 3022000 - 887000, vat: 1740363.64 + 274727.27 - 80636.36 }, purchases: { n: 197, vat: 1443934 } }, [agg, b2b]);
  eq(c2.diffTotal, 887000, 'НӨАТ тайлан: аппад илүү бол зөрүү эерэг');
  ok(/887,000/.test(F.vatReportReconHtml(c2)) && /илүү/.test(F.vatReportReconHtml(c2)), 'НӨАТ тайлан: зөрүүг дүнтэй нь ил хэлнэ');
  ok(/1,443,934/.test(F.vatReportReconHtml(c2)), 'НӨАТ тайлан: худалдан авалтын НӨАТ ил гарна');
}

// Хойш огноолсон баримт: ДДТД-ийн шивсэн өдөр > сар → тайлангийн зөрүүг тайлбарлана (2026-10-05).
// 9 сарын тайлан гарсны дараа 10-05-нд шивсэн 852,000₮ (огноо 09-30 23:59) тайланд ороогүй байв.
{
  eq(F.vatIssuedDay('000006614337000261005000001635194'), '2026-10-05', 'ДДТД: шивсэн өдрийг уншина');
  eq(F.vatIssuedDay('000006614337000260930000001353472'), '2026-09-30', 'ДДТД: энгийн баримт');
  eq(F.vatIssuedDay('4272263059'), '', 'ДДТД: танихгүй хэлбэр (тайлангийн падаан) → хоосон');
  eq(F.vatIssuedDay(''), '', 'ДДТД: хоосон → хоосон');
  const ok1 = { id: 'A', ddtd: '000006614337000260930000001353472', dt: '2026-09-30T15:39:00+00:00', total: 20805600, vat: 1891418.18, buyer_name: 'Трансвест' };
  const late = { id: 'L', ddtd: '000006614337000261005000001635194', dt: '2026-09-30T23:59:00+00:00', total: 852000, vat: 77454.55, buyer_name: 'Ламбда глобал' };
  const rc = F.vatReportRecon({ month: '2026-09', sales: { total: 20805600, vat: 1891418.18 }, purchases: { n: 0 } }, [ok1, late]);
  eq(rc.late.length, 1, 'НӨАТ тайлан: сар дууссаны дараа шивсэн баримтыг олно');
  eq(rc.late[0].issued, '2026-10-05', 'НӨАТ тайлан: шивсэн өдөр');
  eq(rc.diffTotal, 852000, 'НӨАТ тайлан: зөрүү = хойш огноолсон баримт');
  const h = F.vatReportReconHtml(rc);
  ok(/бүхэлдээ сар дууссаны дараа/.test(h) && /Ламбда глобал/.test(h) && /10-05-нд шивсэн/.test(h), 'НӨАТ тайлан: зөрүү бүхэлдээ хойш огноолсон баримтаас бол ил хэлнэ');
  // Тайланд нэрээр жагссан хойш огноолсон баримт (Максимус) ОРСОН тул тайлбарт тоологдохгүй
  const named = { id: 'M', ddtd: '000006614337000261002000001472397', dt: '2026-09-30T23:59:00+00:00', total: 1157440, vat: 105221.82, buyer_name: 'Максимус', buyer_reg: '6191592' };
  const rc3 = F.vatReportRecon({ month: '2026-09', named: [{ reg: '6191592', total: 1157440 }], sales: { total: 20805600 + 1157440, vat: 1 }, purchases: { n: 0 } }, [ok1, late, named]);
  eq(rc3.late.map(x => x.name), ['Ламбда глобал'], 'НӨАТ тайлан: тайланд нэрээр жагссан баримт «ороогүй» гэж тооцогдохгүй');
  eq(F.parseVatReportMatrix([['Огноо', 'Падааны дугаар', 'Борлуулагчийн ТТД', 'Борлуулагчийн Нэр', 'Худалдан авагчийн ТТД', 'Худалдан авагчийн Нэр', 'Татвар ногдуулах', 'Нэмэгдсэн өртгийн', 'Нийт дүн'],
    ['2026-09-30', '1', '6614337', 'Чимун', '6191592', 'Максимус', '1052218', '105222', '1157440'],
    ['2026-09-30', '2', '6614337', 'Чимун', '4000000', 'ЭЦСИЙН', '10', '1', '11'],
    ['2026-09-01', '3', '5241901', 'Петростар', '6614337', 'Чимун', '10', '1', '11']]).named, [{ reg: '6191592', total: 1157440 }], 'НӨАТ тайлан: нэрээр жагссан борлуулалт (нэгтгэсэн код хасагдана)');
  const rc2 = F.vatReportRecon({ month: '2026-09', sales: { total: 20805600 - 35000, vat: 1891418.18 }, purchases: { n: 0 } }, [ok1, late]);
  ok(/Үүнээс 852,000₮/.test(F.vatReportReconHtml(rc2)) && /35,000₮/.test(F.vatReportReconHtml(rc2)), 'НӨАТ тайлан: хэсэгчлэн тайлбарлавал үлдэгдлийг ил хэлнэ');
}

// SCAN — иргэдийн нийлбэрийг захиалгатай тулгахгүй (авто-тулгалт ба гараар холбох цонх)
{
  const autoLine = src.split('\n').find(l => /const todo = vatReceiptsActive\(\)\.filter/.test(l)) || '';
  ok(/vatIsAggregate/.test(autoLine), 'SCAN НӨАТ: авто-тулгалт иргэдийн нийлбэрийг алгасна');
  const attach = src.slice(src.indexOf('async function openVatAttachModal'), src.indexOf('async function openVatAttachModal') + 4000);
  ok(/vatReceiptsActive\(\)\.filter\(r => !vatIsAggregate\(r\)\)/.test(attach), 'SCAN НӨАТ: захиалгад холбох цонхонд иргэдийн нийлбэр гарахгүй');
  const det = src.slice(src.indexOf('function vatDetectReturned'), src.indexOf('function vatDetectReturned') + 800);
  ok(/vatIsAggregate\(r\)\) return/.test(det), 'SCAN НӨАТ: буцаалт илрүүлэлт иргэдийн нийлбэрийг алгасна');
}

// 16a-2) SCAN — НӨАТ-ын нийлбэр/тулгалт БҮГД буцаасныг шүүсэн эх сурвалжаас уншина.
// Түүхий `state.vatReceipts`-ыг шүүлтгүй уншвал буцаасан баримт дахин тоологдоно —
// яг энэ алдаа 2026-08-д гарсан. Зөвшөөрөгдөх түүхий уншилт: ачаалалт, тайлангийн
// модалын сар/жагсаалт (тэнд «↩ Буцаасан» таб ХАРУУЛАХ ёстой), rec хайлт.
{
  const src = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
  const bad = (src.match(/^.*\bstate\.vatReceipts\b.*$/gm) || [])
    .filter(l => !/state\.vatReceipts\s*=/.test(l))            // оноолт
    .filter(l => !/Array\.isArray\(state\.vatReceipts\)/.test(l))   // ачаалсан эсэх шалгалт
    .filter(l => !/\.find\(x => x\.id === /.test(l))           // нэг бичлэг хайх
    .filter(l => !/return state\.vatReceipts;/.test(l))        // loadVatReceipts — түүхий агуулах
    .filter(l => !/\.slice\(\)\.sort\(/.test(l))               // модалын сарын жагсаалт (↩ таб буцаасныг ХАРУУЛНА)
    .filter(l => !/function months\(\)|const before =|const RET =|vatActive\(|vatReceiptsActive/.test(l));
  eq(bad.map(l => l.trim().slice(0, 60)), [],
     'scan: НӨАТ нийлбэр бүр vatActive/vatReceiptsActive-ээр (буцаасан давхар тоологдохгүй)');
}

// 16b) Ирцийн цаг — өнгөрсөн өдрийн нээлттэй сесс (гарахаа бүртгүүлээгүй) 172ц болохгүй
{
  const inTs = '2026-08-20T01:00:00.000Z';   // ирсэн, гараагүй
  const past = F.attMemberSummary([{ kind: 'in', ts: inTs }], false);
  ok(past.mins === 0, 'attMemberSummary: өнгөрсөн өдрийн нээлттэй сесс = 0 мин (172ц алдаа засав)');
  ok(past.noOut === true && past.open === false, 'attMemberSummary: өнгөрсөн нээлттэй = noOut, open биш');
  /* ⛔ ЦАЙНЫ ЦАГ ЧИМЭЭГҮЙ 0 БОЛДОГ БАЙВ (2026-10-03). Өдрийн ирцийн жагсаалт
     `day` талбарыг ТАТДАГГҮЙ байсан тул `lunchMinsFor(undefined, …)` = 0 болж,
     дэлгэцэд цай хасагдаагүй БҮТЭН цаг гарч, сарын тооцоотой зөрж байв
     (CEO: «хасагдаагүй л харагдаад байна»). */
  {
    const D = (day, a, b) => F.attMemberSummary([
      { kind: 'in', day, ts: `2026-10-01T${a}:00.000Z` },
      { kind: 'out', day, ts: `2026-10-01T${b}:00.000Z` }], false);
    const full = D('2026-10-01', '01:00', '10:04');     // 9ц 4м
    eq(full.gross, 544, 'цай: нийт байсан цаг');
    eq(full.lunch, 60, 'цай: 5ц-аас урт өдөр 1ц хасагдана');
    eq(full.mins, 484, 'цай: ажилласан = нийт − цай');
    const short = D('2026-10-01', '01:00', '03:00');    // 2ц
    eq(short.lunch, 0, 'цай: богино өдөр хасагдахгүй');
    eq(short.mins, 120, 'цай: богино өдөр бүтнээрээ');
    // ⛔ Эхлэх өдрөөс ӨМНӨ хасагдахгүй (9 сарын цалин аль хэдийн бодогдсон)
    eq(D('2026-09-30', '01:00', '10:04').lunch, 60, 'цай: 9 сард ч хасагдана (тооцоо тэр сараас эхэлсэн)');
    eq(D('2026-08-31', '01:00', '10:04').lunch, 0, 'цай: 8 сар (түүх) хасагдахгүй');
    // ⛔ `day` дутвал ЧИМЭЭГҮЙ 0 болно — тиймээс татах select-д заавал байна
    eq(D(undefined, '01:00', '10:04').lunch, 0, 'цай: өдөргүй бол хасагдахгүй (select-д day заавал)');
  }
  const closed = F.attMemberSummary([{ kind: 'in', ts: '2026-08-20T01:00:00.000Z' }, { kind: 'out', ts: '2026-08-20T09:00:00.000Z' }], false);
  ok(closed.mins === 480, 'attMemberSummary: хаагдсан сесс = 8ц (480 мин)');
}

// 17) НӨАТ авто оноо — РД+нэр+дүн+огноо таарвал өндөр
{
  const rec = { reg: '1234567', name: 'Түшиг ХХК', total: 500000, net: 450000, dt: '2026-08-28' };
  const strong = F.vatAutoScore(rec, { reg: '1234567', name: 'Түшиг', amount: 500000, date: '2026-08-28' });
  const weak = F.vatAutoScore(rec, { reg: '9999999', name: 'Огт өөр', amount: 12345, date: '2020-01-01' });
  ok(strong >= 20, 'vatAutoScore: РД+нэр+дүн+огноо таарвал өндөр оноо (≥20)');
  ok(weak < strong, 'vatAutoScore: таарахгүй бол бага оноо');

  /* ⛔ ХОЛЫН ОГНОО — ТОРГУУЛЬТАЙ (2026-10-03, CEO барив: «хаа байсан 4 сарыхыг
     санал болгоод байна, нягтлан он сар харахгүй бол алдаж дарах магадлал их»).
     Дүн таарсан гэдэг дангаараа хангалтгүй: 4 сарын өмнөх өөр харилцагчийн
     захиалга ижил дүнтэй байж болно. */
  need(['vatCandGap', 'vatGapNote']);
  eq(F.vatCandGap({ dt: '2026-09-09' }, { date: '2026-09-09' }), 0, 'зөрүү: ижил өдөр → 0');
  eq(F.vatCandGap({ dt: '2026-09-09' }, { date: '2026-05-04' }), 128, 'зөрүү: хоногоор');
  eq(F.vatCandGap({ dt: '2026-09-09' }, {}), null, 'огноогүй бол null (0 гэж худал хэлэхгүй)');
  eq(F.vatGapNote(0), '', 'ойр санал — анхааруулгагүй');
  eq(F.vatGapNote(45), '', '45 хоног хүртэл хэвийн (НӨАТ хожуу шивэгддэг)');
  eq(F.vatGapNote(128), '⚠ 4 сарын зөрүү', 'хол санал — сараар нь ил хэлнэ');
  eq(F.vatGapNote(60), '⚠ 2 сарын зөрүү', '60 хоног → 2 сар');
  eq(F.vatGapNote(null), '', 'огноо мэдэгдэхгүй бол чимээгүй');

  /* ⛔ ХЭСЭГЧИЛСЭН ШИВЭГДСЭН ЗАХИАЛГЫН ҮЛДЭГДЭЛ (2026-10-03, амьд датаас).
     Захиалга #1279 = 2,656,500₮; 1,551,000₮ нь аль хэдийн шивэгдсэн;
     тулгаагүй баримт 1,105,500₮ — яг үлдэгдэл. Хоёулаа нэг РД (5770734).
     Өмнө нь санал зөвхөн БҮТЭН дүнтэй тулгадаг тул «таарах санал алга» байв. */
  need(['vatCandRemain']);
  eq(F.vatCandRemain({ amount: 2656500 }, 1551000), 1105500, 'үлдэгдэл = дүн − шивэгдсэн');
  eq(F.vatCandRemain({ amount: 2656500 }, 0), 0, 'огт шивэгдээгүй бол үлдэгдэл 0 (бүтэн дүнгээр л тулгана)');
  eq(F.vatCandRemain({ amount: 2656500 }, 2656500), 0, 'бүрэн шивэгдсэн бол үлдэгдэлгүй');
  eq(F.vatCandRemain({ amount: 0 }, 500), 0, 'дүнгүй захиалгад үлдэгдэл бодохгүй');
  {
    const rec = { dt: '2026-05-29', buyer_reg: '5770734', name: 'Орчлонконсалтинг', total: 1105500, net: 1005000 };
    const full = { reg: '', name: 'Э.Бэрцэцэг', amount: 2656500, remain: 0, date: '2026-05-31' };
    const part = { reg: '', name: 'Э.Бэрцэцэг', amount: 2656500, remain: 1105500, date: '2026-05-31' };
    ok(F.vatAutoScore(rec, part) > F.vatAutoScore(rec, full),
       'үлдэгдэлтэй таарсан захиалга илүү өндөр оноотой');
    ok(F.vatAutoScore(rec, part) >= 5, 'үлдэгдлийн таарц дүнгийн таарцтай ижил хүчтэй');
  }
  {
    const r = { dt: '2026-09-09', buyer_reg: '', name: '', total: 3960000, net: 3600000 };
    const near = F.vatAutoScore(r, { reg: '', name: '', amount: 3600000, date: '2026-09-05' });
    const far = F.vatAutoScore(r, { reg: '', name: '', amount: 3600000, date: '2026-05-04' });
    ok(far < near, 'дүн ижил атал хол огноотой санал БАГА оноотой');
    ok(far < 5, 'зөвхөн дүнгээр таарсан хол санал дангаараа хүчтэй болохгүй');
  }
}

