    ok(!F.pbxCallerMatch(a, 'байхгүй', cust), 'залгагч: тохирохгүй бол хасагдана');
    ok(F.pbxCallerMatch(a, '', cust), 'залгагч: хоосон хайлт бүгдийг үзүүлнэ');
