  const at = src.indexOf('function bqOrderCard');
  const card = src.slice(at, at + 12000);
  ok(/orderOverpaid\(o\)/.test(card), 'scan: захиалгын карт илүү төлөлтийг шалгана');
  ok(/op-over/.test(card), 'scan: илүү төлөлт төлбөрийн самбарт ил гарна');
  // Захиалгыг засаад дүн буурвал буцаалтын модал ӨӨРӨӨ санал болгоно — хүн мартахгүй
  const sv = src.indexOf('await saveAppOrder(ord)');
