// ═══ ҮЛДЭГДЭЛ ЯАЖ УНШИГДАХ ВЭ — БАНК БҮР ӨӨР (2026-09-11) ════════════════════
// Голомт үлдэгдлээ ШОШГОТОЙ мөрд, ХААН БАГАНА болгон бичдэг. Fixture нь амьд
// файлын бүтцээс (Deposit Account Statement / ДАНСНЫ ХУУЛГА) авсан.
function testStatementBalances() {
  need(['statementMeta']);

  // ── ХААН: толгойн мөрөнд хоёр гарчиг ЗЭРЭГ, утга нь мөр бүрд ──
  const khan = [
    ['', '', '', '', '', '', 'Printed Date:', '2026-09-11'],
    ['', '', 'Депозит дансны дэлгэрэнгүй хуулга', '', '', '', '', ''],
    ['Хэрэглэгч:', '', '', 'ЧИМУН', '', '', 'Интервал: 2026-09-01-2026-09-11', ''],
    ['Валютын төрөл:', '', '', 'MNT', '', 'IBAN:', 'MN670005005222003015', ''],
    ['Гүйлгээний огноо', 'Салбар', 'Эхний үлдэгдэл', 'Кредит гүйлгээ', 'Дебит гүйлгээ', 'Эцсийн үлдэгдэл', 'Гүйлгээний утга', 'Харьцсан данс'],
    ['2026-09-01 09:39:50', '5022', 446581.81, 0.0, -30000.00, 416581.81, 'EB-Зарлага: машин', '5103006078'],
    ['2026-09-02 11:34:50', '5000', 416581.81, 800000.00, 0.0, 1216581.81, 'ДАНС ХООРОНД', '3675118079'],
    ['2026-09-11 19:46:24', '5022', 1216581.81, 0.0, -257777.00, 958804.81, 'EB-Зарлага мотор түлш', '5620056010'],
    ['', '', '', '', '', '', '', ''],
    ['Нийт дүн:', '', '', 800000.00, 287777.00, '', '', ''],
  ];
  const mk = F.statementMeta(khan);
  eq(mk.opening, 446581.81, 'ХААН: эхний үлдэгдэл = ЭХНИЙ мөрийн баганаас');
  eq(mk.closing, 958804.81, 'ХААН: эцсийн үлдэгдэл = СҮҮЛИЙН мөрийн баганаас');

  // ⛔ Гол регресс: баганын ГАРЧГИЙГ утга гэж уншиж 0 болгож байв
  ok(mk.opening !== 0 && mk.closing !== 0, 'ХААН: баганын гарчгаас 0 уншихаа болив');

  // ── Голомт: тус тусдаа шошготой мөр, дүн нь хажууд ──
  const golomt = [
    ['', '', '', '', '', 'Хуулганы огноо', '', '2026-09-11'],
    ['ДАНСНЫ ХУУЛГА', '', '', '', '', '', '', ''],
    ['', 'Дансны дугаар', '3675118079 [MNT]', 'IBAN', '', 'MN79 0015 0036 7511 8079', '', ''],
    ['', 'Харилцагчийн нэр', 'ЧИМУН', 'Гүйлгээний огноо', '', '2026-09-01 - 2026-09-11', '', ''],
    ['', 'Эхний үлдэгдэл', 141028, '', '', '', '', ''],
    ['', 'Гүйлгээний огноо', 'Гүйлгээний утга', 'Харьцсан дансны нэр', 'Харьцсан данс', 'Ханш', 'Орлого', 'Зарлага'],
    ['', '2026-09-01T09:32:57', 'POS', '', '', 1.0, '', 19000],
    ['', '2026-09-02T11:34:51', 'ДАНС ХООРОНД', 'ЧИМУН', '3635161180', 1.0, 541081, ''],
    ['', '', '', 'Нийт орлого', '', 541081, '', ''],
    ['', '', '', 'Нийт зарлага', '', 19000, '', ''],
    ['', '', '', 'Эцсийн үлдэгдэл', '', 663109, '', ''],
  ];
  const mg = F.statementMeta(golomt);
  eq(mg.acct, '3675118079', 'Голомт: дансны дугаар толгойноос ([MNT] хаягдана)');
  eq(mg.period, '2026-09-01 - 2026-09-11', 'Голомт: хугацаа толгойноос');
  eq(mg.opening, 141028, 'Голомт: эхний үлдэгдэл шошготой мөрөөс');
  eq(mg.closing, 663109, 'Голомт: эцсийн үлдэгдэл ФАЙЛЫН ДООД талаас');
  eq(141028 + 541081 - 19000, 663109, 'Голомт: эхний + орлого − зарлага = эцсийн');

  /* ⚠ Голомтын «Эхний үлдэгдэл» мөр нь ганцаараа байх ёстой — ХААН-ы баганын горим
     түүнийг булаахгүй (нэг мөрөнд хоёр гарчиг ЗЭРЭГ байхыг шаарддаг). */
  ok(mg.opening !== mg.closing, 'Голомт: баганын горим шошгын горимыг булаахгүй');

  // ── num(): цифргүй текст нь 0 БИШ ──
  const noDigit = [
    ['Эхний үлдэгдэл', 'Кредит гүйлгээ'],   // гарчиг л, дата мөр алга
  ];
  eq(F.statementMeta(noDigit).opening, null, 'цифргүй хөрш нүднээс 0 уншихгүй');
}
testStatementBalances();

// ═══ ХАСАГДСАН МӨРИЙН ШАЛТГААН + ДАНС (2026-09-11) ════════════════════════════
// «дотоод шилжүүлэг (өөрийн данс)» гэж 56 мөр · 38.8сая хасагдсаныг хэрэглэгч
// батлах аргагүй байв — аль данс болох нь хаана ч бичигдээгүй.
function testStmtDropWhy() {
  need(['stmtDropWhy']);
  const lbl = (d) => d === '5400145457' ? 'Голомт ••5457' : '';
  eq(F.stmtDropWhy({ why: 'дотоод шилжүүлэг (өөрийн данс)', acct: '5400145457' }, lbl),
     'дотоод шилжүүлэг (өөрийн данс) → Голомт ••5457', 'шалтгааны ард данс бичигдэнэ');
  eq(F.stmtDropWhy({ why: 'банкны шимтгэл' }, lbl), 'банкны шимтгэл', 'дансгүй мөр шалтгаагаа л хэлнэ');
  eq(F.stmtDropWhy({ why: 'огноо уншигдсангүй', acct: '' }, lbl), 'огноо уншигдсангүй', 'хоосон данс → нэмэлтгүй');
  eq(F.stmtDropWhy({ why: 'дотоод шилжүүлэг', acct: '9999999999' }, lbl), 'дотоод шилжүүлэг',
     'таних боломжгүй данс → шалтгаан дангаараа (хуурамч нэр зохиохгүй)');
  eq(F.stmtDropWhy({ why: 'х', acct: '  5400-145-457  ' }, (d) => d), 'х → 5400145457', 'зураас/зайтай данс цэвэрлэгдэнэ');
  eq(F.stmtDropWhy(null, lbl), '', 'хоосон мөр → хоосон');
  eq(F.stmtDropWhy({ acct: '5400145457' }, lbl), ' → Голомт ••5457', 'шалтгаангүй ч данс харагдана');

  // SCAN: хасагдсан мөр бүрд данс яваа эсэх — энэ нь шалгах ГАНЦ зам
  const at = src.indexOf("dropped.push({ date: r.date, memo: r.memo, debit: r.debit");
  ok(at > 0, 'scan: хасагдсан мөрийн бүртгэл олдов');
  const chunk = src.slice(at, at + 900);
  eq((chunk.match(/dropped\.push\(\{ date: r\.date[^}]*acct: r\.account/g) || []).length, 1,
     'scan: зарлагын хасалт (дотоод шилжүүлэг) дансаа авч явна');
  // Банкны шимтгэл 2026-09-11-нд хасалтаас ГАРСАН — зардал мөн (5700)
  ok(!/why: 'банкны шимтгэл'/.test(src),
     'scan: банкны шимтгэл хасагдахаа болив — зардал болж бүртгэгдэнэ');
}
testStmtDropWhy();

// ═══ ДАРААГИЙН АЛХАМ (2026-09-11) ═════════════════════════════════════════════
// Хэрэглэгчийн гомдол: «тоо харагдаж байна, одоо юу хийх нь мэдэгдэхгүй». Карт нь
// ажлыг хамаарлын дарааллаар эрэмбэлнэ — дараалал эвдэрвэл зөвлөгөө утгагүй болно.
function testFinNextSteps() {
  need(['finNextSteps', 'finNextStepsHtml']);
  const keys = (st) => st.map(x => x.key);
  const byKey = (st, k) => st.find(x => x.key === k) || {};

  // ① Бүх ажил үлдсэн — эрэмбэ нь хамаарлын дараалал
  const all = F.finNextSteps({ month: '2026-09', isCEO: true,
    missingAccts: ['Голомт', 'Хаан'], pendExpenses: 7,
    openIncome: { n: 12, sum: 4200000 }, chainBreaks: 2,
    balance: { total: 4, ok: 2, bad: 1, unver: 1, badAccts: ['504'], unverAccts: ['300'] } });
  eq(keys(all).join('>'), 'stmt>expense>income>balance>chain>close',
     'алхмын эрэмбэ: хуулга→ангилах→тулгах→тэнцэл→залгаа→хаах');
  eq(byKey(all, 'balance').n, 2, 'тэнцэл: зөрүүтэй + шалгагдаагүй дансыг нийлүүлж тоолно');
  ok(/504/.test(byKey(all, 'balance').hint) && /300/.test(byKey(all, 'balance').hint),
     'тэнцэл: АЛЬ данс гэдгийг нэрлэнэ');
  eq(byKey(all, 'balance').act, 'recon', 'тэнцлийн алхам → тулгалтын цонх');
  eq(byKey(all, 'stmt').n, 2, 'хуулга дутуу дансны тоо');
  eq(byKey(all, 'stmt').act, 'classify', 'хуулгын алхам → оруулах модал');
  eq(byKey(all, 'income').sum, 4200000, 'хаагдаагүй орлогын дүн харагдана');
  eq(byKey(all, 'expense').act, 'expenses', 'зардлын алхам → Миний зардал');
  // Дутуутай үед сар хаах нь ХҮЛЭЭНЭ (дарж болохгүй) — эс бөгөөс дутуу сар хаагдана
  eq(byKey(all, 'close').wait, true, 'дутуутай үед сар хаах товч идэвхгүй');
  eq(byKey(all, 'close').act, undefined, 'хүлээж буй алхам үйлдэлгүй');

  // ② Бүгд цэвэр — хаах нь идэвхтэй, бусад нь ✓
  const clean = F.finNextSteps({ month: '2026-09', isCEO: true,
    missingAccts: [], pendExpenses: 0, openIncome: { n: 0, sum: 0 }, chainBreaks: 0,
    balance: { total: 4, ok: 4, bad: 0, unver: 0, badAccts: [], unverAccts: [] } });
  eq(keys(clean).join('>'), 'stmt>expense>income>balance>close', 'цэвэр үед залгааны алхам гарахгүй');
  ok(clean.slice(0, 4).every(x => x.done), 'цэвэр үед эхний 4 алхам ✓');
  /* ⭐ ЗӨВ БАЙХАД Ч ХАРАГДАНА — «хэдэн данснаас хэд нь тэнцсэн» гэдэг нь шалгалт
     үнэхээр ажилласныг батлах цорын ганц дохио. Зөрүү байхад л гарч ирдэг мөр
     бол шалгалт чимээгүй унасныг хэн ч мэдэхгүй. */
  eq(byKey(clean, 'balance').hint, '4/4 данс сарын эцсийн үлдэгдлээр батлагдсан',
     'тэнцэл: зөв үед ч N/M тоо харагдана (сарын эцсийн үлдэгдлээр)');
  /* ⛔ ХИЙГДСЭН АЛХАМ Ч НЭЭГДЭНЭ (2026-10-03, CEO барив: «орлого тулгах хэсэг
     дахин өөрчлөх боломжгүй хаагдах нь зөв үү, ямар орлогууд тулгасныг ч харж
     чадахгүй байна»). ✓ нь «ажил дууссан», «буцаж харах эрхгүй» гэсэн үг БИШ. */
  eq(byKey(clean, 'income').act, 'recon', 'тулгасан орлогыг буцаж ХАРАХ зам үлдэнэ');
  eq(byKey(clean, 'income').btn, 'Харах', 'хийгдсэн алхмын товч «Харах»');
  eq(byKey(clean, 'balance').act, 'recon', 'тэнцэл: зөв үед ч харах зам үлдэнэ');
  eq(byKey(clean, 'expense').act, 'expenses', 'ангилсан зардлыг буцаж харна');
  eq(byKey(clean, 'stmt').act, 'recon', 'оруулсан хуулгыг буцаж харна');
  // ⚠ «Харах» нь хийх ажил БИШ — толгойн тоололд орохгүй
  ok(/✓ 2026-09 сар цэгцтэй/.test(F.finNextStepsHtml(clean, '2026-09')),
     'бүгд ✓ үед толгой «цэгцтэй» хэвээр (Харах товч тоологдохгүй)');
  eq(F.finNextSteps({ month: '2026-09', isCEO: true, missingAccts: [], pendExpenses: 0,
    openIncome: { n: 0, sum: 0 }, chainBreaks: 0,
    balance: { total: 0, ok: 0, bad: 0, unver: 0 } }).find(x => x.key === 'balance').hint,
     'Шалгах хуулга алга', 'тэнцэл: хуулга байхгүй бол «0/0» гэж төөрөгдүүлэхгүй');
  /* ⛔ АНГИЛААГҮЙ ЗАРДАЛ САР ХААХЫГ ХОРИНО (2026-10-02, амьд дэлгэцээс барив).
     Ангилаагүй мөр `9500`-аар салбарын зардалд ордог тул салбарын ашиг ба
     COO-гийн 30% гажна; хаавал тэр гажсан тоо хөлдөнө. */
  eq(F.finNextSteps({ month: '2026-09', isCEO: true, missingAccts: [], pendExpenses: 62,
    openIncome: { n: 0, sum: 0 }, chainBreaks: 0,
    balance: { total: 4, ok: 4, bad: 0, unver: 0 } }).find(x => x.key === 'close').wait, true,
     'ангилаагүй зардал байхад сар хаах ХҮЛЭЭНЭ');
  eq(F.finNextSteps({ month: '2026-09', isCEO: true, missingAccts: [], pendExpenses: 0,
    openIncome: { n: 0, sum: 0 }, chainBreaks: 0,
    balance: { total: 4, ok: 4, bad: 0, unver: 0 } }).find(x => x.key === 'close').act, 'close',
     'бүгд цэгцэрсэн үед л сар хаах идэвхтэй');
  /* ⛔ ТЭНЦЭЛ ЗӨРВӨЛ САР ХААГДАХГҮЙ — эс бөгөөс зөрүүтэй сар хөлдөж, засах зам хаагдана. */
  eq(F.finNextSteps({ month: '2026-09', isCEO: true, missingAccts: [], pendExpenses: 0,
    openIncome: { n: 0, sum: 0 }, chainBreaks: 0,
    balance: { total: 2, ok: 1, bad: 1, unver: 0, badAccts: ['504'], unverAccts: [] } })
    .find(x => x.key === 'close').wait, true, 'тэнцэл зөрвөл сар хаах ХҮЛЭЭНЭ');
  eq(byKey(clean, 'close').act, 'close', 'цэвэр үед сар хаах идэвхтэй');

  // ③ CEO биш → хаах алхам огт байхгүй
  const staff = F.finNextSteps({ month: '2026-09', isCEO: false,
    missingAccts: [], pendExpenses: 3, openIncome: { n: 0, sum: 0 } });
  ok(!keys(staff).includes('close'), 'CEO биш хүнд сар хаах алхам харагдахгүй');
  eq(byKey(staff, 'expense').n, 3, 'ангилагдаагүй зардлын тоо');

  // ④ Хаалттай сар — ганц мөр, гэхдээ CEO НЭЭЖ чадна (товч эгнээнээс хасагдсан тул)
  const lockedCeo = F.finNextSteps({ month: '2026-08', locked: true, isCEO: true });
  eq(lockedCeo.length, 1, 'хаалттай сард ганц мөр');
  eq(lockedCeo[0].act, 'close', 'хаалттай сарыг CEO нээж чадна');
  const lockedStaff = F.finNextSteps({ month: '2026-08', locked: true, isCEO: false });
  eq(lockedStaff[0].act, undefined, 'CEO биш хүн хаалттай сарыг нээж чадахгүй');

  // ⑤ HTML — тоолол, товч, «хийх N зүйл» толгой
  const h = F.finNextStepsHtml(all, '2026-09');
  ok(/2026-09 сард хийх 5 зүйл/.test(h), 'толгойд үлдсэн ажлын тоо (хаах нь тоологдохгүй)');
  ok(/data-ns-act="classify"/.test(h) && /data-ns-act="recon"/.test(h), 'товчнууд үйлдлээ авч явна');
  ok(!/data-ns-act="close"/.test(h), 'хүлээж буй сар хаах товчгүй');
  ok(/✓ 2026-09 сар цэгцтэй/.test(F.finNextStepsHtml(
    F.finNextSteps({ month: '2026-09', isCEO: false, missingAccts: [], pendExpenses: 0, openIncome: { n: 0, sum: 0 } }),
    '2026-09')), 'бүгд цэвэр үед толгой нь «цэгцтэй»');

  // ── SCAN: гол үйлдлүүд картад л байна, товчны эгнээнд давхардахгүй ──
  ok(!/id="fin-classify-open"/.test(src) && !/id="fin-recon-open"/.test(src),
     'scan: хуулга/тулгалтын товч эгнээнд давхардахгүй (картаас дуудагдана)');
  ok(!/id="fin-month-lock"/.test(src),
     'scan: сар хаах товч ч картад — хоёр газраас хаагдвал аль нь ажилласан нь мэдэгдэхгүй');
}
testFinNextSteps();

// ═══ ӨГӨГДМӨЛ СУУРЬ = МӨНГӨН ГҮЙЛГЭЭ (2026-09-11) ═════════════════════════════
// Зардал 100% банкны хуулгаас ирдэг тул орлогыг 'accrual'-аар үзэх нь НЭГ тайлангийн
// хоёр талыг өөр хэмжүүрээр хэмжинэ (эвент 9 сард, түүний зардал 10 сард → 9 сар
// хиймлээр ашигтай). Өгөгдмөл нь чимээгүй буцвал бүх тайлангийн тоо өөрчлөгдөнө.
function testFinBasisDefault() {
  need(['finBasis']);
  const runIn = (code) => vm.runInContext(code, sandbox);
  // ① Өгөгдмөл — хадгалсан сонголт байхгүй үед
  localStorage.removeItem('finBasis2');
  runIn('state.finBasis = undefined;');
  eq(F.finBasis(), 'cash', 'өгөгдмөл суурь = мөнгөн гүйлгээ (хадгалсан сонголтгүй)');
  // ② Хэрэглэгч гүйцэтгэл рүү сэлгэвэл хүндэтгэнэ
  localStorage.setItem('finBasis2', 'accrual');
  runIn('state.finBasis = undefined;');
  eq(F.finBasis(), 'accrual', 'хэрэглэгчийн сонгосон гүйцэтгэл суурь хадгалагдана');
  // ③ Ойлгомжгүй утга → cash руу унана (accrual руу БИШ)
  localStorage.setItem('finBasis2', 'хог');
  runIn('state.finBasis = undefined;');
  eq(F.finBasis(), 'cash', 'танихгүй утга → мөнгөн гүйлгээ рүү унана');
  localStorage.removeItem('finBasis2');
  runIn('state.finBasis = undefined;');

  // ── SCAN ──
  ok(/const FIN_BASIS_DEFAULT = 'cash'/.test(src),
     "scan: өгөгдмөл суурь 'cash' хэвээр (accrual руу чимээгүй буцаагүй)");
  ok(!/localStorage\.(get|set)Item\('finBasis'\)?/.test(src),
     "scan: хуучин 'finBasis' түлхүүр хэрэглэгдэхгүй — тэр нь өгөгдмөл accrual үеийн сонголт");

  // ④ COO ашгийн эрхийн ҮНДЭС = орсон мөнгө → эхний дүнгийн багана нь cash (d.ca)
  //    Багана солигдвол CEO өөр тоо харна: хураагдаагүй авлага цалинг хөөрөгдөнө.
  for (const [row, want] of [['Орлого (барьцаа хассан)', 'd.ca.inc, d.ac.inc'],
                             ['= Цэвэр ашиг', 'd.ca.net, d.ac.net']]) {
    ok(src.includes("_r2('" + row + "', " + want),
       'scan: COO панелийн «' + row + '» мөрөнд орсон мөнгө ЭХНИЙ багана');
  }
  ok(/_r2\(`COO цалин \(\$\{pct\}%\)`, sc, sa,/.test(src),
     'scan: COO цалингийн мөрөнд ч орсон мөнгө эхэнд');
  // Үлдэгдэл нь сар бүрийн дэвтрийн «Нийт» мөрөнд — ОРСОН МӨНГӨӨР (_balCa);
  // ноогдох (_balAc) нь зөвхөн «лавлагаа» гэсэн бүдэг мөрөнд.
  ok(/coo-led-bal \$\{_bcol\(_balCa\)\}">\$\{fmtMoney\(_balCa\)\}/.test(src),
     'scan: олгосон цалингийн үлдэгдэл ч орсон мөнгөний суурьтай');

  // ⑤ ГАРААР ХАССАН МӨР ДАХИН ТООЛОГДОХ НҮХ (2026-10-05)
  //    `coo_share.skip` нь finance id-гийн жагсаалт. Дуудалтад дамжуулахгүй бол
  //    CEO-гийн хасалт чимээгүй ажиллахаа болино; «Хадгалах» нь тохиргоог ТЭГЭЭС
  //    угсарвал тэр жагсаалт устана. Хоёуланг хаана.
  ok(/cooSalaryPaid\([^;]*cooShareCfg\(\)\.skip/.test(src),
     'scan: cooSalaryPaid-д хасалтын жагсаалт дамжуулагдана (эс бөгөөс гар хасалт үл ажиллана)');
  ok(/const cfg = Object\.assign\(\{\}, cooShareCfg\(\), \{ key,/.test(src),
     'scan: COO тохиргоо хадгалахад байгаа түлхүүрүүд (skip) ХАДГАЛАГДАНА');
  ok(/if \(mo - Number\(d\.slice\(5, 7\)\) >= 9\) y -= 1;/.test(src),
     'scan: цалингийн сарын он буцаалт ЗӨВХӨН ойр хилд (урьдчилсан олголтыг хасахгүй)');
  ok(/coo-led-ref">Ноогдохоор бодвол \(лавлагаа\)[^`]*_balAc/.test(src),
     'scan: ноогдохоор бодсон үлдэгдэл зөвхөн лавлагаа мөрөнд');

  // ⑥ ХУУЛГЫН ТОЛГОЙ — бичлэгийн хувилбар (2026-10-05). Нэг хувилбарыг л хайснаас
  //    болж зарлага чимээгүй 0 болж, гүйлгээ ОРОХГҮЙ байв.
  ok(/деб\[еи\]т/.test(src), 'scan: зарлагын багана «дебет» БА «дебит» хоёуланг таана');
  ok(/огноо\|өдөр\|date/.test(src), 'scan: огнооны багана «өдөр» хэлбэрийг ч таана');
  ok(/parseWarn\.length \? parseWarn\.join/.test(src),
     'scan: толгой танигдаагүй шалтгаан импортын цонхонд ил гарна');
}
testFinBasisDefault();

// ═══ САР ХААХ (2026-09-11) ════════════════════════════════════════════════════
// Хуучин сарын тоо ямар ч үед өөрчлөгдөж, «өнгөрсөн сард харсан тайлан» хүчингүй
// болдог байв. Хаасан сар хөдөлөхгүй; алдаа гарвал дараагийн сард залруулга.
{
  need(['monthIsClosed', 'monthLocked', 'assertMonthOpen', 'closeMonthBlockers', 'setMonthClosed']);
  const runIn = (code) => vm.runInContext(code, sandbox);

  eq(F.monthIsClosed({ '2026-08': { at: 'x' } }, '2026-08'), true, 'сар хаах: хаасан сар танигдана');
  eq(F.monthIsClosed({ '2026-08': { at: 'x' } }, '2026-09'), false, 'сар хаах: бусад сар хөндөгдөхгүй');
  eq(F.monthIsClosed({}, '2026-08'), false, 'сар хаах: хоосон тохиргоо → хаалттай биш');
  eq(F.monthIsClosed(null, ''), false, 'сар хаах: хоосон оролт → хаалттай биш');
  // Огноо (YYYY-MM-DD) дамжуулсан ч сарыг л хардаг
  eq(F.monthIsClosed({ '2026-08': {} }, '2026-08-14'), true, 'сар хаах: бүтэн огноо ч сараар шалгагдана');

  // ── Түгжээ: бичилт ЧИМЭЭГҮЙ бүтэлгүйтэхгүй, ТОДОРХОЙ мессежтэй унана ──
  {
    const saved = runIn('state.closedMonths');
    runIn("state.closedMonths = { '2026-08': { at: '2026-09-01T00:00:00Z', by: 'ceo' } };");
    eq(F.monthLocked('2026-08'), true, 'түгжээ: хаасан сар түгжигдсэн');
    eq(F.monthLocked('2026-09'), false, 'түгжээ: нээлттэй сар чөлөөтэй');
    let msg = '';
    try { F.assertMonthOpen('2026-08', 'зардлын бичилт'); } catch (e) { msg = e.message; }
    ok(/2026-08/.test(msg) && /хаагдсан/.test(msg) && /зардлын бичилт/.test(msg),
       'түгжээ: мессеж нь сар, шалтгаан, юу хийж чадахгүйг хэлнэ → ' + msg);
    let threw = false;
    try { F.assertMonthOpen('2026-09', 'зардлын бичилт'); } catch (e) { threw = true; }
    eq(threw, false, 'түгжээ: нээлттэй сард бичилт зогсохгүй');
    try { F.assertMonthOpen('', 'x'); } catch (e) { threw = true; }
    eq(threw, false, 'түгжээ: огноогүй бичилт хаагдахгүй (чимээгүй блоклохгүй)');
    runIn('state.closedMonths = ' + JSON.stringify(saved === undefined ? null : saved) + ';');
  }

  // ── Хаахад бэлэн эсэх: дутуу хуулга · хаагдаагүй орлого · залгааны эвдрэл ──
  {
    const stmts = [{ id: '504|2026-08-01|2026-08-31', acct: '504', ccy: 'MNT',
      period_from: '2026-08-01', period_to: '2026-08-31', opening: 0, closing_stated: 100, closing_calc: 100 }];
    const income = [{ fp: 'i1', dt: '2026-08-05', amount: 700000, status: 'open' },
      { fp: 'i2', dt: '2026-08-06', amount: 300000, status: 'order' },
      { fp: 'i3', dt: '2026-07-06', amount: 900000, status: 'open' }];

    eq(F.closeMonthBlockers(stmts, [], ['504'], '2026-08'), [], 'хаах: хуулга бүрэн, хаагдаагүй мөр алга → бэлэн');
    // ⛔ Ангилаагүй зардал нь баталгаажуулах цонхонд ИЛ бичигдэнэ
    eq(F.closeMonthBlockers(stmts, [], ['504'], '2026-08', 62).map(x => x.kind), ['pending'],
       'хаах: ангилаагүй зардал саад болно');
    eq((F.closeMonthBlockers(stmts, [], ['504'], '2026-08', 62).find(b => b.kind === 'pending') || {}).n, 62,
       'хаах: хэдэн гүйлгээ ангилаагүйг хэлнэ');
    eq(F.closeMonthBlockers(stmts, [], ['504'], '2026-08', 0), [], 'хаах: ангилаагүй 0 бол саад биш');

    const b1 = F.closeMonthBlockers(stmts, income, ['504'], '2026-08');
    eq(b1.map(x => x.kind), ['income'], 'хаах: хаагдаагүй орлого нь саад');
    eq([b1[0].n, b1[0].sum], [1, 700000], 'хаах: зөвхөн ТУХАЙН сарын хаагдаагүй мөр тоологдоно');

    const b2 = F.closeMonthBlockers(stmts, [], ['504', '300'], '2026-08');
    eq(b2.map(x => x.kind), ['stmt'], 'хаах: дансны хуулга дутуу нь саад');
    eq(b2[0].accts, ['300'], 'хаах: аль данс дутуу гэдгийг нэрлэнэ');

    // Тэнцлийн зөрүү — тухайн сарын хуулганд
    const bad = [{ ...stmts[0], closing_calc: 90 }];
    /* ⛔ ТЭНЦЛИЙН ЗӨРҮҮ нь «ЗАЛГАА» БИШ (2026-10-02) — хоёр нь хоёр өөр ажил:
       залгаа тасарсан бол ДУТУУ ХУУЛГА оруулна, тэнцэл зөрсөн бол оруулсан
       хуулгын МӨР дутуу уншигдсан. Нэг нэрээр нэрлэвэл хүнд буруу заавар хүрнэ. */
    eq(F.closeMonthBlockers(bad, [], ['504'], '2026-08').map(x => x.kind), ['balance'],
       'хаах: хуулгын тэнцэл зөрвөл саад (залгаа БИШ, тэнцэл гэж нэрлэгдэнэ)');
    eq(F.closeMonthBlockers(bad, [], ['504'], '2026-08')[0].accts, ['504'],
       'хаах: аль дансны тэнцэл зөрснийг нэрлэнэ');

    /* ⭐ ХУВИЙН дансны зөрүү сар хаахыг БЛОКЛОХГҮЙ. `regAccts` = компанийн данс
       (`companyAcctList()` хувийн дансыг хасдаг) тул залгааны шалгуур ч түүгээр
       хязгаарлагдана. Өмнө нь «дутуу хуулга» шалгуур хувийн дансыг хасдаг байтал
       залгааны шалгуур хасдаггүй байсан — зөрчил. */
    const prsn = [stmts[0], { id: '99|2026-08-01|2026-08-31', acct: '9911223344', ccy: 'MNT',
      period_from: '2026-08-01', period_to: '2026-08-31', opening: 0, closing_stated: 100, closing_calc: -434583 }];
    eq(F.closeMonthBlockers(prsn, [], ['504'], '2026-08'), [],
       'хаах: хувийн дансны тэнцлийн зөрүү сар хаахыг блоклохгүй');
    eq(F.closeMonthBlockers(prsn, [], ['504', '9911223344'], '2026-08').map(x => x.kind), ['balance'],
       'хаах: тэр данс КОМПАНИЙНХ бол дахин саад болно');
    // ӨӨР сарын эвдрэл нь энэ сарыг хаахад саад БОЛОХГҮЙ
    const other = [{ ...stmts[0], id: '504|2026-06-01|2026-06-30', period_from: '2026-06-01', period_to: '2026-06-30', closing_calc: 90 }];
    eq(F.closeMonthBlockers(other, [], [], '2026-08'), [], 'хаах: өөр сарын эвдрэл энэ сарыг хорихгүй');
  }

  // ── SCAN: түгжээ бичих БҮХ гол замд тавигдсан хэвээр ──
  {
    const gate = (fn, needle) => {
      const at = src.indexOf(fn);
      ok(at > 0, 'scan: ' + fn + ' олдов');
      ok(new RegExp(needle).test(src.slice(at, at + 1400)), `scan: ${fn} — хаасан сарын түгжээ тавигдсан`);
    };
    gate('async function saveFinanceRequest', 'assertMonthOpen');
    gate('async function setIncomeStatus', 'assertMonthOpen');
    // ⚠ Хуулгын импорт нь МӨРӨӨР шүүнэ (assertMonthOpen БИШ) — нэг хуулга 2 сарыг
    //   хамардаг нь хэвийн, бүхэлдээ татгалзвал хилээр дамжсан хуулга орж чадахгүй.
    gate('async function persistStatement', 'monthLocked');
    gate('async function submitBqPayment', 'monthLocked');
    gate('async function clearMonthExpenses', 'monthLocked');
    // Кэш бичихээс ӨМНӨ шалгана — эс бөгөөс локал кэш хаасан сарыг дарна
    const sf = src.slice(src.indexOf('async function saveFinanceRequest'), src.indexOf('async function saveFinanceRequest') + 1400);
    ok(sf.indexOf('assertMonthOpen') < sf.indexOf('saveFinanceCache'),
       'scan: түгжээ нь localStorage кэш бичихээс ӨМНӨ шалгагдана');
    // Эхлэхэд ачаалагдана — эс бөгөөс түгжээ «нээлттэй» гэж андуурна
    ok(/loadClosedMonths\(\);/.test(src), 'scan: хаасан сар эхлэхэд ачаалагдана');
  }
}

// ═══ ДОТООД ШИЛЖҮҮЛГИЙГ БҮРТГЭСЭН ДАНСААР ТАНИХ (2026-09-11) ══════════════════
// Орлогын тал нь дотоод шилжүүлгийг ЗӨВХӨН гүйлгээний утга/нэрээр таьдаг байв
// («данс хооронд», «Чимун»). Нэр хоосон ирсэн өөрийн шилжүүлэг «орлого» болж,
// тулгалтын «Банкны нийт орлого» хөөрөгдөж байсан. Зардлын импорт аль хэдийн
// бүртгэсэн дансаар (isInternalTransfer) таьдаг — орлого одоо ижил дүрэмтэй.
{
  need(['creditIsInternal', '_isInternalCredit', 'isInternalTransfer', 'reconcileByReceipts']);
  const own = new Set(['5041234567', '3001234567']);

  // ⭐ Гол кейс: нэр ХООСОН, утга ХООСОН — зөвхөн данснаас нь таних
  const blank = { date: '2026-08-04', credit: 200000, name: '', memo: '', account: '5041234567' };
  eq(F._isInternalCredit(blank), false, 'дотоод: үг-суурьтай хуучин аргад нэр хоосон мөр ТАНИГДАХГҮЙ (алдааны эх)');
  eq(F.creditIsInternal(blank, own), true, 'дотоод: бүртгэсэн данснаас нь танигдана');

  // Данс нь сүүлийн 10 оронгоор ч таарна (IBAN/угтвартай хэлбэр)
  eq(F.creditIsInternal({ credit: 1, name: '', memo: '', account: '99 5041234567' }, own), true,
     'дотоод: сүүлийн 10 оронгоор таарна');

  // Бодит харилцагчийн төлбөр = ОРЛОГО хэвээр (хэт их хасаж орлого нуухгүй)
  eq(F.creditIsInternal({ credit: 500000, name: 'Бат', memo: 'түрээс', account: '5049999999' }, own), false,
     'дотоод: харилцагчийн төлбөр орлого хэвээр');
  // Үг-суурьтай нөөц хэвээр ажиллана (данс бүртгэгдээгүй ч)
  eq(F.creditIsInternal({ credit: 9, name: 'ЧИМУН ХХК', memo: '', account: '7777777777' }, own), true,
     'дотоод: нэрээр таних нөөц хэвээр (данс бүртгэгдээгүй ч)');
  eq(F.creditIsInternal({ credit: 9, name: '', memo: 'данс хооронд', account: '7777777777' }, own), true,
     'дотоод: утгаар таних нөөц хэвээр');
  // Хэт богино/хоосон данс нь «өөрийн данс» гэж андуурагдахгүй
  eq(F.creditIsInternal({ credit: 9, name: 'Дорж', memo: 'төлбөр', account: '' }, own), false,
     'дотоод: данс хоосон + утга цэвэр → орлого');

  // ── Тулгалт ч ижил дүрмээр: нэргүй дотоод шилжүүлэг орлогод ОРОХГҮЙ ──
  {
    const rows = [
      { date: '2026-08-02', credit: 500000, debit: 0, name: 'Бат', account: '5049999999', memo: 'түрээс' },
      { date: '2026-08-04', credit: 200000, debit: 0, name: '', account: '5041234567', memo: '' },   // өөрийн данс
    ];
    const res = F.reconcileByReceipts(rows, { own, usedFps: new Set(), fpOwners: new Map() });
    eq(res.incomeCount, 1, 'тулгалт: нэргүй дотоод шилжүүлэг орлогын мөрд тоологдохгүй');
    eq(res.untracked.map(c => c.credit), [500000], 'тулгалт: зөвхөн бодит төлбөр үлдэнэ');
  }

  // ── SCAN: дүрэм дахин тархахгүй — үг-суурьтай шалгалтыг ШУУД дуудахгүй ──
  {
    const calls = [...src.matchAll(/_isInternalCredit\(/g)].length;
    eq(calls, 2, 'scan: _isInternalCredit нь тодорхойлолт + creditIsInternal дотор ЗӨВХӨН (шууд дуудалт байхгүй)');
    const at = src.indexOf('function creditIsInternal');
    ok(/isInternalTransfer\(r, set\)/.test(src.slice(at, at + 400)),
       'scan: ганц дүрэм нь бүртгэсэн дансыг шалгана');
  }
}

// ═══ ХУВИЙН ДАНСНЫ ХУУЛГА — ирэлт нь КОМПАНИЙН ОРЛОГО БИШ (2026-09-11) ════════
// Эзний хувийн дансны хуулгад цалин, найзын шилжүүлэг, өөрийн хооронд зөөлт гэх
// мэт хэдэн арван ирэлт байдаг. Тэдгээрийг «хаагдаагүй орлого» болговол эзэн сар
// бүр гараар хааж хөөцөлдөх ба сар хаагдахгүй болно.
{
  need(['buildStatementImport', 'incomeOpenStats']);
  const meta = { acct: '9001112222', period: '2026-08-01 - 2026-08-31', opening: 0, closing: 0 };
  const parsed = { ccy: 'MNT', rows: [
    { date: '2026-08-03', credit: 2500000, debit: 0, name: 'ЧИМУН ХХК-ийн НЯГТЛАН', account: '4004004004', memo: 'цалин' },
    { date: '2026-08-10', credit: 150000, debit: 0, name: 'Найз', account: '8008008008', memo: 'зээл буцаав' },
    { date: '2026-08-15', credit: 900000, debit: 0, name: '', account: '5041234567', memo: '' },   // КОМПАНИЙН данснаас
    { date: '2026-08-20', credit: 0, debit: 300000, name: 'Дэлгүүр', account: '1', memo: 'хүнс' },
  ] };
  const company = new Set(['5041234567']);

  // ── ХУВИЙН данс ──
  const prsn = F.buildStatementImport(parsed, meta, { personal: true, company, own: new Set(['9001112222']) });
  const byMemo = {}; prsn.incomes.forEach(x => { byMemo[x.memo] = x; });
  eq(F.incomeOpenStats(prsn.incomes).n, 0, '🙍 хувийн данс: ХААГДААГҮЙ мөр 0 (эзэн хувийн гүйлгээг хөөцөлдөхгүй)');
  eq(byMemo['цалин'].status, 'personal', '🙍 хувийн данс: цалин = хувийн, компанийн орлого биш');
  eq(byMemo['зээл буцаав'].status, 'personal', '🙍 хувийн данс: найзын шилжүүлэг = хувийн');
  eq(byMemo[''].status, 'internal', '🙍 компанийн данснаас ирсэн нь нөхөн олголт (дотоод, орлого биш)');
  ok(/нөхөн олголт/.test(byMemo[''].note), '🙍 нөхөн олголт гэж бичигдэнэ');
  // Хуулгын нийт дүн нь ХЭВЭЭР бүртгэгдэнэ (дансны хөдөлгөөн, тэнцлийн шалгуурт хэрэгтэй)
  eq(prsn.stmt.credit_total, 3550000, '🙍 хувийн данс: хуулгын нийт ирэлт бүртгэгдсэн хэвээр (тэнцэл шалгагдана)');
  eq(prsn.stmt.debit_total, 300000, '🙍 хувийн данс: зарлага ч бүртгэгдэнэ');

  // ── ИЖИЛ хуулга КОМПАНИЙН данс байвал → хаагдаагүй орлого болно ──
  const comp = F.buildStatementImport(parsed, meta, { personal: false, company, own: new Set(['9001112222']) });
  // «цалин» мөрийн нэрэнд ЧИМУН байгаа тул үг-суурьтай нөөц дүрмээр `internal` болно;
  // үлдсэн 2 мөр (найзын 150,000 + нэргүй 900,000) хаагдаагүй орлого болж эзэн шийднэ.
  eq(F.incomeOpenStats(comp.incomes).n, 2, 'компанийн данс: 2 мөр хаагдаагүй болж эзэн шийднэ');
  eq(F.incomeOpenStats(comp.incomes).sum, 1050000, 'компанийн данс: хаагдаагүй дүн');
  eq(comp.incomes.find(x => x.memo === 'цалин').status, 'internal', 'компанийн данс: «ЧИМУН» нэртэй мөр дотоод гэж танигдана');

  // ── SCAN: хувийн дансны тугийг дамжуулахаа болихгүй ──
  {
    const at = src.indexOf('async function persistStatement');
    const body = src.slice(at, at + 900);
    ok(/personal: isPersonalAcct\(meta\.acct\)/.test(body), 'scan: хувийн дансны туг импортод дамжина');
    ok(/company: companyAcctSet\(\)/.test(body), 'scan: компанийн дансны багц дамжина (нөхөн олголтыг таних)');
    ok(/personal: '🙍/.test(src) && /notincome: '🚫/.test(src), 'scan: шинэ 2 төлөвийн шошго бий');
  }
}

// ═══ БУРУУ ДАРСНАА ОЛОХ + БУЦААХ (2026-09-11) ════════════════════════════════
// Орлогын мөрийг хаамагц «хаагдаагүй» жагсаалтаас гардаг тул буруу тэмдэглэгээ
// ХАРАГДАХГҮЙ, буцаах ч аргагүй болдог байв. Амьд датаас 2 бодит түрээсийн орлого
// «дотоод шилжүүлэг»/«бусад орлого» болж нуугдсаныг барьсан.
{
  need(['incomeManualRows', 'incomeOpenStats']);
  const rows = [
    { fp: 'a', dt: '2026-09-11', amount: 3960000, payer: 'МАЙНС АП ХХК', status: 'internal', decided_by: '88006790', decided_at: '2026-09-11T08:00:25Z' },
    { fp: 'b', dt: '2026-09-10', amount: 475200, payer: 'ВАЙРАЛ', status: 'other', decided_by: '88006790', decided_at: '2026-09-11T08:00:34Z' },
    { fp: 'c', dt: '2026-09-01', amount: 100000, payer: 'Бат', status: 'order', decided_by: null, note: 'баримт FP-…' },   // АВТО
    { fp: 'd', dt: '2026-08-20', amount: 200000, payer: '', status: 'personal', decided_by: null },                        // АВТО
    { fp: 'e', dt: '2026-08-13', amount: 132000, payer: 'ГҮНЖ', status: 'open', decided_by: null },
  ];
  const man = F.incomeManualRows(rows);
  eq(man.map(r => r.fp), ['b', 'a'], 'буцаах: гараар шийдсэн мөр л гарна, сүүлд шийдсэн нь дээр');
  ok(!man.some(r => r.status === 'order' || r.status === 'personal'),
     'буцаах: АВТО тэмдэглэгдсэн мөр жагсаалтад ОРОХГҮЙ (хэдэн зуу мөр дүүргэхгүй)');

  // Буцаасны дараа: «гараар шийдсэн»-ээс гарч, «хаагдаагүй»-д орно
  const after = rows.map(r => (r.fp === 'a' ? { ...r, status: 'open' } : r));
  eq(F.incomeManualRows(after).map(r => r.fp), ['b'], 'буцаах: буцаасан мөр шийдсэн жагсаалтаас гарна');
  eq(F.incomeOpenStats(after).n, 2, 'буцаах: буцаасан мөр хаагдаагүй болж эзэн дахин шийднэ');
  eq(F.incomeManualRows([]), [], 'буцаах: хоосон → хоосон');

  // SCAN — ↩ товч ба handler хэвээр
  ok(/data-inc-undo=/.test(src), 'scan: ↩ буцаах товч бий');
  ok(/data-inc-undo\]'\)\.forEach/.test(src), 'scan: ↩ товчинд handler холбогдсон');
  ok(/setInc\(b\.dataset\.incUndo, 'open'/.test(src), 'scan: буцаахад мөр «хаагдаагүй» болно');
}

// ═══ ЭЦСИЙН ҮЛДЭГДЭЛ ФАЙЛЫН ДООД ТАЛД (2026-09-11) ═══════════════════════════
// Толгойн 14 мөрийг л хайснаас болж оруулсан 3 хуулгын 2-т closing_stated ХООСОН
// болж, «эхний + орлого − зарлага = эцсийн» шалгуур ОГТ ажиллахгүй байв — хуулга
// бүтэн орсон эсэхийг шалгах гол хэмжүүр хоосон байсан.
{
  need(['statementMeta', 'stmtBalanceCheck']);
  const hdr = (extra) => [
    ['Дансны дугаар', '', '3635161180'],
    ['Гүйлгээний огноо', '', '2026-08-01 - 2026-08-31'],
    ['Эхний үлдэгдэл', '', '6739312'],
    ...(extra || []),
    ['Огноо', 'Гүйлгээний утга', 'Орлого', 'Зарлага', 'Үлдэгдэл'],
    ['2026-08-02', 'түрээс', '500000', '', '7239312'],
    ['2026-08-03', 'хүнс', '', '100000', '7139312'],
  ];

  // ⚠ УРТ файл (амьд хуулга 557 мөртэй): эцсийн үлдэгдэл нь толгойн 14 мөрөөс
  //   ХОЛ доор байдаг тул зөвхөн СҮҮЛийг хайж байж олно.
  const many = []; for (let i = 1; i <= 40; i++) many.push([`2026-08-${String(i % 28 + 1).padStart(2, '0')}`, 'гүйлгээ ' + i, '1000', '', '7239312']);
  const long1 = F.statementMeta([...hdr(), ...many, ['', '', '', 'Эцсийн үлдэгдэл', '7139312']]);
  eq(long1.closing, 7139312, 'хуулга: 40+ мөртэй файлын ХАМГИЙН ДООД эцсийн үлдэгдэл уншигдана');
  eq(long1.opening, 6739312, 'хуулга: урт файлд эхний үлдэгдэл ч хэвээр');
  eq(F.statementMeta([...hdr(), ...many]).closing, null, 'хуулга: эцсийн үлдэгдэлгүй урт файл → null (таамаглахгүй)');

  // ① Эцсийн үлдэгдэл ДООД талд (Голомтын бодит хэлбэр)
  const m1 = F.statementMeta([...hdr(), ['', '', '', 'Эцсийн үлдэгдэл', '7139312']]);
  eq(m1.opening, 6739312, 'хуулга: эхний үлдэгдэл толгойноос');
  eq(m1.closing, 7139312, 'хуулга: ЭЦСИЙН үлдэгдэл файлын ДООД талаас уншигдана');
  eq(m1.acct, '3635161180', 'хуулга: данс уншигдана');
  eq(m1.period, '2026-08-01 - 2026-08-31', 'хуулга: хугацаа уншигдана');

  // ② Толгойд байвал бас уншина (хуучин зан төлөв эвдрээгүй)
  eq(F.statementMeta(hdr([['Эцсийн үлдэгдэл', '', '7139312']])).closing, 7139312,
     'хуулга: толгойд байгаа эцсийн үлдэгдэл хэвээр уншигдана');

  // ③ Утга нь шошгоос ЗҮҮН талд (Голомт заримдаа ингэдэг)
  eq(F.statementMeta([...hdr(), ['7139312', 'Эцсийн үлдэгдэл']]).closing, 7139312,
     'хуулга: утга шошгоос ӨМНӨ байсан ч уншигдана');

  // ④ Гүйлгээний «Үлдэгдэл» БАГАНА эцсийн үлдэгдэл гэж андуурагдахгүй
  eq(F.statementMeta(hdr()).closing, null, 'хуулга: «Үлдэгдэл» багана шошго гэж андуурагдахгүй');

  // ⑤ Зөрүүтэй хуулга — тэнцэл УНАНА (мөр дутуу уншигдсаныг барина)
  const bad = F.statementMeta([...hdr(), ['', '', '', 'Эцсийн үлдэгдэл', '9999999']]);
  const chk = F.stmtBalanceCheck({ ccy: 'MNT', opening: bad.opening, closing_stated: bad.closing,
    closing_calc: bad.opening + 500000 - 100000 });
  eq(chk.ok, false, 'хуулга: эцсийн үлдэгдэл зөрвөл тэнцэл УНАНА');
  eq(chk.diff, 7139312 - 9999999, 'хуулга: зөрүүний дүн гарна');

  // ⑥ Толгой ба сүүл давхцах жижиг файлд 2 удаа уншиж эвдрэхгүй
  eq(F.statementMeta([['Эхний үлдэгдэл', '100'], ['Эцсийн үлдэгдэл', '200']]).closing, 200,
     'хуулга: жижиг файлд ч ажиллана');

  // SCAN — сүүл хайх нь хэвээр
  ok(/rows\.slice\(Math\.max\(14, rows\.length - 20\)\)/.test(src),
     'scan: файлын СҮҮЛийг ч хайдаг хэвээр (эцсийн үлдэгдэл доор байдаг)');
}

// ═══ ШИЛЖИЛТИЙН ХИЛ: хуулга МӨРӨӨР алгасна (2026-09-11) ══════════════════════
// Нэг хуулга 2 сарыг хамардаг нь хэвийн (жиш. 08-01…09-11). Хаасан сар таарвал
// файлыг бүхэлдээ татгалзвал хилээр дамжсан хуулга ОРОХ БОЛОМЖГҮЙ болно.
{
  const at = src.indexOf('async function persistStatement');
  const body = src.slice(at, at + 1600);
  ok(!/assertMonthOpen/.test(body),
     'хил: хуулгыг бүхэлдээ татгалзахаа больсон (assertMonthOpen хасагдсан)');
  ok(/filter\(x => !monthLocked\(String\(x\.dt/.test(body),
     'хил: хаасан сарын ОРЛОГЫН МӨР л алгасагдана');
  ok(/saveStatementImport\(built\.stmt, fresh\)/.test(body),
     'хил: хуулгын мөр (нийт дүн, үлдэгдэл) ҮРГЭЛЖ бичигдэнэ — залгааны шалгуурт хэрэгтэй');
  ok(/skippedClosed/.test(body), 'хил: алгасагдсан мөрийн тоо буцна (чимээгүй алга болохгүй)');
}

// ═══ ШИЛЖИЛТИЙН ХААЛТ — «N сараас өмнөх БҮГД» (2026-09-11) ═══════════════════
// Хэрэглэгчийн шийдвэр: түүхийг дахин бичихгүй, 8 сар ба өмнөхийг хүчээр хааж,
// 9 сараас шинэ дүрмээр цэвэр эхлэх. Сар бүрийг нэг бүрчлэн хаах нь утгагүй
// (Booqable түүх 3 сараас хойш) тул нэг «шилжилт» тэмдэглэгээгээр хаана.
{
  need(['monthIsClosed', 'monthCloseInfo', 'setCutover']);
  const cut = { __cutover: { before: '2026-09', at: '2026-09-11T10:00:00Z', by: '88006790' } };

  eq(monthIsClosedAll(cut, ['2026-03', '2026-06', '2026-08']), true, 'шилжилт: 9 сараас өмнөх БҮХ сар хаалттай');
  eq(F.monthIsClosed(cut, '2026-09'), false, 'шилжилт: 9 сар НЭЭЛТТЭЙ (шинэ дүрэм эндээс)');
  eq(F.monthIsClosed(cut, '2026-10'), false, 'шилжилт: дараагийн сарууд нээлттэй');
  eq(F.monthIsClosed(cut, '2025-12'), true, 'шилжилт: өнгөрсөн жил ч хаалттай');
  eq(F.monthIsClosed(cut, '2026-08-14'), true, 'шилжилт: бүтэн огноо ч сараар шалгагдана');
  function monthIsClosedAll(cfg, months) { return months.every(m => F.monthIsClosed(cfg, m)); }

  // Хоёр хэлбэр зэрэг: шилжилт + дараа нь сараар хаасан
  const both = { ...cut, '2026-09': { at: '2026-10-01T00:00:00Z', by: 'x' } };
  eq(F.monthIsClosed(both, '2026-09'), true, 'хоёулаа: 9 сарыг дараа нь сараар хаасан');
  eq(F.monthIsClosed(both, '2026-10'), false, 'хоёулаа: 10 сар нээлттэй хэвээр');

  // Дэлгэрэнгүй — хэрэглэгчид ЯАГААД хаалттайг тайлбарлана
  eq(F.monthCloseInfo(cut, '2026-08').kind, 'cutover', 'дэлгэрэнгүй: шилжилтээр хаагдсан гэж хэлнэ');
  eq(F.monthCloseInfo(both, '2026-09').kind, 'month', 'дэлгэрэнгүй: сараар хаагдсаныг ялгана');
  eq(F.monthCloseInfo(cut, '2026-09'), null, 'дэлгэрэнгүй: нээлттэй сард хоосон');
  eq(F.monthCloseInfo({}, '2026-08'), null, 'дэлгэрэнгүй: хаалтгүй бол хоосон');
  eq(F.monthIsClosed({ __cutover: {} }, '2026-01'), false, 'шилжилт: before хоосон бол хаахгүй (санамсаргүй бүх түүх хаагдахгүй)');

  // SCAN
  ok(/__cutover/.test(src) && /async function setCutover/.test(src), 'scan: шилжилтийн хаалт кодод бий');
  ok(/const before = nextMonthStr\(m\);/.test(src),
     'scan: «m ба өмнөх бүгд» = before нь ДАРААГИЙН сар (m өөрөө хаагдана)');
  const tg = src.slice(src.indexOf('async function toggleMonthClose'), src.indexOf('async function toggleMonthClose') + 3000);
  ok(/Зөвхөн \$\{m\}/.test(tg), 'scan: хүрээ сонгох диалог бий (зөвхөн энэ сар / бүгд)');
  ok(/setCutover\('', ''\)/.test(tg), 'scan: шилжилтийг буцааж авах зам бий');
}

// ═══ ХААСАН САРЫН ЗАХИАЛГА + ХУУЧИРСАН ТҮГЖЭЭ (2026-09-11) ═══════════════════
// Хоёр нүх: ① захиалга устгах/цуцлах нь түгжээгүй байсан — хаасан сарын орлого
// чимээгүй буурах боломжтой. ② түгжээ зөвхөн эхлэхэд ачаалагддаг тул хаалт өөр
// сессээс тавигдвал ажиллаж байгаа апп мэдэхгүй, бичилт чөлөөтэй өнгөрнө.
{
  need(['orderStatusTouchesMoney', 'orderLockedMonth', 'assertMonthOpenLive', 'loadClosedMonths']);
  const runIn = (code) => vm.runInContext(code, sandbox);

  // ── ① Ямар төлөв солилт мөнгө хөнддөг ──
  eq(F.orderStatusTouchesMoney('rented', 'deleted'), true, 'төлөв: устгах нь мөнгө хөндөнө');
  eq(F.orderStatusTouchesMoney('reserved', 'canceled'), true, 'төлөв: цуцлах нь мөнгө хөндөнө');
  eq(F.orderStatusTouchesMoney('deleted', 'reserved'), true, 'төлөв: СЭРГЭЭХ нь ч мөнгө хөндөнө (орлого буцаж орно)');
  eq(F.orderStatusTouchesMoney('preparation', 'ready'), false, 'төлөв: дамжлагын шат мөнгө хөнддөггүй → хоригдохгүй');
  eq(F.orderStatusTouchesMoney('rented', 'returned'), false, 'төлөв: буцаан авах мөнгө хөнддөггүй');
  eq(F.orderStatusTouchesMoney('deleted', 'deleted'), false, 'төлөв: ижил төлөв → хөдөлгөөн биш');

  // ── Захиалгын мөнгө аль сард сууж байна (хоёр суурь хоёулаа шалгагдана) ──
  {
    const saved = runIn('state.closedMonths');
    runIn("state.closedMonths = { __cutover: { before: '2026-09' } };");
    // Эвент 9 сард, мөнгө 8 сард орсон → 8 сар хаалттай тул ХОРИГЛОНО
    eq(F.orderLockedMonth({ starts_at: '2026-09-20', paid_date: '2026-08-30' }), '2026-08',
       'захиалга: мөнгө орсон сар хаалттай бол хоригдоно');
    // Эвент 8 сард, мөнгө 9 сард → эвентийн сар хаалттай тул мөн хоригдоно
    eq(F.orderLockedMonth({ starts_at: '2026-08-20', paid_date: '2026-09-02' }), '2026-08',
       'захиалга: эвентийн сар хаалттай бол ч хоригдоно (гүйцэтгэлийн суурь)');
    eq(F.orderLockedMonth({ starts_at: '2026-09-20', paid_date: '2026-09-02' }), '',
       'захиалга: хоёр сар нээлттэй → чөлөөтэй');
    runIn('state.closedMonths = ' + JSON.stringify(saved === undefined ? null : saved) + ';');
  }

  // ── ② Түгжээ TTL-тэй: хуучирвал өөрөө шинэчилнэ ──
  ok(/const CLOSED_M_TTL/.test(src), 'түгжээ: TTL тодорхойлогдсон');
  {
    const fn = src.slice(src.indexOf('async function loadClosedMonths'), src.indexOf('async function loadClosedMonths') + 500);
    ok(/Date\.now\(\) - state\._closedMonthsAt\) < CLOSED_M_TTL/.test(fn),
       'түгжээ: хуучирсан эсэхийг цагаар шалгана (зөвхөн «байгаа эсэх»-ээр биш)');
    ok(/state\._closedMonthsAt = Date\.now\(\)/.test(fn), 'түгжээ: ачаалсан цаг тэмдэглэгдэнэ');
  }

  // ── SCAN: устгах 2 замд түгжээ тавигдсан ──
  {
    const gate = (fn, needle) => {
      const at = src.indexOf(fn); ok(at > 0, 'scan: ' + fn + ' олдов');
      ok(new RegExp(needle).test(src.slice(at, at + 1500)), `scan: ${fn} — хаасан сарын түгжээ бий`);
    };
    gate('async function bulkDeleteOrders', 'orderLockedMonth');
    gate('async function bqUpdateStatus', 'orderStatusTouchesMoney');
    // Түгжээг шалгахын ӨМНӨ серверээс шинэчилнэ (хуучирсан кэшээр гаргахгүй)
    const bq = src.slice(src.indexOf('async function bqUpdateStatus'), src.indexOf('async function bqUpdateStatus') + 1500);
    ok(bq.indexOf('loadClosedMonths(true)') < bq.indexOf('orderLockedMonth'),
       'scan: түгжээ шалгахын өмнө серверээс шинэчилнэ');
  }
}

// ═══ «БОЛЬСОН» — ЗӨВХӨН ГАРААР, ТӨЛБӨР ОРВОЛ СЭРГЭНЭ (2026-09-27) ════════════
// Хоёр нүх байв: ① `autoCleanExpiredOrders` нь эвентийн огноо өнгөрсөн, төлбөргүй
// захиалгыг АВТОМАТААР `deleted` болгож DB-д бичдэг байсан — хүн эргэлзсэн, хойшлогдсон,
// эсвэл бэлнээр төлөгдсөн жинхэнэ захиалга чимээгүй «Больсон» руу унаж, хэн ч
// мэдэхгүй байв (сессэд нэг удаа, зөвшөөрөл асуухгүй). Хэлцэл больсон эсэхийг
// ЗӨВХӨН хүн мэднэ → зөвхөн гараар, шалтгаантай. ② «Больсон» захиалгад төлбөр орвол
// тэр нь больсон гэдэг БУРУУ байсны нотолгоо — захиалга буцаж орох ёстой.
{
  need(['orderReviveStatus']);

  // ── ① Авто-больсон ЭРГЭЖ ИРЭХГҮЙ ──
  {
    const codeLines = src.split('\n').filter(l => !/^\s*(\/\/|\*)/.test(l)).join('\n');
    eq((codeLines.match(/autoCleanExpiredOrders/g) || []).length, 0,
       'scan: хугацаа хэтэрсэн захиалгыг АВТО «Больсон» болгодоггүй (зөвхөн гараар)');
    eq((codeLines.match(/_expiredCleaned/g) || []).length, 0,
       'scan: авто-больсоны төлөв үлдээгүй');
    // Захиалгыг «Больсон» болгох цорын ганц зам = шалтгаан асуудаг гар урсгал
    ok(/ORDER_CX_REASONS/.test(codeLines), 'scan: больсон/цуцлах шалтгааны сонголт хэвээр');
  }

  // ── ② Сэргэх төлөв: өнгөрсөн эвент → Дууссан, ирээдүйн → Захиалсан ──
  eq(F.orderReviveStatus({ starts_at: '2026-08-01', stops_at: '2026-08-03' }, '2026-09-27'), 'returned',
     'сэргээх: өнгөрсөн эвент → Дууссан');
  eq(F.orderReviveStatus({ starts_at: '2026-10-05', stops_at: '2026-10-07' }, '2026-09-27'), 'reserved',
     'сэргээх: ирээдүйн эвент → Захиалсан');
  eq(F.orderReviveStatus({ starts_at: '2026-09-27' }, '2026-09-27'), 'reserved',
     'сэргээх: ӨНӨӨДӨР болох эвент → Захиалсан (дуусаагүй)');
  eq(F.orderReviveStatus({ starts_at: '2026-09-20', stops_at: '2026-09-28' }, '2026-09-27'), 'reserved',
     'сэргээх: дуусах огноо нь шийднэ (эхэлсэн ч дуусаагүй → Захиалсан)');
  eq(F.orderReviveStatus({}, '2026-09-27'), 'reserved',
     'сэргээх: огноогүй бол Захиалсан — чимээгүй «Дууссан» болгож нуухгүй');
  // Сэргээх нь ORDER_BUCKETS-ийн жинхэнэ бүлэг рүү л орно (танигдахгүй төлөв үүсгэхгүй)
  ['returned', 'reserved'].forEach(st => eq(F.bucketOf(st) === 'done' || F.bucketOf(st) === 'active', true,
     `сэргээх: '${st}' нь ажлын бүлэгт (Дууссан/Захиалсан) орно`));

  // ── ③ Төлбөрийн зам «Больсон»-г сэргээнэ + хаасан сарын түгжээтэй ──
  {
    const at = src.indexOf('async function submitBqPayment');
    ok(at > 0, 'scan: submitBqPayment олдов');
    const fn = src.slice(at, src.indexOf('\n}', at));
    // ⚠ Зөвхөн «функц дурдагдсан» биш — ТӨЛӨВ үнэхээр түүнээс тооцогдохыг шалгана
    //   (эс бөгөөс түгжээний мөрөнд дурдагдсан хэвээр байхад сэргээлт чимээгүй унтарна).
    ok(/const newStatus = [^;]*orderReviveStatus\(o\)/.test(fn),
       'scan: төлбөр орвол «Больсон» сэргэнэ (шинэ төлөв orderReviveStatus-аас)');
    ok(/orderLockedMonth\(o\)/.test(fn) && /orderStatusTouchesMoney/.test(fn),
       'scan: сэргээх нь мөнгө хөндөнө → хаасан сарын түгжээ шалгагдана');
    ok(fn.indexOf('loadClosedMonths(true)') < fn.indexOf('orderLockedMonth'),
       'scan: түгжээ шалгахын өмнө серверээс шинэчилнэ');
    // Товч нь «Больсон» захиалгад ч гарна — эс бөгөөс сэргээх зам хаалттай
    const pay = src.slice(src.indexOf('const appCanPay'), src.indexOf('const appCanPay') + 200);
    eq(/st !== 'deleted'/.test(pay), false,
       'scan: «Больсон» захиалгад төлбөр бүртгэх товч гарна (сэргээх ганц зам)');
    ok(/st !== 'canceled'/.test(pay), 'scan: «Цуцалсан»-д төлбөр бүртгэхгүй хэвээр');
  }
}

// ═══ «БОЛЬСОН»-ООС БУЦААХ ЗАМ (2026-09-27) ═══════════════════════════════════
// Төлбөр орвол сэргэдэг болсон ч БҮРЭН ТӨЛӨГДСӨН захиалга гацдаг байв: үлдэгдэл 0
// тул төлбөрийн товч гарахгүй, картан дээр «Сэргээх» ч байхгүй — цорын ганц зам нь
// жагсаалтын багц-сонголт байв (амьд датаар #1559 яг ингэж гацсан). Түүнчлэн
// `bulkRestoreOrders` нь БҮГДИЙГ 'reserved' болгодог тул өнгөрсөн эвент ажлын
// жагсаалтад мөнхөд үлдэж, хаасан сарын түгжээ ч огт шалгагддаггүй байв.
{
  need(['orderReviveStatus', 'bulkRestoreOrders', 'restoreOneOrder']);
  const fn = src.slice(src.indexOf('async function bulkRestoreOrders'),
                       src.indexOf('async function bulkRestoreOrders') + 2200);

  // ── ① Сэргээх нь мөнгө хөндөнө → устгахтай ИЖИЛ түгжээ ──
  ok(/orderLockedMonth\(o\)/.test(fn), 'scan: сэргээхэд хаасан сарын түгжээ шалгагдана');
  ok(fn.indexOf('loadClosedMonths(true)') < fn.indexOf('orderLockedMonth'),
     'scan: түгжээ шалгахын өмнө серверээс шинэчилнэ');

  // ── ② Зорилтот төлөв = orderReviveStatus, хатуу 'reserved' БИШ ──
  ok(/orderReviveStatus\(o\)/.test(fn), 'scan: сэргээх төлөв orderReviveStatus-аас');
  eq(/status: 'reserved'/.test(fn), false,
     'scan: бүгдийг хатуугаар «Захиалсан» болгохгүй (өнгөрсөн эвент Дууссан руу)');

  // ── ③ Картан дээр буцаах товч — багц-сонголтгүйгээр ──
  ok(/data-app-restore=/.test(src), 'scan: «Больсон» картад ↩ Сэргээх товч бий');
  ok(/\[data-app-restore\]/.test(src), 'scan: тэр товч холбогдсон');
  // Ганц сэргээлт нь багцын ижил функцийг дуудна (дүрэм хоёр газар салбарлахгүй)
  const one = src.slice(src.indexOf('async function restoreOneOrder'),
                        src.indexOf('async function restoreOneOrder') + 700);
  ok(/bulkRestoreOrders\(/.test(one), 'scan: ганц сэргээлт багцын дүрмийг дуудна');
  ok(/showConfirm\(/.test(one), 'scan: сэргээхийн өмнө баталгаажуулна');
}

// ═══ «БОЛЬСОН» БОЛГОХ БҮХ ЗАМ ШАЛТГААН БИЧНЭ (2026-09-27) ═══════════════════
// Картын товч шалтгаан асуудаг байтал БАГЦ товч ба тест-цэвэрлэгээ асуудаггүй
// байв — амьд датаар 54 «Больсон»-ы 30 нь шалтгаангүй, «яагаад захиалга алдаж
// байна» гэдгийг тоолж чадахгүй байв (#1559 ч яг ингэж ороод гацсан).
{
  need(['setCancelReason', 'cxReasonKey', 'bulkDeleteOrders']);
  // Тойм үндсэн ажилтанд ОЛДОХ ёстой: доод цэсэнд + эхний дэлгэц; цагийн ажилтанд нуугдана (2026-10-05, CEO)
  {
    const fs_ = require('fs'), path_ = require('path');
    const ih = fs_.readFileSync(path_.join(__dirname, '..', 'index.html'), 'utf8');
    const cs = fs_.readFileSync(path_.join(__dirname, '..', 'styles.css'), 'utf8');
    ok(/class="mobile-nav-item[^"]*" data-view="dashboard"/.test(ih), 'scan: Тойм доод цэсэнд байна');
    ok(/body\.role-daily \.mobile-nav-item\[data-view="dashboard"\]/.test(cs), 'scan: цагийн ажилтанд доод цэсний Тойм нуугдана');
    // Зан чанар: CEO «Үндсэн» болгосон (override) ажилтан — override ХОЖУУ ирэхэд цэс нээгдэж Тойм руу шилжинэ
    {
      const _T = vm.runInContext('TEAM', sandbox); const save = _T.slice(); _T.length = 0;
      _T.push({ name: 'Override Ажилтан', phone: '99887766', status: 'идэвхтэй', role: 'Агуулахын ажилтан', worker_type: 'daily' });
      vm.runInContext("state.isCEO = false; state.me = '99887766'; state.user = { worker_type: 'daily' }; state._wtOverrides = {}; document.body.classList.remove('role-daily');", sandbox);
      vm.runInContext('applyRoleUi(true)', sandbox);
      eq(vm.runInContext('state.view', sandbox), 'myattend', 'төрөл: цагийн ажилтан Миний ирцээс эхэлнэ');
      vm.runInContext("state._wtOverrides = { '99887766': 'permanent' }; applyWorkerTypeOverrides(); applyRoleUi();", sandbox);
      eq(vm.runInContext('state.view', sandbox), 'dashboard', 'төрөл: override хожуу ирэхэд үндсэн ажилтан Тойм руу шилжинэ');
      eq(vm.runInContext("document.body.classList.contains('role-daily')", sandbox), false, 'төрөл: override ирэхэд цагийн ажилтны цэсний хориг арилна');
      vm.runInContext("state.view = 'orders'; state._wtOverrides = {}; TEAM[0].worker_type = 'daily'; state.user.worker_type = 'daily'; applyRoleUi(); state._wtOverrides = { '99887766': 'permanent' }; applyWorkerTypeOverrides(); applyRoleUi();", sandbox);
      eq(vm.runInContext('state.view', sandbox), 'orders', 'төрөл: хүн өөр дэлгэц рүү шилжсэн бол эхлэх дэлгэц рүү татахгүй');
      _T.length = 0; save.forEach(x => _T.push(x));
      vm.runInContext("state._wtOverrides = undefined; state.view = 'mine';", sandbox);
    }
  }
  // Гүйлгээ — зөвхөн бүх санхүүг хардаг хүнд (2026-10-05, CEO). Цэс нуугдана + шууд нээж чадахгүй.
  {
    ok(/if \(state\.view === 'finance' && !canSeeAllFinance\(\)\) state\.view = 'mine';/.test(src),
       'scan: санхүүгийн эрхгүй хүн Гүйлгээ рүү орж чадахгүй (render хамгаалалт)');
    const sb = src.slice(src.indexOf('function renderSidebar()'), src.indexOf('function renderSidebar()') + 20000);
    ok(/const _finOk = canSeeAllFinance\(\);[\s\S]{0,200}mobile-nav-item\[data-view="finance"\]/.test(sb),
       'scan: Гүйлгээ хажуугийн БА доод цэснээс эрхгүй хүнд нуугдана');
    const _T = vm.runInContext('TEAM', sandbox); const save = _T.slice(); _T.length = 0;
    _T.push({ name: 'Энгийн Ажилтан', phone: '99001122', status: 'идэвхтэй', role: 'Агуулахын ажилтан' });
    vm.runInContext("state.isCEO = false; state.me = '99001122'; state.finBranchPerms = new Set();", sandbox);
    eq(vm.runInContext('canSeeAllFinance()', sandbox), false, 'Гүйлгээ: энгийн ажилтан санхүүг бүхэлд нь харахгүй');
    vm.runInContext("state.finBranchPerms = new Set(['99001122']);", sandbox);
    eq(vm.runInContext('canSeeAllFinance()', sandbox), true, 'Гүйлгээ: салбар засах эрхтэй ажилтан харна');
    _T[0].status = 'гарсан';
    eq(vm.runInContext('canSeeAllFinance()', sandbox), false, 'Гүйлгээ: ажлаас гарсан хүний салбар засах эрх хүчингүй');
    _T.length = 0; save.forEach(x => _T.push(x));
    vm.runInContext("state.finBranchPerms = undefined;", sandbox);
  }
  // Утас солигдоход бүх холбоос шилжинэ — db/person_rekey.sql (2026-10-05, CEO: «дахин дахин таарч байна»)
  {
    const fs_ = require('fs'), path_ = require('path');
    const rk = fs_.readFileSync(path_.join(__dirname, '..', 'db', 'person_rekey.sql'), 'utf8');
    ok(/create trigger employees_rekey_trg after update of phone, merged_into on employees/.test(rk),
       'person_rekey: утас солих/нэгтгэх үед trigger ажиллана');
    // Апп утсаар хүн холбодог гол хүснэгтүүд жагсаалтад заавал байна — нэгийг мартвал тэр нь хоцорно
    const must = ['staff_salary', 'salary_payments', 'member_perms', 'member_branches', 'attendance',
                  'push_subscriptions', 'employee_docs', 'fin_branch_perm', 'stage_meta', 'app_config', 'att_requests', 'evaluations'];
    const miss = must.filter(x => rk.indexOf(x) < 0);
    eq(miss.join(','), '', 'person_rekey: утсаар холбогддог гол хүснэгт бүгд хамрагдсан');
    ok(!/'customers'\s*,\s*'phone'|\('app_orders'\s*,\s*'phone'\)|\('pbx_calls'/.test(rk),
       'person_rekey: харилцагчийн утас ба дуудлагын лог хөндөгдөхгүй');
  }
  // Буцаан авалт: ДУТУУ = алдагдал — хадгалахаас ӨМНӨ асууна (2026-10-05, #1476 худал 840k алдагдал)
  {
    const i = src.indexOf('if (_shortLines.length) {\n      const _nS');
    const j = src.indexOf('sm2[act.key] = entry;');
    ok(i > 0 && i < j, 'scan: дутуу бүртгэхээс ӨМНӨ анхааруулга асууна (нөөцөд бичихээс өмнө)');
    ok(/if \(!\(await showConfirm\(`⚠ \$\{_nS\} ширхэг ДУТУУ/.test(src) && /\)\)\) return;\n    \}\n    sm2\[act\.key\] = entry;/.test(src),
       'scan: «Буцаж засах» дарвал хадгалахгүй (хариуг шалгана)');
  }
  // «Больсон» болгох цорын ганц бичих зам = bulkDeleteOrders (шалтгаантай). Шалтгаангүй
  // ганц-устгах зам (deleteAppOrder) ба тест-цэвэрлэгээний цонх 2026-10-05-нд хасагдсан.
  ok(!/function deleteAppOrder|function openTestCleanupModal/.test(src),
     'scan: шалтгаангүй устгах хуучин зам буцаж ирэхгүй');

  // ── ① Багц устгал шалтгааныг захиалга БҮРД бичнэ ──
  {
    const fn = src.slice(src.indexOf('async function bulkDeleteOrders'),
                         src.indexOf('async function bulkDeleteOrders') + 2400);
    ok(/async function bulkDeleteOrders\(ids, reason\)/.test(src),
       'scan: багц устгал шалтгаан хүлээж авна');
    ok(/setCancelReason\(o\.note, reason\)/.test(fn),
       'scan: шалтгаан захиалга бүрийн тэмдэглэлд бичигдэнэ');
    // note мөр бүрт өөр тул НЭГ багц PATCH-аар бичиж БОЛОХГҮЙ
    eq(/id=in\.\(/.test(fn), false,
       'scan: багц PATCH БИШ — note мөр бүрт өөр тул нэг нэгээр бичнэ');
  }

  // ── ② Багц товч шалтгаан АСУУНА ──
  {
    const at = src.indexOf("getElementById('bulk-delete')");
    ok(at > 0, 'scan: багц «Больсон» товч олдов');
    const h = src.slice(at, at + 1200);
    ok(/pickCancelReason\(/.test(h), 'scan: багц «Больсон» шалтгаан асууна');
    ok(/if \(!reason\) return;/.test(h), 'scan: шалтгаангүй бол устгахгүй');
    ok(h.indexOf('pickCancelReason') < h.indexOf('bulkDeleteOrders'),
       'scan: шалтгааныг устгахаас ӨМНӨ асууна');
  }

  // ── ④ «Тест захиалга» = админ шалтгаан → алдагдлын шинжилгээнд ОРОХГҮЙ ──
  eq(F.cxReasonKey(F.setCancelReason('', 'Тест захиалга')), 'Тест захиалга',
     'шалтгаан: тэмдэглэлд бичээд буцааж уншина');
  eq(F.cxIsAdmin(F.setCancelReason('', 'Тест захиалга')), true,
     'шалтгаан: «Тест захиалга» = админ (алдсан борлуулалтад тоологдохгүй)');
  eq(F.cxIsAdmin(F.setCancelReason('', 'Өөр компаниас авсан')), false,
     'шалтгаан: жинхэнэ алдагдал админ БИШ');
  // Токен бичихэд захиалгын бусад токен эвдэрдэггүй
  {
    const before = '⟦DLV|city|0|150000⟧ ⟦LEAD|repeat⟧';
    const after = F.setCancelReason(before, 'Арга хэмжээ болсонгүй');
    ok(after.includes('⟦DLV|city|0|150000⟧') && after.includes('⟦LEAD|repeat⟧'),
       'шалтгаан: бусад токен эвдрэхгүй');
    eq(F.cxReasonKey(after), 'Арга хэмжээ болсонгүй', 'шалтгаан: буцааж уншигдана');
  }
}

// ═══════════════ SERVICE WORKER — «апп харагдана ч юу ч дарагдахгүй» (2026-09-11) ═══
// Хэрэглэгчийн гомдол: «Апп юу ч дарагдахгүй апп хөдлөхгүй байна».
// Шалтгаан: `fetch` нь 404/503-д reject ХИЙДЭГГҮЙ — resolve болдог. sw.js тэр хариуг
// хуудсанд шууд дамжуулж байсан тул GitHub Pages deploy-ийн хиккапт app.js-ийн оронд
// алдааны HTML ирж, апп бүтнээрээ ХАРАГДАЖ (index.html кэшээс) товч бүр үхмэл болдог.
// Алдааны бүртгэгч нь app.js дотор тул серверт ч юу ч бүртгэгддэггүй байв.
// Кэшэд бүтэн хувилбар байхад л хэрэглэгч үхмэл апп хардаг байсныг эндээс барина.
async function swFetchTests() {
  const swSrc = fs.readFileSync(path.join(__dirname, '..', 'sw.js'), 'utf8');

  const mkRes = (status, body) => {
    const r = { ok: status >= 200 && status < 300, status, body, clone: () => mkRes(status, body) };
    return r;
  };
  // caches mock — нэрээр store, store дотор url→Response
  function mkCaches(seed) {
    const stores = new Map([['seed', new Map(Object.entries(seed || {}))]]);
    const find = (url, ignoreSearch) => {
      const bare = (u) => String(u).split('?')[0];
      for (const st of stores.values()) {
        if (st.has(url)) return st.get(url);
        if (ignoreSearch) { for (const [k, v] of st) if (bare(k) === bare(url)) return v; }
      }
      return undefined;
    };
    return {
      stores,
      open: (name) => Promise.resolve({
        addAll: () => Promise.resolve(),
        put: (req, res) => { if (!stores.has(name)) stores.set(name, new Map()); stores.get(name).set(req.url || String(req), res); return Promise.resolve(); },
        keys: () => Promise.resolve([]),
        match: (req, o) => Promise.resolve(find(req.url || String(req), o && o.ignoreSearch)),
      }),
      keys: () => Promise.resolve([...stores.keys()]),
      delete: () => Promise.resolve(true),
      match: (req, o) => Promise.resolve(find(req.url || String(req), o && o.ignoreSearch)),
    };
  }
  // sw.js-г ачаалж fetch handler-ыг гаргаж авна
  function loadSw({ seed, netFor }) {
    const listeners = {};
    const caches = mkCaches(seed);
    const box = {
      console, setTimeout, clearTimeout, Promise, URL, URLSearchParams, Object, Array, String, Number, JSON, Date, Math, Error,
      caches,
      fetch: (req) => netFor(req.url || String(req)),
      Response,   // жинхэнэ SW-д байдаг — offlineResponse() үүнийг ашиглана
      self: null,
    };
    box.self = box;
    box.globalThis = box;
    box.location = { origin: 'https://chimunllc.github.io', href: 'https://chimunllc.github.io/chimun-tasks/' };
    box.addEventListener = (ev, fn) => { listeners[ev] = fn; };
    box.registration = { showNotification: () => Promise.resolve() };
    box.clients = { matchAll: () => Promise.resolve([]), claim: () => Promise.resolve(), openWindow: () => Promise.resolve() };
    box.skipWaiting = () => Promise.resolve();
    vm.createContext(box);
    vm.runInContext(swSrc, box, { filename: 'sw.js' });
    return {
      caches,
      // хүсэлт → SW-ийн буцаасан хариу
      go(url, mode) {
        const req = { url, method: 'GET', mode: mode || 'cors' };
        let out;
        listeners.fetch({ request: req, respondWith: (p) => { out = p; } });
        return Promise.resolve(out);
      },
    };
  }

  const APPJS = 'https://chimunllc.github.io/chimun-tasks/app.js';
  const PAGE  = 'https://chimunllc.github.io/chimun-tasks/index.html';
  const cachedApp = mkRes(200, 'CACHED-APPJS');
  const cachedPage = mkRes(200, 'CACHED-HTML');
  const seed = { [APPJS]: cachedApp, [PAGE]: cachedPage, 'https://chimunllc.github.io/chimun-tasks/': cachedPage };

  // ① ЯДРАЛ: Pages 503 буцаасан ч кэшэд бүтэн app.js байвал ТҮҮНИЙГ өгнө
  {
    const sw = loadSw({ seed, netFor: () => Promise.resolve(mkRes(503, '503 Service Unavailable')) });
    const r = await sw.go(APPJS);
    eq(r && r.body, 'CACHED-APPJS', 'sw: app.js 503 → кэшлэгдсэн бүтэн хувилбар (апп үхэхгүй)');
    ok(r && r.ok === true, 'sw: буцаасан хариу хүчинтэй (ok) байна');
  }
  // ② 404 (deploy дунд) — ижил
  {
    const sw = loadSw({ seed, netFor: () => Promise.resolve(mkRes(404, 'not found')) });
    eq((await sw.go(APPJS)).body, 'CACHED-APPJS', 'sw: app.js 404 → кэшээс');
  }
  // ③ Хэвийн 200 — сүлжээний ШИНЭ хувилбар хүрнэ (кэш хуучныг дардаггүй)
  {
    const sw = loadSw({ seed, netFor: () => Promise.resolve(mkRes(200, 'FRESH-APPJS')) });
    eq((await sw.go(APPJS)).body, 'FRESH-APPJS', 'sw: 200 → сүлжээний шинэ код (кэш хоцрохгүй)');
  }
  // ④ Офлайн (fetch reject) — кэшээс
  {
    const sw = loadSw({ seed, netFor: () => Promise.reject(new Error('offline')) });
    eq((await sw.go(APPJS)).body, 'CACHED-APPJS', 'sw: офлайн → кэшээс');
  }
  // ⑤ Кэш ХООСОН + 503 — өөр гарц байхгүй тул 503-ыг дамжуулна (гэхдээ хуудас
  //    index.html-ээ ч авахгүй тул хэрэглэгч «дарагдахгүй апп» БИШ, хоосон хардаг)
  {
    const sw = loadSw({ seed: {}, netFor: () => Promise.resolve(mkRes(503, 'oops')) });
    const r = await sw.go(APPJS);
    ok(r && r.status === 503, 'sw: кэш хоосон + 503 → хариуг дамжуулна (нуухгүй)');
  }
  // ⑥ `app.js?v=123` — query-тэй хүсэлт precache-тай таарна (ignoreSearch)
  {
    const sw = loadSw({ seed, netFor: () => Promise.resolve(mkRes(503, 'oops')) });
    eq((await sw.go(APPJS + '?v=999')).body, 'CACHED-APPJS', 'sw: query-тэй app.js ч кэштэй таарна');
  }
  // ⑦ Хуудас (navigate) 503 — index.html кэшээс
  {
    const sw = loadSw({ seed, netFor: () => Promise.resolve(mkRes(503, 'oops')) });
    eq((await sw.go('https://chimunllc.github.io/chimun-tasks/', 'navigate')).body, 'CACHED-HTML',
       'sw: хуудас 503 → кэшлэгдсэн index.html');
  }
  // ── ГАДНЫ хүсэлт: SW барих ЁСГҮЙ (2026-09-12) ────────────────────────────
  // DB API-г барьж, сүлжээ тасрахад fetch reject болж respondWith унаснаас
  // «FetchEvent.respondWith received an error» гарч «Миний ирц» 10 удаа хоосон
  // харагдсан. Кэшлэдэггүй тул барих нь ямар ч ашиггүй.
  {
    const DBQ = 'https://n8n.nomaadcamp.com/db/rest/v1/attendance?member_key=in.(1)';
    const sw = loadSw({ seed, netFor: () => Promise.reject(new Error('offline')) });
    eq(await sw.go(DBQ), undefined, 'sw: DB API хүсэлтийг ОГТ барихгүй (браузерт үлдээнэ)');
    const sw2 = loadSw({ seed, netFor: () => Promise.resolve(mkRes(200, 'OK')) });
    eq(await sw2.go('https://lh3.googleusercontent.com/x.jpg'), undefined, 'sw: гадны зургийг барихгүй');
  }

  // ── respondWith ХЭЗЭЭ Ч undefined/reject болохгүй ────────────────────────
  // `caches.match` олдохгүй бол undefined буцаадаг. respondWith(undefined) =
  // хуудсанд ойлгомжгүй алдаа. Бүх салаа бодит Response буцаана.
  {
    const sw = loadSw({ seed: {}, netFor: () => Promise.reject(new Error('offline')) });
    const r = await sw.go('https://n8n.nomaadcamp.com/webhook/bootstrap');
    ok(r && typeof r.status === 'number', 'sw: webhook офлайн + кэшгүй → Response буцаана');
    const r2 = await sw.go('https://chimunllc.github.io/chimun-tasks/icon.svg');
    ok(r2 && typeof r2.status === 'number', 'sw: өөрийн asset офлайн + кэшгүй → Response буцаана');
  }

  // ⑧ SCAN: shell салбар дээр уналт ХОЁР замд (resolve БА reject) байх ёстой
  {
    const at = swSrc.indexOf('if (isHTML || isAppShell)');
    const blk = swSrc.slice(at, at + 1600);
    ok((blk.match(/shellFallback\(/g) || []).length >= 2,
       'scan: sw — 404/503 (resolve) БА сүлжээ унасан (reject) ХОЁУЛАА кэш рүү уналттай');
    ok(!/\.then\(\(res\) => res\)[\s\S]{0,40}catch\(\(\) => caches\.match\(req\)\)\s*\)\s*;?\s*\n\s*return;\s*\n\s*}\s*\n\s*\/\/ NETWORK-FIRST/.test(swSrc),
       'scan: sw — shell салбар хариуг шалгалтгүй дамжуулдаггүй');
  }
  // ⑨ SCAN: app.js ачаалагдсаныг index.html хянадаг (үхмэл апп чимээгүй үлдэхгүй)
  {
    const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
    ok(/__appJsLoaded/.test(html), 'scan: index.html — app.js ачаалагдсаныг шалгадаг хянагч бий');
    ok(/Дахин ачаалах/.test(html), 'scan: index.html — хэрэглэгчид «Дахин ачаалах» гарц бий');
    ok(/app_errors/.test(html), 'scan: index.html — үхмэл ачаалалт серверт бүртгэгдэнэ');
    // Хянагч нь app.js-ийн ДАРАА байх ёстой (script дараалан ажилладаг тул дохиог
    // тэр цагт найдвартай шалгана). Өмнө байвал үргэлж «үхсэн» гэж буудна.
    ok(html.indexOf('__appJsLoaded') > html.indexOf('<script src="app.js">'),
       'scan: index.html — хянагч app.js-ийн ДАРАА ажиллана');
    ok(!/setTimeout\([\s\S]{0,400}__appJsLoaded/.test(html),
       'scan: index.html — хянагч хугацаагаар таадаггүй (сул сүлжээнд худал дуугарна)');
    ok(/^window\.__appJsLoaded = true;$/m.test(src), 'scan: app.js — ачаалагдсан дохиогоо тавьдаг');
  }
}

// SCAN — захиалгын мөрөнд тооцоологдсон шошго заавал РЕНДЕРЛЭГДЭНЭ (2026-09-12)
// Алдаа: `quoteChip` («📭 Илгээгээгүй») бодогдоод `_chips` массивт ороогүй байв.
// Улмаар дүнгийн мөрөнд «2 илгээгээгүй» гэж гарч байхад мөр дээр тэмдэг гарахгүй,
// хэрэглэгч аль захиалга нь болохыг олж чадахгүй байсан. CSS нь бүрэн бэлэн байсан —
// зөвхөн нэг массивт нэр дутсан. Энэ нь чимээгүй унадаг ангийн алдаа.
// Дүрэм: orderListRow доторх `const *Chip` бүр `_chips` жагсаалтад байх ёстой.
{
  const fn = src.slice(src.indexOf('function orderListRow('), src.indexOf('const ORDER_TIME_GROUPS'));
  ok(fn.length > 500, 'scan: orderListRow олдов');
  const declared = [...fn.matchAll(/const\s+(\w+Chip)\s*=/g)].map(m => m[1]);
  ok(declared.length >= 5, 'scan: мөрийн шошгууд тодорхойлогдсон (' + declared.length + ')');
  const line = (fn.match(/const _chips = .*/) || [''])[0];
  ok(!!line, 'scan: _chips жагсаалт олдов');
  const missing = declared.filter(n => !line.includes(n));
  eq(missing.length, 0, 'scan: тооцоолсон шошго бүр _chips-д орсон' +
     (missing.length ? ' → дутуу: ' + missing.join(', ') : ''));
  ok(line.includes('quoteChip'), 'scan: «Илгээгээгүй» шошго мөрөнд гарна');
}


// ── ХАРИЛЦАГЧИЙН БҮРТГЭЛ (2026-09-13) ───────────────────────────────────
{
  const PK = vm.runInContext('custPhoneKey', sandbox);
  // Утасны нормчлол — db/customers.sql-ийн cust_phone_norm()-тэй ИЖИЛ байх ёстой.
  eq(PK('99001122'), '99001122', 'харилцагч: 8 орон хэвээр');
  eq(PK('976 9900 1122'), '99001122', 'харилцагч: 976 угтвар хасагдана');
  eq(PK('+976-9900-1122'), '99001122', 'харилцагч: тэмдэгт цэвэрлэгдэнэ');
  eq(PK('099001122'), '99001122', 'харилцагч: 0 угтвар хасагдана');
  eq(PK('123'), '', 'харилцагч: богино дугаар → хоосон');
  eq(PK(''), '', 'харилцагч: хоосон → хоосон');
  eq(PK(null), '', 'харилцагч: null → хоосон');
  eq(PK('9900112233445'), '', 'харилцагч: хэт урт → хоосон (таамаглахгүй)');

  const MT = vm.runInContext('custMatches', sandbox);
  const c = { name: 'Б.Болд', phone: '99001122', company: 'Ай Ти ХХК', rd: 'УК12345678', email: 'b@x.mn' };
  ok(MT(c, ''), 'харилцагч: хоосон хайлт бүгдийг өгнө');
  ok(MT(c, 'болд'), 'харилцагч: нэрээр олдоно');
  ok(MT(c, 'ай ти'), 'харилцагч: компаниар олдоно');
  ok(MT(c, 'УК123'), 'харилцагч: РД-гаар олдоно');
  ok(MT(c, '9900-1122'), 'харилцагч: зураастай утсаар ч олдоно');
  ok(!MT(c, 'гэрэл'), 'харилцагч: таарахгүй хайлт хасагдана');

  const SORT = vm.runInContext('custSortRows', sandbox);
  const sorted = SORT([
    { name: 'A', owed: 0, last: '2026-01-01' },
    { name: 'B', owed: 500, last: '2025-01-01' },
    { name: 'C', owed: 0, last: '2026-05-01' },
  ]);
  eq(sorted.map(x => x.name), ['B', 'C', 'A'], 'харилцагч: өртэй нь эхэнд, дараа нь сүүлд захиалсан');

  // ИНВАРИАНТ: харилцагчийн авлага = Авлага дэлгэцийн тоо.
  // Хоёр газар өөр дүрэм бичигдвэл энэ тест УНАНА (CLAUDE.md: авлагын ганц дүрэм).
  const CS = vm.runInContext('custStats', sandbox);
  const RD = vm.runInContext('receivablesData', sandbox);
  const st = vm.runInContext('state', sandbox);
  const saved = { ao: st.appOrders, no: st.nomaadOrders };
  st.nomaadOrders = [];
  const orders = [
    { id: '1', number: 1, customer_id: 'c_a', status: 'returned',  total_mnt: 500000, paid_mnt: 200000 },
    { id: '2', number: 2, customer_id: 'c_a', status: 'archived',  total_mnt: 300000, paid_mnt: 300000 },
    { id: '3', number: 3, customer_id: 'c_b', status: 'reserved',  total_mnt: 900000, paid_mnt: 0 },
    { id: '4', number: 4, customer_id: 'c_b', status: 'deleted',   total_mnt: 400000, paid_mnt: 0 },
    { id: '5', number: 5, customer_id: null,  status: 'returned',  total_mnt: 700000, paid_mnt: 100000 },
  ];
  st.appOrders = orders;
  const byCust = CS(orders, 'cash');
  const custOwed = [...byCust.values()].reduce((s, x) => s + x.owed, 0);
  const rdOwed = RD().items.filter(i => i.branch === 'bq')
    .filter(i => (orders.find(o => String(o.id) === String(i.id)) || {}).customer_id)
    .reduce((s, i) => s + i.balance, 0);
  eq(custOwed, rdOwed, 'ИНВАРИАНТ: харилцагчийн авлага = Авлага дэлгэцийн тоо');
  eq((byCust.get('c_a') || {}).orders, 2, 'харилцагч: идэвхтэй захиалга тоологдоно');
  ok(!byCust.has(null), 'харилцагч: customer_id-гүй захиалга бүлэглэгдэхгүй');
  eq((byCust.get('c_b') || {}).orders, 1, 'харилцагч: больсон захиалга тоонд ОРОХГҮЙ');
  st.appOrders = saved.ao; st.nomaadOrders = saved.no;
}

// scan: харилцагчийн авлагыг түүхий тоогоор БҮҮ бод — orderOwed/canon төлөв ашигла.
{
  const fn = src.slice(src.indexOf('function custStats('), src.indexOf('function custMatches('));
  ok(fn.length > 200, 'scan: custStats олдов');
  ok(/orderOwed\(/.test(fn), 'scan: харилцагчийн үлдэгдэл orderOwed-оор бодогдоно');
  ok(/RECEIVABLE_ORDER_ST/.test(fn), 'scan: харилцагчийн авлага канон төлөвөөр шүүгдэнэ');
  ok(/orderRevenue\(/.test(fn), 'scan: харилцагчийн орлого orderRevenue-аар бодогдоно');
  ok(!/total_mnt\s*-\s*|paid_mnt\s*\)/.test(fn.replace(/orderOwed\([^)]*\)/g, '')),
     'scan: custStats-д түүхий total_mnt − paid_mnt тооцоо алга');
}

// Рендэр — загвар эвдэрвэл (хаалт дутуу, тодорхойгүй хувьсагч) энд унана.
