  ok(/fmtMoney\(histOnly \? paid : b\.total\)/.test(rs), 'scan: түүх сард хураангуйд ОЛГОСОН дүн гарна');
  const mp = src.slice(src.indexOf('function myPayCardHtml'), src.indexOf('function renderMyAttend'));
